    public string Name() { return name; }
    public int Army() { return army; }
    public Point3d Pos() { return pos; }
    public bool IsAlive() { return true; }
    public bool IsValid() { return true; }
    public bool IsTaskComplete() { return true; }
    public double CoverageR() { return 1200; }
    public double FieldR() { return 1200; }
	
    public int ParkCountR() { return 0; }
    public int ParkCountFree() { return 0; }
    public int ParkCountAll() { return 0; }
    public maddox.game.world.AiActor[] QueueLanding() { return null; }
    public maddox.game.world.AiActor[] QueueTakeoff() { return null; }
    public maddox.game.world.AiGroup Group() { return null; }
    public int StripCount() { return 1; }
    public double StripDirection(int i) { return 0; }
    public double StripLength(int i) { return 0; }
    public int StripState(int i) { return 0; }
    public double StripWidth(int i) { return 0; }
    public int Type() { return 0; }
	public int ChooseStripForTakeoff() { return 0; } //added 2026/06 for new CloD version/update
    

    Random ran = new Random();

    public aAiAirport()
    {
        ap = null;
        name = "aAirfield_" + ran.Next(999).ToString();
        army = 0;
        pos = new Point3d(0, 0, 0);

    }
    public aAiAirport(aAiAirport a)
    {
        ap = a;
        name = a.Name();
        army = a.Army();
        pos = a.Pos();

    }
    public aAiAirport(maddox.game.world.AiAirport a)
    {
        ap = a;
        name = a.Name();
        army = a.Army();
        pos = a.Pos();

    }

    public aAiAirport(string name, int army, Point3d pos
        )
    {
        this.name = name;
        this.army = army;
        this.pos = pos;
    }

    public aAiAirport(maddox.game.world.AiAirport ap, string name, int army, Point3d pos
        )
    {
        this.ap = ap;
        this.name = name;
        this.army = army;
        this.pos = pos;
    }

