            }

        }
        catch (Exception ex) { System.Console.WriteLine("Main mission - read sessstats.txt - Exception: " + ex.ToString()); }
        */

        StatsMission.Stb_PlayerSessStat BS = statsmission.stb_SaveIPlayerStat.BlueSessStats;
