                    //northerly: 350582, 301410
                    new Point2d (350582, 301410),
                    new Point2d (358080,247296),
                    },


                };
            }

            //For whatever reason max/min map state is like 10000, 20000, 30000
            //but corresponding CampaignMapState is 100, 200, 300 etc
            //these are the numbers where the front line will be fully right on the original far north Red or far south Blue front lines we drew on each side of the channel.
            double minMapState_int = minMapState_ext / 100;
            double maxMapState_int = maxMapState_ext / 100;
            double campaign_offset_int = campaign_offset_ext / 100;
          
            ISectionFile f = GamePlay.gpCreateSectionFile();
            if (f2 == null) f2 = GamePlay.gpCreateSectionFile();
            string sect;
            string key;
            string value;
            int count = 0;

            double mapState = CampaignMapState;
            if (currMapState.HasValue) mapState = currMapState.Value;

            mapState += campaign_offset_int; //2024-03-19, allows us to make 0 points/start point offset from the center of the Channel.  This offset would be set on a per-campaign basis.

            double neutral = (maxMapState_int - minMapState_int) / 120;
            double neutral_width_m = 2000; //Was 5000, now (2023/10/28) changed to 2500; 2024/03/19 changed to 2000 (bec now removing ALL OBJECTS from the neutral zone)

            //This makes the front start to creep much more slowly once it hits "land"
            //2022-12, added the 0.9 business because we are SMOOTHING the map & adding a bit of neutral territory between red & blue, so keeping the line just a bit more offshore
            //2023-01-10 --> this WAS the equation for map front lines
            /*
            if (mapState > 0.85 * maxMapState) mapState = maxMapState + (mapState - 0.9 * maxMapState) / 4; //2022-07-31: was 20, now 19.  2022-12, now 15.  This is to make it a bit easier to move the front line onto land
            if (mapState < 0.85 * minMapState) mapState = minMapState + (minMapState - 0.9 * mapState) / 4; 
            */
            Console.WriteLine("Frontline: mapState {0:F2}  maxMapState_ext {1:F2} minMapState_ext {2:F2}", mapState, maxMapState_ext, minMapState_ext);
            //This is the CORRECT way, we can do it after Jubilee is done
            double slowdownpoint = 1;
            double slowdownrate = 3;
            if (mapState > slowdownpoint * maxMapState_int) mapState = maxMapState_int * slowdownpoint + (mapState - slowdownpoint * maxMapState_int) / slowdownrate; //2022-07-31: was 20, now 19.  2022-12, now 15.  This is to make it a bit easier to move the front line onto land
            if (mapState < slowdownpoint * minMapState_int) mapState = minMapState_int * slowdownpoint + (mapState - slowdownpoint * minMapState_int) / slowdownrate;


            double mult_north = (mapState - neutral - minMapState_int) / (maxMapState_int - minMapState_int);  //mult is for red frontline (most northerly)
            double mult_south = (mapState + neutral - minMapState_int) / (maxMapState_int - minMapState_int);  //mult2 for blue, most southerly 

            double mult_neut = (mapState - minMapState_int) / (maxMapState_int - minMapState_int);  //mult_neut is halfway between the two, the 'neutral line'.
            Console.WriteLine("Frontline: mapState corrected {0:F2}  maxMapState_int {1:F2} minMapState_int {2:F2}", mapState, maxMapState_int, minMapState_int);
            Console.WriteLine("Frontline: mult_north {0:F2}  mult_south {1:F2} mult_neut {2:F2}", mult_north, mult_south, mult_neut);

            /*if (mult > 1) mult = 1; //We COULD go beyond 0-1 but that might get weird.  So the Frontlines are drawn using a weird thing where the front goes halfway between p1 and p2 and PERPENDICULAR to the line from p1 to p2.  So we have to pay attention to make sure p1 & p2 form the right sort of line going the right direction.
            if (mult < 0) mult = 0;
            if (mult2 > 1) mult2 = 1; //We COULD go beyond 0-1 but that might get weird
            if (mult2 < 0) mult2 = 0;
            */
            //Now it will advance front onto land but it will move much more slowly
            /* Now we're doing this with mapState instead of here
            if (mult > 1) mult = (mult - 1) / 20 + 1; //it advances, but 20X slower

            if (mult < 0)  mult = mult/20; 

            if (mult2 > 1) mult2 = (mult2 - 1) / 20 + 1; //We COULD go beyond 0-1 but that might get weird
            if (mult2 < 0) mult2 = mult2/20;
            */

            if (mult_south == mult_north) mult_south = mult_north + 0.05; //They can't be equal or HELP!!! So it's better to be a bit above 1 than equal.

            List<List<Point2d>> newPoints = new List<List<Point2d>>();

            List<Point2d> lastPoints = null;

            foreach (List<Point2d> initpoints in frontPoints)
            {

                
                //complicated little business to linearly interpolate one or perhaps several new points in between each existing point.
                //This helps smooth out the boundary A LOT.
                if (lastPoints != null)
                {
                    double numPointsToInterpolate = 7; //was 3, now 6 (2022-07)

                    double french_dist = Calcs.CalculatePointDistance(initpoints[1], lastPoints[1]);
                    double brit_dist = Calcs.CalculatePointDistance(initpoints[0], lastPoints[0]);
                    double ave_dist = (french_dist + brit_dist) / 2;


                    //we try to put a point about every 3km, but as we near the brit coastline
                    //we use the distance between those end points, and if near the french coastline, we use the distance between those frontPoints to figure how many to interpolate
                    //Thus we can squeeze or stretch points on either side and it still works OK.
                    //3000m probably has something to do with, our neutral zone is 3000m wide, so red/white/blue front markers are facing each other with a spacing of about 3000m.
                    //You won't have collisions with that when you turn a corner unless your next point is <3000m away.
                    //if we want to use more fine-grained front points, we could put a neutral marker
                    //closer to red, and another very close to blue, instead of just one halfway between
                    //as we are now.  Try making every 6000 instead of 3000.
                    if (mult_neut > 0.4) numPointsToInterpolate = french_dist / 4000;
                    else if (mult_neut < -0.4) numPointsToInterpolate = brit_dist / 4000;
                    else numPointsToInterpolate = ave_dist / 4000;

                    for (int i = 1; i < numPointsToInterpolate - 1 ; i++)
                    {
                        //0 is brit side & 1 is french side
                        //Console.WriteLine("PTI: {0} {1}", i, numPointsToInterpolate);
                        double id = (double)i;
                        List<Point2d> newPoint = new List<Point2d>();
                        newPoint.Add(new Point2d(id * (initpoints[0].x - lastPoints[0].x) / numPointsToInterpolate + lastPoints[0].x, id * (initpoints[0].y - lastPoints[0].y) / numPointsToInterpolate + lastPoints[0].y));
                        newPoint.Add(new Point2d(id * (initpoints[1].x - lastPoints[1].x) / numPointsToInterpolate + lastPoints[1].x, id * (initpoints[1].y - lastPoints[1].y) / numPointsToInterpolate + lastPoints[1].y));
                        newPoints.Add(newPoint);
                    }
                }

                newPoints.Add(initpoints);

                lastPoints = initpoints;

            }
            var Point1 = new Point3d();
            var Point2 = new Point3d();
            var Point3 = new Point3d();
            var oldBauv = new Point3d();
            int pointCount = 0;

            //now go through all the points in our new, much higher resolution, line & plot
            foreach (List<Point2d> points in newPoints)
            {

                double dist = Calcs.CalculatePointDistance(points[0], points[1]);

                //2022/07 - here is where x,y and x2,y2 should be PERPENDICULAR to the current stretch
                //of the front line, rather than just moving alone the line connecting red/blue sides (as it does now)
                //2022/12 - we always work on Point2, which is x_neut,y_neut  Then x/y_blue & x/y_red are extrapolated from that, based on the relative positions of the three points and desired width of the neutral zone

                double x_neut = mult_neut * points[1].x + (1 - mult_neut) * points[0].x;  //linear interpolation between the two given points, based on how far we currently are between the min & max map state
                double y_neut = mult_neut * points[1].y + (1 - mult_neut) * points[0].y;

                Point3d Point = new Point3d(x_neut, y_neut, 0);

                if (pointCount == 0)
                {
                    Point1 = Point;
                    pointCount++;
                    continue;
                }
                else if (pointCount == 1)
                {
                    Point2 = Point;
                    pointCount++;
                    continue;
                }
                Point3 = Point;

                Point3d bauv = Calcs.bisectAngleUnitVectorXY(Point1, Point2, Point3, Point2);

                //bauvXY works so that if the bauv vector is point anywhere NORTH it will be the RED
                //side.  However on our map the real line is more a 45 degree angle or in certain places
                //even more complicated.  But for now let's make it a 45 degree line - vectors towards left/above are brit & towards right/down are french


                /*
                if (Point2.x > 229377) //the part of the map where the line is more 45 deg or vertical
                {
                    if (bauv.y < 0) bauv = Calcs.reverseVectorXY(bauv);
                    //else if (bauv.y >= 0 && bauv.x >= bauv.y) bauv = Calcs.reverseVectorXY(bauv);
                } else //the part of the map where the line is more horizontal
                {
                    if (bauv.y < 0 && bauv.x > bauv.y) bauv = Calcs.reverseVectorXY(bauv);
                    else if (bauv.y >= 0 && bauv.x >= bauv.y) bauv = Calcs.reverseVectorXY(bauv);
                }
                */
                //this is ANOTHER way to do it - based on the idea that bauv should point
                //in the direction of points[1] -> points[0] (points [0] is on the RED side and bauv points towards teh RED side
                /*
                double theta = Calcs.angleBetweenVectorsXY_rad(bauv, new Point3d (points[0].x-points[1].x, points[1].y-points[0].y, 0));
                if (theta < Math.PI / 2) bauv = Calcs.reverseVectorXY(bauv);
                */

                //OK, the winner is, we take Point1 and Point2, get the normal vector in the CLOCKWISE direction from that, and  then make sure bauv is pointed in THAT same general direction
                double theta = Calcs.angleBetweenVectorsXY_rad(bauv, Calcs.unitNormalVectorCCWXY( Point1, Point3));
                if (theta > Math.PI / 2 && !double.IsNaN(theta)) bauv = Calcs.reverseVectorXY(bauv);

                double theta2 = Calcs.angleBetweenVectorsXY_rad(bauv, oldBauv);
                if (theta2 > Math.PI / 2) Console.WriteLine("!!!!!!! FRONTINELINE: BAUV reversed!!!!!! {0:f2} {1:f2} {2:f2} {3:f2} theta2 {4:f3}", bauv.x, bauv.y, oldBauv.x, oldBauv.y, theta2);
                if (double.IsNaN(theta) && theta2 > Math.PI/2 ) bauv = Calcs.reverseVectorXY(bauv);

                if (!test) Console.WriteLine("Frontline: Point: ({0:F0}, {1:F0}) - BAUV: ({2:F2}, {3:F2}) theta: {4}", Point2.x, Point2.y, bauv.x, bauv.y, theta);
                
                oldBauv = bauv;

                //Final solution to bauv direction problem is in the CALCS routine - it is set to make bauv point north if we traverse the line west->east etc.  Since we are going west->east we can take the perp to that vector turn to CCW and it will point north-ish.  Etc.

                //a red & neut will face each other at 150m. Similarly for blue & blueNeut`
                Point3d bluePos = Calcs.addVectorwithScalarMultXY(Point2, bauv, -neutral_width_m);
                Point3d blueNeutPos = Calcs.addVectorwithScalarMultXY(Point2, bauv, -neutral_width_m + 250);
                Point3d redPos = Calcs.addVectorwithScalarMultXY(Point2, bauv, neutral_width_m);
                Point3d redNeutPos = Calcs.addVectorwithScalarMultXY(Point2, bauv, neutral_width_m - 250);
                Point3d neutPos = Point2;

                /*
                double x = mult * points[1].x + (1 - mult) * points[0].x;  //linear interpolation between the two given points, based on how far we currently are between the min & max map state
                double y = mult * points[1].y + (1 - mult) * points[0].y;
                double x2 = mult2 * points[1].x + (1 - mult2) * points[0].x;  //linear interpolation between the two given points, based on how far we currently are between the min & max map state
                double y2 = mult2 * points[1].y + (1 - mult2) * points[0].y;
                */

                //Console.WriteLine("({0:F0}, {1:F0}) - ({2:F0}, {3:F0})", x, y, x2, y2);

                sect = "FrontMarker";
                key = "FrontMarker" + count.ToString();
                value = redPos.x.ToString("F2") + " " + redPos.y.ToString("F2") + " 1"; //1 = army 1
                f.add(sect, key, value);
                f2.add(sect, key, value);
                count++;

                key = "FrontMarker" + count.ToString();
                value = redNeutPos.x.ToString("F2") + " " + redNeutPos.y.ToString("F2") + " 0"; //1 = army 1
                f.add(sect, key, value);
                f2.add(sect, key, value);
                count++;

                key = "FrontMarker" + count.ToString();
                value = blueNeutPos.x.ToString("F2") + " " + blueNeutPos.y.ToString("F2") + " 0"; //1 = army 1
                f.add(sect, key, value);
                f2.add(sect, key, value);
                count++;

                key = "FrontMarker" + count.ToString();
                value = bluePos.x.ToString("F2") + " " + bluePos.y.ToString("F2") + " 2";
                f.add(sect, key, value);
                f2.add(sect, key, value);
                count++;

                Point1 = Point2;
                Point2 = Point3;
                pointCount++;
            }

            int countFP = 0;

            foreach (List<Point2d> initpoints in frontPoints)
            {

                f = Calcs.makeStatic(f, GamePlay, this, initpoints[0].x, initpoints[0].y, -100, "Stationary.Environment.Ladder_UK1_DMG1", 0, staticprefix: "frontmarker_setpoint_red_" + countFP.ToString() + "_");
                f = Calcs.makeStatic(f, GamePlay, this, initpoints[1].x, initpoints[1].y, -100, "Stationary.Environment.Ladder_UK1_DMG1", 0, staticprefix: "frontmarker_setpoint_blue" + countFP.ToString() + "_");
                countFP++;
            }


            if (loadSectionFile)
            {
				if (fast) GamePlay.gpPostMissionLoad(f);
				else {
					
					Timeout(12.74, () =>
					{
						GamePlay.gpPostMissionLoad(f);
					});
				}

                if (ON_TESTSERVER) Console.WriteLine("PostmissionLoad: Drew current frontline");
            }



            if (saveName != null && !panic()) f.save(CLOD_PATH + FILE_PATH + "/sectionfiles" + "/" + saveName); //testing

            return f2;
        }
        catch (Exception ex)
        {
            Console.WriteLine("******************Frontline ERROR: " + ex.ToString());
            return f2;
        }
        


    }

