                //{
                MO_SpoilPlayerScoutPhotos(actor as Player);
                //});
            }

            try
            {
                MO_HandlePointAreaObjectives(actor, damages, shortName); //remember, don't overdo it with creating many new threads @ once, as can happen with onXkilled
                MO_makeAllObjectivesScoutedAndLaunchDefenseFromPos(actor.Pos(), null);
            }
            catch (Exception ex) { Console.WriteLine("OnActorDead - HandlePAO: " + ex.ToString()); }

            if (actor != null && actor is AiAircraft)
            {
                //if dead, then destroy it within a reasonable time
                AiAircraft aircraft = actor as AiAircraft;

