                            //HashSet<AiAirGroup> gag = new HashSet<AiAirGroup> ( airGroupInfoDict[airGroup].groupedAirGroups);
                            HashSet<AiAirGroup> toremovefrom_gag = new HashSet<AiAirGroup>();

