                                                      mph +
                                                      heading.ToString("F0") + "° " +
                                                      sector.ToString() + " " +
                                                      Calcs.GetAircraftType(a);
                                                    if (intcpt_time_min > 0.02)
                                                    {
                                                        posmessage +=
                                                           " Intcpt: " +
