                                            //Console.WriteLine("LPAA: Processing ag: PA{0} {1} {2} ", playerArmy, agid.actor.Army(), agid.actor.Name());

                                            aigroup_count++;
                                            /*
                                            AirGroupInfo agid = new AirGroupInfo();
                                            if (airGroupInfoDict != null && airGroupInfoDict.ContainsKey(airGroup))
