    // destroys aircraft abandoned by a player.
    private bool isAiControlledPlane(AiAircraft aircraft)
    {
        if (aircraft == null)
        {
            return false;
        }

        Player[] players = GamePlay.gpRemotePlayers();
        foreach (Player p in players)
        {
            if (p != null && (p.Place() is AiAircraft) && (p.Place() as AiAircraft) == aircraft)
            {
                return false;
            }
        }

        return true;
    }

    private void destroyPlane(AiAircraft aircraft, string reason = "DestroyPlane")
    {
        if (aircraft != null)
        {
			AircraftDestroyedList[aircraft] = reason;
            Timeout (0.1, () => aircraft.Destroy());
        }
    }

    private void explodeFuelTank(AiAircraft aircraft)
    {
        if (aircraft != null)
        {
            aircraft.hitNamed(part.NamedDamageTypes.FuelTank0Exploded);
        }
    }

    private void destroyAiControlledPlane(AiAircraft aircraft, string reason = "destroyAiControlledPlane")
    {
        if (isAiControlledPlane2(aircraft))
        {
			AircraftDestroyedList[aircraft] = reason;
            destroyPlane(aircraft, reason);
        }
    }

    private void damageAiControlledPlane(AiActor actor, string reason="damageAiControlledPlane")
    {
        if (actor == null || !(actor is AiAircraft))
        {
            return;
        }

        AiAircraft aircraft = (actor as AiAircraft);

        if (!isAiControlledPlane2(aircraft))
        {
            return;
        }

        if (aircraft == null)
        {
            return;
        }

        aircraft.hitNamed(part.NamedDamageTypes.ControlsElevatorDisabled);
        aircraft.hitNamed(part.NamedDamageTypes.ControlsAileronsDisabled);
        aircraft.hitNamed(part.NamedDamageTypes.ControlsRudderDisabled);
        aircraft.hitNamed(part.NamedDamageTypes.FuelPumpFailure);
        aircraft.hitNamed(part.NamedDamageTypes.Eng0TotalFailure);
        aircraft.hitNamed(part.NamedDamageTypes.ElecPrimaryFailure);
        aircraft.hitNamed(part.NamedDamageTypes.ElecBatteryFailure);

        aircraft.hitLimb(part.LimbNames.WingL1, -0.5);
        aircraft.hitLimb(part.LimbNames.WingL2, -0.5);
        aircraft.hitLimb(part.LimbNames.WingL3, -0.5);
        aircraft.hitLimb(part.LimbNames.WingL4, -0.5);
        aircraft.hitLimb(part.LimbNames.WingL5, -0.5);
        aircraft.hitLimb(part.LimbNames.WingL6, -0.5);
        aircraft.hitLimb(part.LimbNames.WingL7, -0.5);

        int iNumOfEngines = (aircraft.Group() as AiAirGroup).aircraftEnginesNum();
        for (int i = 0; i < iNumOfEngines; i++)
        {
            aircraft.hitNamed((part.NamedDamageTypes)Enum.Parse(typeof(part.NamedDamageTypes), "Eng" + i.ToString() + "TotalFailure"));
        }

        /***Timeout (240, () =>
                {explodeFuelTank (aircraft);}
            );
         * ***/

        Timeout(300, () =>
		
        {  
			AircraftDestroyedList[aircraft] = reason;
		    destroyPlane(aircraft, reason);
		}
            );
    }

    double cloudHeight = 1000;

    public string updateTimeAndWeather(string missionFile, string desiredString, string map_value)
    {
        try
        {

            RegexOptions ro = RegexOptions.IgnoreCase | RegexOptions.Multiline;
            missionFile = Regex.Replace(missionFile, @"^\s*TIME\s*\d*\.?\d*\s*$", desiredString, ro);//looks for a line with something like <spaces> TIME <spaces> 34.234 .. Case irrelevant = replaces it

            missionFile = Regex.Replace(missionFile, @"^\s*MAP\s.*$", "  MAP " + map_value, ro);//looks for a line with something like <spaces> MAP <spaces> nameof1940Map .. Case irrelevant = replaces it

            cloudHeight = random.Next(500, 1500);
            string desiredCloudsHeightString = "  CloudsHeight " + cloudHeight.ToString("F0"); //seems limited to 500-1500 meters.  See https://www.aircombatgroup.co.uk/forum/viewtopic.php?f=5&t=8360
                                                                                                          //Also MAYBE for cumulous clouds (and perhaps others ???) the cloudsheight here must be higher than the bottom of the cloud deck as given in those weather systems.  Yikes!
                                                                                                          //UPDATE: It's not that the cumulous cloud deck must be lower than the cloudsheight, just that it can't be too high in general.  Maybe less than 1200 meters?

            missionFile = Regex.Replace(missionFile, @"^\s*CloudsHeight\s*\d*\.?\d*\s*$", desiredCloudsHeightString, ro);//looks for a line with something like <spaces> XXXXXX <spaces> 34.234 .. Case irrelevant = replaces it

            /*int WeatherIndex = 1; //Can be 0=clear, 1 = light clouds, 2 = medium clouds
            if (random.NextDouble() > .91) WeatherIndex = 2;//rarely, make it medium clouds
            else if (random.NextDouble() > .80) WeatherIndex = 0;//more commonly, make it clear */

            //perhttps://weatherspark.com/y/150362/Average-Weather-in-Isle-of-Wight-United-Kingdom-Year-Round
            //June-Oct it is, clear: 25%, mostly clear 14%, partly cloudy 12%, mostly cloudy 12%, 35% overcast
            //We can't do overcast with Weatherindex, so say 0 = clear = 25%
            // 1 = mostl clear & half of partly cloudy = 20%, 
            // 2= half of pc and mc + a bit of oc = 28%.
            // Turn that into out of 100, it is: 34, 28, 38
            //Update 1/14/2023: BlacKnight wants more CLOUDS, so moved it to:
            // - 13% clear (WI = 0), 19% minor clouds (WI=1), remainder (68%) WI=3
            int WeatherIndex = 0; //Can be 0=clear, 1 = light clouds, 2 = medium clouds
            if (random.NextDouble() <= .19) WeatherIndex = 1;//28% partly cl
            else if (random.NextDouble() <= 68.0/81) WeatherIndex = 2;//38% mostly cl (72 is remaining % after 28)

            string desiredWeatherIndexString = "  WeatherIndex " + WeatherIndex.ToString("F0");
            missionFile = Regex.Replace(missionFile, @"^\s*WeatherIndex\s*\d*\.?\d*\s*$", desiredWeatherIndexString, ro);//looks for a line with something like <spaces> XXXXX <spaces> 34.234 .. Case irrelevant = replaces it

            //string desiredWindLayersString = generateWindLayers();

            //missionFile = Regex.Replace(missionFile, @"^\s*[GlobalWind_0]\s*$.*^\s*[splines]\s*$", desiredWindLayersString, ro);//looks for lines starting with [GlobalWind_0]  and ending with [splines] - Case irrelevant => replaces it

            //if (ON_TESTSERVER) Console.WriteLine(missionFile);


            return missionFile;
        }
        catch (Exception ex)
        {
            Console.WriteLine("updateweather ERROR: " + ex.Message);
            return missionFile;
        };
    }
    
    Dictionary<int, string> WindsAloft_red = new Dictionary<int, string>();
    Dictionary<int, string> WindsAloft_blue = new Dictionary<int, string>();
    Dictionary<int, string> WindsAloftCalc_red = new Dictionary<int, string>();
    Dictionary<int, string> WindsAloftCalc_blue = new Dictionary<int, string>();

    public string listWindLayers(Player player = null, int army = 1, int delta = 1, bool calc = false)
    {
        var WA = WindsAloft_red;
        if (army==2) WA = WindsAloft_blue;
        
        //printing the linds from the wind layers calculation
        if (calc)
        {
            WA = WindsAloftCalc_red;
            if (army == 2) WA = WindsAloftCalc_blue;
        }
        double delay = 0;

        string nl = Environment.NewLine; 
        string msg = "";
        //double oldAlt = -3000

        string newmsg1 = "";
        
        if (player != null) {
            newmsg1 = "Winds aloft:";
         
            Timeout(delay, () => { twcLogServer(new Player[] { player }, newmsg1); });
            delay += 0.02;
        }

        int count = 1;

        foreach (int alt in WA.Keys)
        {
            count++;
            if ( (count - 1) % delta != 0) continue;
            
            msg += WA[alt] + nl;
            if (player != null) Timeout(delay, ()=> { twcLogServer(new Player[] { player }, WA[alt]); });
            delay += 0.02;
        }
        return msg;
    }
    

