                string line_red = String.Format("{2:F0}ft: Wind from {0:F0} deg {1:F0} mph.", hdg_deg, Calcs.meterspsec2milesphour(vel_mps), Calcs.RoundInterval(Calcs.meters2feet(alt_m), 100));
