    public string generateWindLayers()
    {
        try
        {
            double gwl_cloudHeight = 0;
            //synchronize one of the layers with the bottom of the cloud layer
            if (cloudHeight >= 500 && cloudHeight <= 1500) gwl_cloudHeight = cloudHeight;

            //choose general wind direction in proportion to those usually found in the channel area
            //June-Oct
            //Wind in UK & FR is generally from the west, southwest, south
            //More precisely, per https://weatherspark.com/d/150362/9/12/Average-Weather-on-September-12-in-Isle-of-Wight-United-Kingdom#Figures-WindDirection on average in months June-Oct
            // 39% west (7 22 10), 21% south (10 7 4), 22% east (5 12 5), 18% north (4 10 4) 
            // Just to even it up a LITTLE say 35% west (7 20 8), 21% south (10 7 4), 22% east (5 12 5), 22% north (5 12 5) (dividing N into NNE, N, NNW - etc)
            var winDirWeights = new Dictionary<double, int>()
            {
                //heading, weight
                {0, 12 },
                {45, 10 },
                {90, 12},
                {135, 9 },
                {180, 7 },
                {225, 18 },
                {270, 20 },
                {315, 12 }

            };

            int sumWeight = winDirWeights.Values.Sum();
            double windir_main = 0;
            int windir_choice = random.Next(0, sumWeight);
            int sum = 0;
            foreach(double d in winDirWeights.Keys)
            {
                sum += winDirWeights[d];
                if (sum > windir_choice) { windir_main = d; break; }

            }

            double windir_alt_hdg_deg = windir_main + (random.NextDouble() - 0.5) * 45;
            if (windir_alt_hdg_deg < 0) windir_alt_hdg_deg += 360;

            //winddir at altitude is usually a bit different from ground, and typically winddir
            //proceeds counterclockwise as it goes down in altitude.  It can be (rarely) as far as 270 deg
            //from jetstream to sea level.  
            //Occasionally it is CW instead of CCW, but alittle

            int leftOrRight = random.Next(2);

            //Mostly it's around 30 deg say and CCW going down to the ground.
            //But it can be up to 270 CCW or say 60 CW
            double windir_adder_deg = 30 + (random.NextDouble() * random.NextDouble() * random.NextDouble()) * 225 * (leftOrRight) - (random.NextDouble() * random.NextDouble() * random.NextDouble()) * 90 * (1 - leftOrRight);
            double windir_gnd_hdg_deg = windir_alt_hdg_deg - windir_adder_deg;

            //Note this can be NEGATIVE, or >360, and we'll want to keep it that way for now, so we can step gradually from say 10 deg to -80.  Or from 350 deg to 410.

            //if (random.NextDouble() > 0.1) windir_hdg = random.NextDouble() * random.NextDouble() * 110 * (random.Next(2) * 2 - 1) + 225;  //will favor winds @ 225 deg +/- 50, mostly around 225.

            //Below is in m/s.  Roughly 1 m/s = 2 mph.
            //Per this web site: https://www.camarilloweather.com/wxglobalwind.php
            //wind speeds range 0-30mph-ish on the surface (more often 30-50-ish over the ocean, though)
            //0-10 common over ground, 20s over ocean
            //300ft 30-50mph
            //4900 ft 40-80mph
            //11500 40-90mph
            //35000 90-170mph
            //Per https://weatherspark.com/y/150362/Average-Weather-in-Isle-of-Wight-United-Kingdom-Year-Round average sea level windspeed Jun-Oct is about 12.8mph.
            //50% are in 8-17mph rand; 90% are in 6-21 range
            //We will use that for lowlevel_wind value.  (And it will be be adjusted if too dramatic
            //change from ground level, to avoid low level wind shear issues.)

            double lowlevel_wind_REAL_vel_mps = Calcs.milesphour2meterspsec(random.NextDouble() * random.NextDouble() * 15 * (random.Next(2) * 2 - 1) + 12.8); //So this gives approx 12.8mph ave, with 50% +/- 3.75, 80% +/ 9.6, and 20% +/- 9.6-15. 
            if (lowlevel_wind_REAL_vel_mps < 0) lowlevel_wind_REAL_vel_mps = 0;

            //double surface_wind_vel_mps = 0.5 + random.NextDouble() * 1.0; //keeping it REAL calm for starters 

            //IF we were doing real this would be =lowlevel_wind__real_vel_mps.  Maybe scale it down to 0-5mps or so. "5m/s or less is safe" for ground level.  For now scaling it 0-2 to keep it REAL calm @ surface.
         
            //was /10 and <=2, but moving up to /7 and <= 3.5 2023/01/23
            //moving up to 3.5 & 5.5 2023/08/22
            double surface_wind_vel_mps = lowlevel_wind_REAL_vel_mps / 3.5;            
            if (surface_wind_vel_mps > 6.0) surface_wind_vel_mps = 6.0; //2023/10

            if (ON_TESTSERVER) //testing HIGHER/more realistic surface winds @ testserver
            {
                surface_wind_vel_mps = lowlevel_wind_REAL_vel_mps / 2;
                if (surface_wind_vel_mps > 5.5) surface_wind_vel_mps = 5.5;
            }
            double lowlevel_wind_vel_mps = lowlevel_wind_REAL_vel_mps * 1.1; //IF we were doing REAL windvel, this would be like surface + 10% or so.

            //Based on satellite maps of high alt wind speed, we have:
            //0.03% 0 kt, 41% 1-36 KNOTS, 35% 36-72kt, 17% 72-100kt, 7% 100-150kt, 0.2% > 150kt

            double highlevel_wind_vel_kt = 1 + random.NextDouble() * 100;
            if (highlevel_wind_vel_kt <= 41) highlevel_wind_vel_kt *= 36 / 41; //41% are 1-36kt
            else if (highlevel_wind_vel_kt <= 76) highlevel_wind_vel_kt = (highlevel_wind_vel_kt - 41) * 36 / 35 + 36; //35% are 36-72kt
            else if (highlevel_wind_vel_kt <= 93) highlevel_wind_vel_kt = (highlevel_wind_vel_kt - 76) * 28 / 17 + 72; //17% are 72-100kt
            else highlevel_wind_vel_kt = (highlevel_wind_vel_kt - 93) * 50 / 7 + 100; //7% ARE 100-150kt

            //Very low high-level wind seems to come up a bit more often than warranted.
            if (highlevel_wind_vel_kt <= 41 && highlevel_wind_vel_kt < Calcs.meterspsec2knots(lowlevel_wind_REAL_vel_mps)) highlevel_wind_vel_kt = Calcs.meterspsec2knots(lowlevel_wind_REAL_vel_mps) + random.Next(-1, 5);

            if (highlevel_wind_vel_kt < 1) highlevel_wind_vel_kt = 1;

            //            double highlevel_wind_vel_mps = 3 + random.NextDouble()* 30  ; //Average speed at 12000m is around 25m/s or 50mph.  However jet stream typical speed is around 125m/s or 250mph.

                //Keep winds calm until Genghis Khan begins
            if (ON_JUBILEE && highlevel_wind_vel_kt >22)
            {
                Console.WriteLine("GenerateWindLayers: Clamping top speed to 22kt for {0:F3} more days", -DateTime.UtcNow.Subtract((new DateTime(2023, 01, 13, 23, 59, 0)).ToUniversalTime()).TotalDays);
                highlevel_wind_vel_kt = 22;
            } 


            double highlevel_wind_vel_mps = Calcs.knots2meterspsec(highlevel_wind_vel_kt);

            

            double windir_xy_rad = Calcs.DegreesToRadians(270.0 - windir_gnd_hdg_deg); //in radians, in the XYZ coordinate system where (1,0) = 0 degrees, (0,1) is 90 degrees etc.
            double windir_xy_rad_elev = windir_xy_rad;
            double bottomBound = 0;
            double topBound = 240; //next bottombound can be 90% of this, which we assume means phasing in the next wind speed from that point up, and so 240-24 = 216 which (WE HOPE!) is safely higher than the highest airfield/surface elevation in game. That high point appears to be around 200 meters near Upavon and also around 190 meters near Biggin Hill.  However the highest AIRFIELDS appear to be Biggin Hill at 186 and Yatesbury at 170.
                                   //Reason this is important is: Ground wind even just 3-4 m/s can cause weather cocking etc.  
                                   //It IS possible to take off etc with ground wind as high as 6 m/s or so but 1-2-3 m/2 is more reasonable.
                                   //The wind will be in effect until the elevation of the topBound and/or bottomBound of the next layer
                                   //So we want to avoid ANY high speed wind at the elevation where an airfield might be.

            string nl = Environment.NewLine;
            string s = "";
            s += "[GlobalWind_0]" + nl;
            s += String.Format("  Power {0:F3} {1:F3} 0.000" + nl, surface_wind_vel_mps * Math.Cos(windir_xy_rad), surface_wind_vel_mps * Math.Sin(windir_xy_rad));
            s += String.Format("  BottomBound {0:F0}" + nl, bottomBound);
            s += String.Format("  TopBound {0:F0}" + nl, topBound);
            s += "  GustPower 1" + nl; //Gust power & angle aren't implemented right now so just leaving them be
            s += "  GustAngle 0" + nl;
            //{ 200, 400, 800, 1600, 3200, 6400,  2800, 6200, 12000 }
            WindsAloftCalc_red[0] = String.Format("{0:F0} deg {1:F0} mph at {2:F0}", windir_gnd_hdg_deg, Calcs.meterspsec2milesphour(surface_wind_vel_mps), "sea level");
            WindsAloftCalc_blue[0] = String.Format("{0:F0} deg {1:F0} kph at {2:F0}", windir_gnd_hdg_deg, Calcs.meterspsec2kmphour (surface_wind_vel_mps), "sea level");

            //So CloD seems to be set up for GlobalWind_0 through 9 and definitely NOT 10 or 11.  
            //this causes an unhandledexception when trying to load the mis file
           
            int maxi = 9;
            //Having like 9 layers was cool BUT killed the server/clients (seemed to????), it seemed like.  2023-01-06, maybe not - maybe a different cause?  Trying 9 again.......
            //maybe like 4-5 layers is more reasonable
            double powernum = Math.Exp((Math.Log(93) / (maxi - 1))); //powernum^maxi = 90 - we want about 9,000m/30,000ft as our highest topBound, but then we will "manually" add one moreon top of that, which is the jetstream
            bool cloudcatch = false;

            for (int i = 1; i <= maxi; i++)
            {
                double oldTopBound = topBound;
                bottomBound = topBound - random.NextDouble() * 50; //you have to overlap the layers by a little -at least 1 meter or FMB makes it 50 meters always.  The next bottomBound is just a bit lower than the previous topBound
                //double baseAlt_m = Math.Pow(powernum, i) * 100; //ranges up to about 20000-ish
                //So this chart: https://www.quora.com/Does-the-wind-get-stronger-the-higher-the-altitude
                //Shows wind speed grows relatively linearly with altitude, up to about 10000m (jet stream), when it starts to decrease.
                //The slope of the line is slightly greater 0-1000m, then slightly less.
                double baseAlt_m = 9000 * i/(maxi-1); //ranges up to about 20000-ish
                topBound = 230.0 + (baseAlt_m) * (1.1 - random.NextDouble() * 0.2); //+/- 10%


                //Make one of the layer boundaries match the cloudbase altitude.
                //Stretch it up a bit of necessary.
                if (i < maxi - 1 && !cloudcatch && bottomBound < gwl_cloudHeight + 10 && topBound + 500 > gwl_cloudHeight && gwl_cloudHeight > oldTopBound)
                {
                    topBound = gwl_cloudHeight + 10 + random.Next(-30, 30); 
                    cloudcatch = true;
                }

                if (i == maxi) topBound = 16000; //we're manually making the last layer, which is 30,000+, jet stream

                if (topBound < bottomBound + 100) topBound = bottomBound + 200;
                
                double windbasis = (highlevel_wind_vel_mps - lowlevel_wind_vel_mps) * i / (double)maxi + lowlevel_wind_vel_mps;
                double wind_vel_mps = windbasis + (1.15 - random.NextDouble() * 0.3); //+/-15%

                //having a big wind shear near the surface is trouble (the 240m surface-level layer is 
                //quite near the surface anywhere there is some high ground)
                //So for that 2nd lowest layer, we clamp it ot surface wind + 3 m/s at most
                if (i == 1 && wind_vel_mps > surface_wind_vel_mps && wind_vel_mps - surface_wind_vel_mps > 3.5) wind_vel_mps = surface_wind_vel_mps + 3.5;

                //So wind direction is quite variable low to the ground but as we get in the 1000+m range
                //it is far less variable.
                //As you get closer to the ground, the wind direction tends to move counterclockwise (in the northern hemisphere), maybe the last 1000m or so.

                double dirbasis_deg = (windir_alt_hdg_deg - windir_gnd_hdg_deg) * i / (double)maxi + windir_gnd_hdg_deg;

                //up to 20 deg in either direction, but decreasing as altitude grows
                double dir_variability = 20 * Math.Pow((maxi - i) / (double)maxi, 1.3) * (random.Next(2)*2 -2);

                double windir_curralt_hdg_deg = dirbasis_deg + dir_variability*random.NextDouble(); //+/-15%


                double windir_curralt_xy_rad = Calcs.DegreesToRadians(270 - windir_curralt_hdg_deg);
                double z = (random.NextDouble()* random.NextDouble() * 1.5 - 0.75); //Have be very careful with the Z value, keep it quite small
                  //if z is even 2-3-4 aircraft like large bombers can get 'trapped' just below
                  //that boundary layer, unable to climb above it.
                  //Keeping it below 1 should be (fairly) safe
                
                //These don't do anything anyway, so just disabling.
                //double gustpow = random.NextDouble() * random.NextDouble() * 5;  // seems to vary 0-1?
                //double gustangle = random.NextDouble() * 90 - 45; //ranges -45 to 45 degrees
                double gustpow = 0;
                double gustangle = 0;

                bool turb = false;

                /*
                //Once in a while make a narrow, pretty turbulent layer, somewhat high
                if (i >= 6 && i < maxi && random.Next(30) == 0)
                {
                    topBound = bottomBound + 200 + random.Next(40);
                    windir_xy_rad_elev += Math.PI + random.NextDouble() * 0.05;
                    z = random.NextDouble() * 5 + 5;
                    turb = true;

                }*/

                s += String.Format("[GlobalWind_{0}]" + nl, i);
                s += String.Format("  Power {0:F3} {1:F3} {2:F3}" + nl, wind_vel_mps * Math.Cos(windir_curralt_xy_rad), wind_vel_mps * Math.Sin(windir_curralt_xy_rad), z);
                s += String.Format("  BottomBound {0:F0}" + nl, bottomBound);
                s += String.Format("  TopBound {0:F0}" + nl, topBound);
                s += String.Format("  GustPower {0:F3}" + nl, gustpow);  //Gust power & angle aren't implemented right now so just leaving them be
                s += String.Format("  GustAngle {0:F0}" + nl, gustangle); 

                WindsAloftCalc_red[Convert.ToInt32(bottomBound)] = String.Format("{0:F0} deg {1:F0} mph at {2:F0}", windir_curralt_hdg_deg, Calcs.meterspsec2milesphour(wind_vel_mps), Calcs.RoundInterval(Calcs.meters2feet((bottomBound)), 100 ));
                WindsAloftCalc_blue[Convert.ToInt32(bottomBound)] = String.Format("{0:F0} deg {1:F0} kph at {2:F0}", windir_curralt_hdg_deg, Calcs.meterspsec2kmphour(wind_vel_mps), Calcs.RoundInterval((bottomBound) , 100));

            
            }
            //s += "[splines]"; //NO newline after [splines]
            if (ON_TESTSERVER)
            {
                Console.WriteLine(s);
                Console.WriteLine(listWindLayers(null, 1, 1, calc: true)); ;
                Console.WriteLine( listWindLayers(null, 2, 1, calc: true));
            }
            return s;
        }
        catch (Exception ex)
        {
            Console.WriteLine("***** GenerateWindlayers ERROR: " + ex.Message);
            return "[GlobalWind_0]" + Environment.NewLine;
        }
    }

