                                                     //int brk=(int)Math.Round(19/20);


                /* if (DEBUG) twcLogServer(null, "DEBUGD: Airgroup: " + a.AirGroup() + " " 

                  + a.Type() + " " 
                  + a.TypedName() + " " 
                  +  a.AirGroup().ID() + " timeout: " + ot, new object[] { });
                */

