    [DataContract()]
    public class MissionObjective : IMissionObjective
    {
        //public string TriggerName { get; set; }

        [DataMember] public string ID { get; set; } //unique name, often the Triggername or static name
        [DataMember] public string Name { get; set; } //Name the will be displayed to the [DataMember] public in messages etc
        [DataMember] public int AttackingArmy { get; set; } // Army this is an objective for (ie, whose task is to destroy it); can be 1=red, 2=blue,0=none
        [DataMember] public int OwnerArmy { get; set; } // Army that owns this object (ie, is harmed if it is destroyed)
        [DataMember] public int OriginalOwnerArmy { get; set; } // Army that owned this object when first placed - so we know which side it was designed for in case it flips due to territory loss
        [DataMember] public string FlakID { get; set; } //Flak area associated with this objective.  Flak area codes & associated .mis files are identified in FlakMissions dictionary defined below
        [DataMember] public string InitSubmissionName { get; set; } //Flak area associated with this objective.  Flak area codes & associated .mis files are identified in FlakMissions dictionary defined below
        [DataMember] public string ChiefName { get; set; } //(optional) Name of the "Chief" associated with this objective, like 1009_Chief. If provided it allows the detection of the actual location of the _Chief on recon flights.  So when reconned, it will tell the actual location of the ship or convoy at the time of recon, not just the starting point of the _Chief's route.
        [DataMember] public bool AutoFlakIfPrimary { get; set; } //Automatically place flak batteries near this objective, but only if it is chosen as a primary
        [DataMember] public bool AutoFlak { get; set; } //Automatically place flak batteries near this objective
        [DataMember] public int NumFlakBatteries { get; set; }
        [DataMember] public int NumInFlakBattery { get; set; }
        [DataMember] public SortedDictionary<DateTime, int> DefenseUnits { get; set; } //number of defense units at this objective, and their expiration date
        //[DataMember] public List<Point3d> AutoFlak_locations { get; set; } //x,y is safe position for autoflak or tempflak around MO.  NOTE that z is "radius_hide" or known safe distance to nearest moving OBJ/convoy etc.  It is NOT height or altitude. //moved this to a separate structure, threadsafe, we hope
        public int AutoFlak_locations_pointer { get; set; }

        [DataMember] public bool IsEnabled { get; set; } //TODO: This is only partially implemented. But a certain % of objectives are marked disabled @ the start of each session; this has the effective of making them disappear (entirely in some cases, or just as objectives on the list in others)
        [DataMember] public bool CanBeDisabled { get; set; } //Many objectives can be disabled/moved/out of commission/whatever.  But some like large Military Manufacturing Areas, airports, etc just can't be disabled like that.
        [DataMember] public Mission.MO_ObjectiveType MOObjectiveType { get; set; }
        [DataMember] public Mission.MO_ProducerOrStorageType MOProducerOrStorageType { get; set; } //NOT IMPLEMENTED YET!
        [DataMember] public double MO_ProductionCut_pct { get; set; } //production cut caused by the loss of this item, percent 0-1 (= 0-100% or perhaps more than 100% possible? Or less, to cause an increase in production for that item?)
        [DataMember] public double MO_StorageCut_pct { get; set; } //percent of storage of this item cut/eliminated/destroyed caused by the loss of this item, percent 0-1 (= 0-100% or perhaps more than 100% possible? Or less, to cause an increase in production for that item?)
        [DataMember] public Point3d MO_ProductionStorageCutRadius_m { get; set; } //x,y point & radius (Point3d.z) within which this percent of storage or production of this item cut/eliminated/destroyed caused by the loss of this item will happen.  So you could for example have a shortage of spitfires or fuel in one area of the map that is serviced by this production or storage plant. The production cut will continue until the item is undestroyed.  The storage cut will be one-time when the item is destroyed.  NOT IMPLEMENTED!!!!!

        [DataMember] public Mission.MO_TriggerType MOTriggerType { get; set; }
        [DataMember] public bool IsPrimaryTarget { get; set; } //One of the primary/required targets for this mission?
        [DataMember] public double PrimaryTargetWeight { get; set; } //If we select primary targets randomly etc, is this one that could be selected? Percentage weight 0-100, 0 means never chosen.  Update: Now 0-200.  2020-01.
        [DataMember] public bool IsFocus { get; set; } //The focus airport/objective for this campaign/mission? //Not used in Channel Map (yet) but in Tobruk

        [DataMember] public double Points { get; set; } //How many points are awarded to the side that destroys this objective
        [DataMember] public double TimetoRepairIfDestroyed_hr { get; set; } //hours needed to repair this objective if it is destroyed, per 100%.  Ie if 200% destroyed it will take 2X this long.
        [DataMember] public bool Destroyed { get; set; }
        [DataMember] public double DestroyedPercent { get; set; } //some items can potentially be partially destroyed, it 50% = 0.5, 100%=1.0; also higher numbers possible such as 200% = 2.0;
        [DataMember] public bool ObjectiveAchievedForPoints { get; set; } //We set this when one side destroys an objective & gets the points for it.  We can then remove this when that side
                                                                          //turns the map so that they have a clean slate of new objectives.  But the points is independent of whether
                                                                          //it is actually still destroyed or not.
        [DataMember] public HashSet<string> PlayersWhoContributedNames { get; set; } //list of any players who have contributed to destroying this objective

        [DataMember] public Dictionary<string, int> PlayersWhoRepairedNamesTimes { get; set; } //list of any players who have contributed to repairing this objective, the int is how many times they delivered repair supplies

        [DataMember] public DateTime? TimeToUndestroy_UTC { get; set; } //if destroyed, what time UTC is the d/t it should be undestroyed/repaired.  This is in real time, ie if item destroyed 10pm, Tues Jan 24, 2022 UTC for 24 hours then it will be repaired at 10pm Wed Jan 25, 2022.
                                                                        //NOTE!!!! That Airfields use this slightly differently from other objectives.  When they are damaged they start registering a time to undestroy, even if they are not 100% destroyed.  This is the time when all damage should be repaired, removed. 
        [DataMember] public DateTime? LastHitTime_UTC { get; set; } //Last time target attacked/hit

        [DataMember] public bool Scouted { get; set; } //whether or not it has been scouted or reconnoitered by the enemy; if so they can get access to exact coordinates etc
        //public Dictionary<Player,int> PlayersWhoScouted { get; set; } //list of any players who have scouted this objective //Player is not serializable, alas.
        [DataMember] public Dictionary<string, int> PlayersWhoScoutedNames { get; set; } //list of any players who have scouted this objective
        [DataMember] public Point3d lastScoutedPos { get; set; } //where this objective was, at the time it was last scouted.  Note that x,y (meters) and ELEVATION ASL z (meters OR feet above SEA LEVEL) are inherited from Pos.
        [DataMember] public String lastScoutedSector { get; set; } //where this objective was, at the time it was last scouted
        [DataMember] public int numTimesScouted { get; set; } //how many times this objective has been scouted (since map turned/scouted objectives cleared)
        [DataMember] public DateTime? lastTimeScouted_dt { get; set; } //last Date/time this objective was scouted, in historical date/time terms (ie a 1940s ydt:hms)


        [DataMember] public bool hasGeneralStaff { get; set; } //one of the objectives for each side will have one of the top generals/staff/staff car nearby ONE of their primary objectives

        [DataMember] public Point3d Pos { get; set; } //x,y is the map position of the objectives in meters,meters - corresponds to coordinates used by CloD for location.  Pos.z is the elevation/altitude ASL (above sea level) of the objective above sea level.  If attacking army is Blue/2 this is in meters, if attacking army is Red/1 it is in FEET.
        [DataMember] public double radius { get; set; } //extent of the object, ie, for airfields, how far center to the perimeter.  This is more FYI as info about the object, although it can be used to determine whether hits to a certain object are effective, or how effective (as we do with airfields)

        [DataMember] public string Sector { get; set; }
        [DataMember] public string bigSector { get; set; } //a block of several sectors, somewhat randomly selected, and the target is somewhere within it
        [DataMember] public string HUDMessage { get; set; }
        [DataMember] public string LOGMessage { get; set; }
        [DataMember] public string SuccessSubmissionName { get; set; } //submission to launch when objective reached; if blank nothing launched
        [DataMember] public double RadarEffectiveRadius { get; set; }

        [DataMember] public string TriggerName { get; set; }
        [DataMember] public string TriggerType { get; set; }
        [DataMember] public double TriggerPercent { get; set; }
        [DataMember] public double TriggerDestroyRadius { get; set; } //What is set in the .mis file as the effective radius for this trigger object.  This is slightly different from "radius" in that it is a number used only internally to determine if the destroyed objects are within the effective area of the trigger.

        [DataMember] public double OrdnanceRequiredToTrigger_kg { get; set; } //For type PointArea
        [DataMember] public double OrdnanceOnTarget_kg { get; set; } //For PointArea & similar - how many KG ordnance have hit this target already
        [DataMember] public double ObjectsRequiredToTrigger_num { get; set; } ////For type JerryCanArea: buildings, static objects, etc within the given radius required to trigger it.  Using actual number instead of percent, because I don't think we cna get the listing of now many buildings etc in a given area. 
        [DataMember] public double ObjectsDestroyed_num { get; set; } //how many objects have been destroyed so far.
        [DataMember] public double TotalInitialObjects_num { get; set; } //for trigger type objectives, how many objects they started with, within their triggerradius
        [DataMember] public double ActorsRequiredToTrigger_num { get; set; } //these are actors killed which MATCH the Chief prefix (ie, 3001_Chief - each individual actor will be 3001_Chief1, 3001_Chief2, etc)
        [DataMember] public double ActorsDestroyed_num { get; set; }

        [DataMember] public double AirfieldDamagePoints { get; set; } //For airfields, how many destruction points have been received by that airport
        [DataMember] public double AirfieldPointsRequired { get; set; } //For airfields, how many damage points required to close it/ 100% damage
        public AiAirport aiairport { get; set; } //CloD internal airport object.  Can't save as [DataMember] due to it being in an external assembly etc
        [DataMember] public string AirfieldName { get; set; } //The ID is generally set to "internal airfieldname_airfield" and name is ""internal airfieldname Airfield" (unless it already includes a word like airfield, airport, fliegerhorst, aerodrome, etc).  This saves the actual/original airfield name incase we need to find it again.

        [DataMember] public HashSet<string> BirthplaceACTypes { get; set; } //For a Landing Ground Objective, which types of aircraft are included in the spawn area/birthplace 
        [DataMember] public List<string> StaticNames { get; set; } //for static targets, the list of static names that will determine if the target is destroyed
        [DataMember] public double StaticPercentageRequired { get; set; } //what percentage of those static targets must be destroyed to eliminate the objective
        [DataMember] public List<string> StaticRemoveNames { get; set; } //what statics to remove when the object is destroyed (allows eg dams to be breached by removal of certain portions)
        [DataMember] public Point3d[] StaticRemovalPoint_Radius_m { get; set; } //OR you can specify a list of points & corresponding radii to remove ALL statics within that radius from the point
                                                                                //Point3d.x & y are the point, .z is the radius.  TODO: This is not working yet        
        [DataMember] public double StaticRemoveDelay_sec { get; set; } //how long to wait after target destruction before removing static objects in list
        [DataMember] public double StaticRemoveSpread_sec { get; set; } //how long to spread out the static target destruction

        [DataMember] public MO_MobileObjectiveType MOMobileObjectiveType { get; set; } //MO_MobileOBjectiveType.None if it's not mobile/movable
        [DataMember] public double MobileMoveTime_hrs { get; set; } //Time between moves of this objective (hours)
        [DataMember] public DateTime? MobileNextMoveTime_dt { get; set; } //Next date/time this mobile objective should be moved;
        [DataMember] public double MobileMaxMoveDist_km { get; set; } //Minimum distance to move (km)
        [DataMember] public double MobileMinMoveDist_km { get; set; } //Maximum distance to move (km)
        [DataMember] public Point3d MobileSWPoint { get; set; } //area the MobileObjectiveType can roam is defined by a rectangle; these two points give the SW & NE corners of the rect
        [DataMember] public Point3d MobileNEPoint { get; set; }


        [DataMember] public string Comment { get; set; } //PRIVATE comment, ie for developers, internal notes, etc, not for display to end users
        public Mission msn;
        private Random ran = new Random();

        //for serialization we must  have a paramterless constructor.  So if we serialize things in we'll have to add the Mission msn value later;
        //after loading the data back in & unserializing it.
        public MissionObjective()
        {
        }

        public MissionObjective(Mission m)
        {
            msn = m;
        }
        //RADAR TRIGGER initiator ; does EITHER trigger OR PointArea, depending on parameters/trigger type given
        public MissionObjective(Mission m, string objectiveKey, string objectiveName, string flak, int ownerarmy, double pts, double repairdays, string mission_trigger_type, double trigger_percent, double x, double y, double trigger_destroy_radius, double radar_effective_radius, bool is_primary_target, double primary_target_weight, string comment, MO_ObjectiveType MObjType = MO_ObjectiveType.Radar, MO_TriggerType MOTrigType = MO_TriggerType.Trigger, string init_submission_filename = "", double orttkg = 100, double orttn = 2, double arttn = 0, MO_ProducerOrStorageType MOProdStorType = MO_ProducerOrStorageType.None, string chief_name = "")
        {

            msn = m;
            Pos = new Point3d(x, y, 0); //See below for z value added - elevation ASL in feet OR meters

            MOObjectiveType = MObjType;
            MOProducerOrStorageType = MOProdStorType;
            MOTriggerType = MOTrigType;
            TriggerName = objectiveKey;
            ID = objectiveKey;
            Name = objectiveName;
            //must make sure no additional/different replacements are used when the
            //chiefname is used to generate the stationary name in the .mis files
            ChiefName = IDtoCleanChiefName(chief_name); //Name of the chief used in teh mission or submission file, like 1009_Chief.  We can use this to find the exact location of that _Chief during recon flights etc.
            FlakID = flak;
            InitSubmissionName = init_submission_filename;
            AutoFlakIfPrimary = true;
            AutoFlak = true;
            NumFlakBatteries = 3;
            NumInFlakBattery = 4;            

            MOMobileObjectiveType = MO_MobileObjectiveType.None;
            MobileMoveTime_hrs = 0; //Time after which the mobile objective should move to a different location. 0 means never.
            MobileNextMoveTime_dt = null; //The next date/time when this mobile objective should be moved.
            MobileMaxMoveDist_km = 0;
            MobileMinMoveDist_km = 0;
            MobileSWPoint = Pos;
            MobileNEPoint = Pos;

            //NumFlakBatteries = 3;
            //NumInFlakBattery = 4;

            IsEnabled = true;
            CanBeDisabled = false;  //Radar is mostly fixed installations; if it's there it's there.

            TimetoRepairIfDestroyed_hr = repairdays * 24;
            OwnerArmy = ownerarmy;
            OriginalOwnerArmy = ownerarmy;
            AttackingArmy = 3 - ownerarmy;
            if (AttackingArmy > 2 || AttackingArmy < 1) AttackingArmy = 0;

            double z = Calcs.LandElevation_m(Pos); //saving altitude/elevation of the objective.
            if (AttackingArmy == 1) z = Calcs.meters2feet(z); //(in feet for Red army)
            Pos = new Point3d(Pos.x, Pos.y, z);

            if (AttackingArmy != 0)
            {
                HUDMessage = ArmiesL[AttackingArmy] + " destroyed " + Name;
                LOGMessage = "Heavy damage to " + Name + " - out of action about " + this.TimetoRepairIfDestroyed_hr.ToString("F0") + " hours. Good job " + ArmiesL[AttackingArmy] + "!!!";
            }
            else
            {
                HUDMessage = Name + " was destroyed";
                LOGMessage = Name + " was destroyed, " + this.TimetoRepairIfDestroyed_hr.ToString("F1") + " hours to repair. " + pts + " awarded " + ArmiesL[AttackingArmy];
            }

            Points = pts;
            TriggerType = mission_trigger_type; //the name/string of the trigger type from the .mis file.  Just FYI, not using it for anything at present.
            TriggerPercent = trigger_percent;

            /* string keyp = Calcs.doubleKeypad(Pos);
            Sector = msn.GamePlay.gpSectorName(x, y).ToString() + "." + keyp;
            Sector = Sector.Replace(",", ""); // remove the comma */
            Sector = Calcs.correctedSectorNameDoubleKeypad(msn, Pos);
            bigSector = Calcs.makeBigSector(msn, Pos, Points);
            TriggerDestroyRadius = trigger_destroy_radius;
            RadarEffectiveRadius = radar_effective_radius;

            radius = trigger_destroy_radius;

            OrdnanceRequiredToTrigger_kg = orttkg;
            OrdnanceOnTarget_kg = 0; //stores how much ordinance has been piled on this target
            ObjectsRequiredToTrigger_num = orttn;
            ObjectsDestroyed_num = 0;
            ActorsRequiredToTrigger_num = arttn; //these are actors killed which MATCH the Chief prefix (ie, 3001_Chief - each individual actor will be 3001_Chief1, 3001_Chief2, etc)
            ActorsDestroyed_num = 0;


            Destroyed = false;
            DestroyedPercent = 0;
            ObjectiveAchievedForPoints = false;
            TimeToUndestroy_UTC = null;
            LastHitTime_UTC = null;

            Scouted = false;
            lastScoutedPos = Pos;
            lastScoutedSector = Sector;
            PlayersWhoScoutedNames = new Dictionary<string, int>();
            PlayersWhoContributedNames = new HashSet<string>();
            PlayersWhoRepairedNamesTimes = new Dictionary<string, int>();

            hasGeneralStaff = false;


            IsPrimaryTarget = is_primary_target;
            PrimaryTargetWeight = primary_target_weight;
            Comment = comment;
        }


        //AIRFIELD initiator
        //public Dictionary<AiAirport, Tuple<bool, string, double, double, DateTime, double, Point3d>> AirfieldTargets = new Dictionary<AiAirport, Tuple<bool, string, double, double, DateTime, double, Point3d>>();
        //Tuple is: bool airfield disabled, string name, double pointstoknockout, double damage point total, DateTime time of last damage hit, double airfield radius, Point3d airfield center (position)
        public MissionObjective(Mission m, double pts, double ptp, AiAirport airport, int ownerarmy, Tuple<bool, string, double, double, DateTime, double, Point3d, Tuple<int>> tup, MO_ProducerOrStorageType MOProdStorType = MO_ProducerOrStorageType.None, bool is_focus = false, string chief_name = "")
        //            string tn, string n, int ownerarmy, double pts, string t, double p, double x, double y, double d, bool pt, int ptp, string comment, MO_ProducerOrStorageType MOProdStorType = MO_ProducerOrStorageType.None)
        {

            msn = m;
            MOObjectiveType = MO_ObjectiveType.Military_Airfield;
            MOProducerOrStorageType = MOProdStorType;
            MOTriggerType = MO_TriggerType.Airfield;
            ID = tup.Item2 + "_airfield";
            //Console.WriteLine("New MissionObjective airport: " + ID);
            string adder = " Airfield";

            //if the airfield name already includes somethign meaning "airfield" then don't add it again
            string matcher = tup.Item2.ToLower();
            var descList = new List<string> { "airfield", "airport", "fliegerhorst", "aerodrome", "airdrome", "aéroport", "aérodrome", "raf ", "airbase", "landing field", "air station", "air strip", "flugplatz", "flughafen", "lufthafen", "aerodrom", "flugfeld", "luftverkehrszentrum", "sonderlandeplatz", "landeplatz", "luftstützpukt", "flugstation", "luftwaffenstützpunkt", "lg", "landing ground" };

            if (descList.Any(s => matcher.Contains(s))) adder = "";

            Name = tup.Item2 + adder;

            AirfieldDamagePoints = tup.Item4;  //For airfields, how many destruction points have been received by that airport
            AirfieldPointsRequired = tup.Item3; //For airfields, how many damage points required to close it/ 100% damage
            AiAirport aiairport = airport; //CloD internal airport object.  Can't save as [DataMember] due to it being in an external assembly etc
            AirfieldName = tup.Item2;//The ID is generally set to "internal airfieldname_airfield" and name is ""internal airfieldname Airfield".  This saves the actual/original/exact airfield name incase we need to find it again.

            ChiefName = IDtoCleanChiefName(chief_name); //Name of the chief used in teh mission or submission file, like 1009_Chief.  We can use this to find the exact location of that _Chief during recon flights etc.
            FlakID = ""; //no flak files for airports . . . yet
            AutoFlakIfPrimary = true;
            AutoFlak = false;
            NumFlakBatteries = 3;
            NumInFlakBattery = 3;
            //for testing
            //NumFlakBatteries = 3;
            //NumInFlakBattery = 4;


            Pos = tup.Item7;

            MOMobileObjectiveType = MO_MobileObjectiveType.None;
            MobileMoveTime_hrs = 0; //Time after which the mobile objective should move to a different location. 0 means never.
            MobileNextMoveTime_dt = null; //The next date/time when this mobile objective should be moved.
            MobileMaxMoveDist_km = 0;
            MobileMinMoveDist_km = 0;
            MobileSWPoint = Pos;
            MobileNEPoint = Pos;

            IsEnabled = true;
            CanBeDisabled = false;  //Airfields are mostly fixed installations; if it's there it's there.


            //OwnerArmy = airport.Army(); OK, this doesn't work as all .Army() for airports is set to 0        
            OwnerArmy = ownerarmy;
            OriginalOwnerArmy = ownerarmy;
            AttackingArmy = 3 - OwnerArmy;
            if (AttackingArmy > 2 || AttackingArmy < 1) AttackingArmy = 0;

            double z = Calcs.LandElevation_m(Pos); //saving altitude/elevation of the objective.
            if (AttackingArmy == 1) z = Calcs.meters2feet(z); //(in feet for Red army)
            Pos = new Point3d(Pos.x, Pos.y, z);

            HUDMessage = null;//hud/log messages are handled by the handle airport bombing routine
            LOGMessage = null;

            Points = pts;
            string keyp = Calcs.doubleKeypad(Pos);
            /* Sector = msn.GamePlay.gpSectorName(x, y).ToString() + "." + keyp;
            Sector = Sector.Replace(",", ""); // remove the comma     */
            Sector = Calcs.correctedSectorNameDoubleKeypad(msn, Pos);
            bigSector = Calcs.makeBigSector(msn, Pos, Points);

            radius = tup.Item6; //

            TimetoRepairIfDestroyed_hr = 200 * 20 / 60; //Airfields have their own routines for figuring this out, but we are still setting this here as the typical/average value
                                                        //Formula is points taken * 20 = minutes to repair.  So 200 pts require to take out an airfield means 200*20/60 hours.
            Destroyed = false;
            DestroyedPercent = 0;
            ObjectiveAchievedForPoints = false;
            TimeToUndestroy_UTC = null;
            LastHitTime_UTC = null;

            Scouted = false;
            lastScoutedPos = Pos;
            lastScoutedSector = Sector;
            PlayersWhoScoutedNames = new Dictionary<string, int>();
            PlayersWhoContributedNames = new HashSet<string>();
            PlayersWhoRepairedNamesTimes = new Dictionary<string, int>();

            hasGeneralStaff = false;

            IsPrimaryTarget = false;
            PrimaryTargetWeight = ptp;
            IsFocus = is_focus;
            Comment = "Auto-generated from in-game airports list";
            fixDestructionValues();
        }

        //TEMPORARY LANDING GROUND initiator
        public MissionObjective(Mission m, string objective_id, string name, Point3d pos, double radius_m, double objective_points, double primaryobjective_weight, double timeToRemainActive_hrs, string flak_file, int ownerarmy, bool auto_flak = true, bool auto_flak_ifprimary = true, int flak_numbatteries = 7, int flak_numberinbattery = 8, MO_ProducerOrStorageType MOProdStorType = MO_ProducerOrStorageType.None, string chief_name = "", HashSet<string> planeset = null)

        {

            msn = m;
            MOObjectiveType = MO_ObjectiveType.TemporaryLandingGround;
            MOProducerOrStorageType = MOProdStorType;
            MOTriggerType = MO_TriggerType.TemporaryLandingGround;
            ID = objective_id;
            Console.WriteLine("Creating NEW MissionObjective Temporary Landing Ground: " + ID);
            Name = name;

            AirfieldName = name;//The ID is generally set to "internal airfieldname_spawn" and name is ""internal airfieldname Airfield" (unless the original name includes a word like "Airfield" or "Airbase" or similar.  This saves the actual/original/exact airfield name incase we need to find it again.
            if (planeset is object) Console.WriteLine("Landingground: Making MissionObjective, adding planeset with {0} aircraft", planeset.Count); 
            else Console.WriteLine("Landingground: Making MissionObjective, planeset was NULL!!!");
            BirthplaceACTypes = planeset; //For a Landing Ground Objective, which types of aircraft are included in the spawn area/birthplace 
            if (BirthplaceACTypes is object) Console.WriteLine("Landingground: Making MissionObjective, adding planeset with {0} aircraft: {1}", BirthplaceACTypes.Count, string.Join("", BirthplaceACTypes) );
            else Console.WriteLine("Landingground: Making MissionObjective, planeset was NULL!!!");
            ChiefName = IDtoCleanChiefName(chief_name); //Name of the chief used in the mission or submission file, like 1009_Chief.  We can use this to find the exact location of that _Chief during recon flights etc.

            FlakID = flak_file; //no flak files for airports . . . yet
            AutoFlakIfPrimary = true;
            AutoFlak = true;
            NumFlakBatteries = 2;
            NumInFlakBattery = 2;
            //for testing
            //NumFlakBatteries = 3;
            //NumInFlakBattery = 4;


            Pos = pos;

            MOMobileObjectiveType = MO_MobileObjectiveType.None;
            MobileMoveTime_hrs = 0; //Time after which the mobile objective should move to a different location. 0 means never.
            MobileNextMoveTime_dt = null; //The next date/time when this mobile objective should be moved.
            MobileMaxMoveDist_km = 0;
            MobileMinMoveDist_km = 0;
            MobileSWPoint = Pos;
            MobileNEPoint = Pos;

            IsEnabled = true;
            CanBeDisabled = false;  //Airfields are mostly fixed installations; if it's there it's there.


            //OwnerArmy = airport.Army(); OK, this doesn't work as all .Army() for airports is set to 0        
            OwnerArmy = ownerarmy; //This is a bit confused as this target needn't be "attacked".
            OriginalOwnerArmy = ownerarmy;
            AttackingArmy = ownerarmy; //Attacked in this case means "army that needs to complete or accomplish this task."
            //if (AttackingArmy > 2 || AttackingArmy < 1) AttackingArmy = 0;


            double z = Calcs.LandElevation_m(Pos); //saving altitude/elevation of the objective.
            if (AttackingArmy == 1) z = Calcs.meters2feet(z); //(in feet for Red army)
            Pos = new Point3d(Pos.x, Pos.y, z);

            Points = objective_points;
            string keyp = Calcs.doubleKeypad(Pos);
            /* Sector = msn.GamePlay.gpSectorName(x, y).ToString() + "." + keyp;
            Sector = Sector.Replace(",", ""); // remove the comma     */
            Sector = Calcs.correctedSectorNameDoubleKeypad(msn, Pos);
            bigSector = Calcs.makeBigSector(msn, Pos, Points);

            radius = radius_m; //

            TimetoRepairIfDestroyed_hr = timeToRemainActive_hrs; //Another strange one; we're reversing the "destroyed" system - this is how long it stays active once established

            HUDMessage = ArmiesL[ownerarmy] + " created a Landing Ground - " + Name;
            LOGMessage = "New Landing Ground " + Name + " created by " + ArmiesL[ownerarmy] + " - active for " + (this.TimetoRepairIfDestroyed_hr / 24.0).ToString("F1") + " days.";

            Destroyed = false;
            DestroyedPercent = 0;
            ObjectiveAchievedForPoints = false;
            DateTime currTime_dt = DateTime.UtcNow;
            TimeToUndestroy_UTC = currTime_dt.AddHours(timeToRemainActive_hrs);
            LastHitTime_UTC = null;

            Scouted = false;
            lastScoutedPos = Pos;
            lastScoutedSector = Sector;
            PlayersWhoScoutedNames = new Dictionary<string, int>();
            PlayersWhoContributedNames = new HashSet<string>();
            PlayersWhoRepairedNamesTimes = new Dictionary<string, int>();

            hasGeneralStaff = false;

            IsPrimaryTarget = false;
            PrimaryTargetWeight = primaryobjective_weight;
            IsFocus = false;
        }



        //TRIGGER initiator (for all trigger types, the kind that use the built-in CLoD triggers, except RADAR & AIRFIELD & POINTAREA)
        public MissionObjective(Mission m, MO_ObjectiveType mot, string tn, string n, string flak, string init_submission_filename, string chief_name, int ownerarmy, double pts, string trigger_type, double percentageToTrigger, double x, double y, double trigger_destroy_radius, bool pt, double ptp, double ttr_hr, string comment, MO_ProducerOrStorageType MOProdStorType = MO_ProducerOrStorageType.None, int numHitsToTrigger= 0, int numObjectsInRadius= 0)
        {

            Console.WriteLine("Initiating Trigger objective " + tn + " submission file: " + init_submission_filename);
            msn = m;
            Pos = new Point3d(x, y, 0);

            MOObjectiveType = mot;
            MOProducerOrStorageType = MOProdStorType;
            MOTriggerType = MO_TriggerType.Trigger;
            TriggerName = tn;
            ID = tn;
            Name = n;
            FlakID = flak;
            InitSubmissionName = init_submission_filename;
            ChiefName = IDtoCleanChiefName(chief_name); //Name of the chief used in teh mission or submission file, like 1009_Chief.  We can use this to find the exact location of that _Chief during recon flights etc.
            AutoFlakIfPrimary = true;
            AutoFlak = false;
            //NumFlakBatteries = 4;
            //NumInFlakBattery = 10;
            //for testing
            NumFlakBatteries = 2;
            NumInFlakBattery = 6;

            MOMobileObjectiveType = MO_MobileObjectiveType.None;
            MobileMoveTime_hrs = 0; //Time after which the mobile objective should move to a different location. 0 means never.
            MobileNextMoveTime_dt = null; //The next date/time when this mobile objective should be moved.
            MobileMaxMoveDist_km = 0;
            MobileMinMoveDist_km = 0;
            MobileSWPoint = Pos;
            MobileNEPoint = Pos;

            IsEnabled = true;
            CanBeDisabled = false;  //Mostly these rely on fixed/existing buildings etc that can't be removed

            OwnerArmy = ownerarmy;
            OriginalOwnerArmy = ownerarmy;
            AttackingArmy = 3 - ownerarmy;
            if (AttackingArmy > 2 || AttackingArmy < 1) AttackingArmy = 0;

            double z = Calcs.LandElevation_m(Pos); //saving altitude/elevation of the objective.
            if (AttackingArmy == 1) z = Calcs.meters2feet(z); //(in feet for Red army)
            Pos = new Point3d(Pos.x, Pos.y, z);

            if (AttackingArmy != 0)
            {
                HUDMessage = ArmiesL[AttackingArmy] + " destroyed " + Name;
                LOGMessage = "Heavy damage to " + Name + " - good job " + ArmiesL[AttackingArmy] + "!!!";
            }
            else
            {
                HUDMessage = Name + " was destroyed";
                LOGMessage = Name + " was destroyed";
            }

            Points = pts;
            TriggerType = trigger_type;
            TriggerPercent = percentageToTrigger;

            string keyp = Calcs.doubleKeypad(Pos);
            /* Sector = msn.GamePlay.gpSectorName(x, y).ToString() + "." + keyp;
            Sector = Sector.Replace(",", ""); // remove the comma     */
            Sector = Calcs.correctedSectorNameDoubleKeypad(msn, Pos);
            bigSector = Calcs.makeBigSector(msn, Pos, Points);

            radius = trigger_destroy_radius; //this was set to 75 for EVERY objective.  I'm not sure why?

            TriggerDestroyRadius = trigger_destroy_radius;
            TimetoRepairIfDestroyed_hr = ttr_hr;
            Destroyed = false;
            DestroyedPercent = 0;
            if (numObjectsInRadius > 0) TotalInitialObjects_num = numObjectsInRadius;
            else
            {
                //we could WAIT to do this for a few minutes unti lthe dust settles
                //OR we could recalculate it periodically?
                int num = msn.GamePlay.gpGroundStationarys(Pos.x, Pos.y, trigger_destroy_radius).ToList().Count;
                if (num < 10) num = 10;
                TotalInitialObjects_num = num;
            }

            ObjectsRequiredToTrigger_num = (double)TotalInitialObjects_num * (double)percentageToTrigger / 100.0; 

 
            ObjectiveAchievedForPoints = false;
            TimeToUndestroy_UTC = null;
            LastHitTime_UTC = null;

            Scouted = false;
            lastScoutedPos = Pos;
            lastScoutedSector = Sector;
            PlayersWhoScoutedNames = new Dictionary<string, int>();
            PlayersWhoContributedNames = new HashSet<string>();
            PlayersWhoRepairedNamesTimes = new Dictionary<string, int>();

            hasGeneralStaff = false;

            IsPrimaryTarget = pt;
            PrimaryTargetWeight = ptp;
            Comment = comment;
        }

        //POINTAREA initiator.  An area which is designated by a map coordinate and radius.  
        //You can designate EITHER kg tonnage of ordnance dropped in that area to destroy it, AND/OR a certain number of objects (static objects, actors, buildings, etc) that must be killed within that radius (the buildings part working depends on TF getting the onbuildingdestroyed routine working again), AND/OR a certain number of ACTORS that must be killed - they don't need to be within the certain RADIUS but they must match the CHIEF NAME given.
        //Chief name is for moving objectives like submarines, trains, vehicle convoys, ship actors, and looks like 2004_Chief (you must set up your .mis file for this so that the chiefs for different objectives have a unique number like this).  Then each individual vehicle/ship/sub/etc within that Chief will be named 2004_Chief1, 2004_Chief2, 2004_Chief3, etc. 
        //OR you can choose 2 of them and in that case the players will have, ie, to drop the certain tonnage on the area AND kill the certain number of objects, OR all three.
        public MissionObjective(Mission m, MO_ObjectiveType objective_type, string objective_ID, string objective_name, string flak, string init_submission_filename, int ownerarmy, double points, double x, double y, double rad, double trigrad, double orttkg, double orttn, double arttn, double primary_target_weight, double ttr_hr, bool auto_flak, bool auto_flak_ifprimary, int num_flakbatteries, int num_in_eachbattery, string comment, MO_ProducerOrStorageType MOProdStorType = MO_ProducerOrStorageType.None, string chief_name = "", bool canBeDisabled = true)
        {

            Console.WriteLine("Initiating PointArea objective " + objective_ID);
            msn = m;
            Pos = new Point3d(x, y, 0);

            MOObjectiveType = objective_type;
            MOProducerOrStorageType = MOProdStorType;
            MOTriggerType = MO_TriggerType.PointArea;
            TriggerName = objective_ID;
            ID = objective_ID;
            Name = objective_name;
            FlakID = flak;
            InitSubmissionName = init_submission_filename;
            AutoFlakIfPrimary = auto_flak_ifprimary;
            AutoFlak = auto_flak;
            //These are big wide open easy bombing targets, but they are heavily defended, must come in high.  Is the idea.
            NumFlakBatteries = num_flakbatteries;
            NumInFlakBattery = num_in_eachbattery;
            ChiefName = IDtoCleanChiefName(chief_name);

            //for testing
            //NumFlakBatteries = 1;
            //NumInFlakBattery = 10;

            MOMobileObjectiveType = MO_MobileObjectiveType.None;
            MobileMoveTime_hrs = 0; //Time after which the mobile objective should move to a different location. 0 means never.
            MobileNextMoveTime_dt = null; //The next date/time when this mobile objective should be moved.
            MobileMaxMoveDist_km = 0;
            MobileMinMoveDist_km = 0;
            MobileSWPoint = Pos;
            MobileNEPoint = Pos;

            IsEnabled = true;
            CanBeDisabled = canBeDisabled;
            if (Name.ToUpper().Contains("AREA")) CanBeDisabled = false;  //Can't disable area objectives, they are too large, complicated, etc.

            OwnerArmy = ownerarmy;
            OriginalOwnerArmy = ownerarmy;
            AttackingArmy = 3 - ownerarmy;
            if (AttackingArmy > 2 || AttackingArmy < 1) AttackingArmy = 0;

            double z = Calcs.LandElevation_m(Pos); //saving altitude/elevation of the objective.
            if (AttackingArmy == 1) z = Calcs.meters2feet(z); //(in feet for Red army)
            Pos = new Point3d(Pos.x, Pos.y, z);

            if (AttackingArmy != 0)
            {
                HUDMessage = ArmiesL[AttackingArmy] + " destroyed " + Name;
                LOGMessage = "Heavy damage to " + Name + " - good job " + ArmiesL[AttackingArmy] + "!!!";
            }
            else
            {
                HUDMessage = Name + " was destroyed";
                LOGMessage = Name + " was destroyed";
            }

            Points = points;
            TriggerType = ""; //used for CLoD internal triggers, which have a name like TGroundtarget
            TriggerPercent = 0; //we're not using this here, it is only for CloD built-in triggers
            Pos = new Point3d(x, y, 0);
            string keyp = Calcs.doubleKeypad(Pos);
            /* Sector = msn.GamePlay.gpSectorName(x, y).ToString() + "." + keyp;
            Sector = Sector.Replace(",", ""); // remove the comma     */
            Sector = Calcs.correctedSectorNameDoubleKeypad(msn, Pos);
            bigSector = Calcs.makeBigSector(msn, Pos, Points);

            radius = rad;

            TriggerDestroyRadius = trigrad;

            OrdnanceRequiredToTrigger_kg = orttkg;
            OrdnanceOnTarget_kg = 0; //stores how much ordinance has been piled on this target
            ObjectsRequiredToTrigger_num = orttn; //These can be stationaries/statics OR actors, as long they are in the objective radius
            ObjectsDestroyed_num = 0;
            ActorsRequiredToTrigger_num = arttn; //these are actors killed which MATCH the Chief prefix (ie, 3001_Chief - each individual actor will be 3001_Chief1, 3001_Chief2, etc)
            ActorsDestroyed_num = 0;

            TimetoRepairIfDestroyed_hr = ttr_hr;
            Destroyed = false;
            DestroyedPercent = 0;
            ObjectiveAchievedForPoints = false;
            TimeToUndestroy_UTC = null;
            LastHitTime_UTC = null;

            Scouted = false;
            lastScoutedPos = Pos;
            lastScoutedSector = Sector;
            PlayersWhoScoutedNames = new Dictionary<string, int>();
            PlayersWhoContributedNames = new HashSet<string>();
            PlayersWhoRepairedNamesTimes = new Dictionary<string, int>();

            hasGeneralStaff = false;

            IsPrimaryTarget = false;
            PrimaryTargetWeight = primary_target_weight;
            Comment = comment;


        }

        //POINTAREA ***AND*** MOBILE OBJECTIVE initiator.  An area which is designated by a map coordinate and radius ***AND*** which moves around within a designated rectangle every time a new session starts or whenever
        //You can designate EITHER kg tonnage of ordnance dropped in that area to destroy it, OR a certain number of objects (static objects, actors, buildings, etc) that must be killed within that radius (the buildings part working depends on TF getting the onbuildingdestroyed routine working again).  There is a failsafe so if oneside or the other is achieved over 200% it starts to count towards the other side (typically, KG-age, which will start to count towards objects killed, but it could be the other way, too)
        //OR you can choose BOTH and in that case the players will have to drop the certain tonnage on the area AND kill the certain number of objects
        public MissionObjective(Mission m, MO_ObjectiveType objective_type, string objective_ID, string objective_name, string flak, int ownerarmy,
            double points, double x, double y, double rad, double trigrad, double orttkg, double orttn, double arttn, double primary_target_weight, double ttr_hr, bool auto_flak, bool auto_flak_ifprimary,
            int num_flakbatteries, int num_in_eachbattery,
            MO_MobileObjectiveType mobile_objective_type,
            double mobile_hours_between_moves,
            Point3d mobile_SW_point,
            Point3d mobile_NE_point,
            double min_move_dist_km,
            double max_move_dist_km,
            MO_ProducerOrStorageType MOProdStorType = MO_ProducerOrStorageType.None,
            string comment = "", double radar_effective_radius_m = 20000,
            string chief_name = "", bool canbedisabled = true)

        {

            Console.WriteLine("Initiating PointArea/Mobile objective " + objective_ID);
            msn = m;
            Pos = new Point3d(x, y, 0);

            MOObjectiveType = objective_type;
            MOProducerOrStorageType = MOProdStorType;
            MOTriggerType = MO_TriggerType.PointArea;
            TriggerName = objective_ID;
            ID = objective_ID;
            Name = objective_name;
            FlakID = flak;
            InitSubmissionName = null; //can't really figure out how an initsubmission file would be helpful for these mobile objectives?
            AutoFlakIfPrimary = auto_flak_ifprimary;
            AutoFlak = auto_flak;
            //These are big wide open easy bombing targets, but thye are heavily defended, must come in high.  Is the idea.
            NumFlakBatteries = num_flakbatteries;
            NumInFlakBattery = num_in_eachbattery;

            ChiefName = IDtoCleanChiefName(chief_name); //Name of the chief used in teh mission or submission file, like 1009_Chief.  We can use this to find the exact location of that _Chief during recon flights etc.
            //for testing
            //NumFlakBatteries = 1;
            //NumInFlakBattery = 10;

            MOMobileObjectiveType = mobile_objective_type;
            MobileMoveTime_hrs = mobile_hours_between_moves; //Time after which the mobile objective should move to a different location.
            MobileNextMoveTime_dt = null; //The next date/time when this mobile objective should be moved.  If null the objective will be placed @ start of mission, and then the MoveTime_dt will be set
            MobileMinMoveDist_km = min_move_dist_km;
            MobileMaxMoveDist_km = max_move_dist_km;
            MobileSWPoint = mobile_SW_point;//Best be sure they really are teh SW & NE points & not mixed up somehow.  Though it just MIGHT work regardless.
            MobileNEPoint = mobile_NE_point;

            IsEnabled = true;
            CanBeDisabled = canbedisabled;  //It's mobile; it can disappear -as a rule

            OwnerArmy = ownerarmy;
            OriginalOwnerArmy = ownerarmy;
            AttackingArmy = 3 - ownerarmy;
            if (AttackingArmy > 2 || AttackingArmy < 1) AttackingArmy = 0;

            double z = Calcs.LandElevation_m(Pos); //saving altitude/elevation of the objective.
            if (AttackingArmy == 1) z = Calcs.meters2feet(z); //(in feet for Red army)
            Pos = new Point3d(Pos.x, Pos.y, z);

            if (AttackingArmy != 0)
            {
                HUDMessage = ArmiesL[AttackingArmy] + " destroyed " + Name;
                LOGMessage = "Heavy damage to " + Name + " - good job " + ArmiesL[AttackingArmy] + "!!!";
            }
            else
            {
                HUDMessage = Name + " was destroyed";
                LOGMessage = Name + " was destroyed";
            }

            Points = points;
            TriggerType = ""; //used for CLoD internal triggers, which have a name like TGroundtarget
            TriggerPercent = 0; //we're not using this here, it is only for CloD built-in triggers
            Pos = new Point3d(x, y, 0);
            string keyp = Calcs.doubleKeypad(Pos);
            /* Sector = msn.GamePlay.gpSectorName(x, y).ToString() + "." + keyp;
            Sector = Sector.Replace(",", ""); // remove the comma     */
            Sector = Calcs.correctedSectorNameDoubleKeypad(msn, Pos);
            bigSector = Calcs.makeBigSector(msn, Pos, Points);

            radius = rad;

            TriggerDestroyRadius = trigrad;

            RadarEffectiveRadius = radar_effective_radius_m;

            OrdnanceRequiredToTrigger_kg = orttkg;
            OrdnanceOnTarget_kg = 0; //stores how much ordinance has been piled on this target
            ObjectsRequiredToTrigger_num = orttn;
            ObjectsDestroyed_num = 0;
            ActorsRequiredToTrigger_num = arttn; //these are actors killed which MATCH the Chief prefix (ie, 3001_Chief - each individual actor will be 3001_Chief1, 3001_Chief2, etc)
            ActorsDestroyed_num = 0;

            TimetoRepairIfDestroyed_hr = ttr_hr;
            Destroyed = false;
            DestroyedPercent = 0;
            ObjectiveAchievedForPoints = false;
            TimeToUndestroy_UTC = null;
            LastHitTime_UTC = null;

            Scouted = false;
            lastScoutedPos = Pos;
            lastScoutedSector = Sector;
            PlayersWhoScoutedNames = new Dictionary<string, int>();
            PlayersWhoContributedNames = new HashSet<string>();
            PlayersWhoRepairedNamesTimes = new Dictionary<string, int>();

            hasGeneralStaff = false;

            IsPrimaryTarget = false;
            PrimaryTargetWeight = primary_target_weight;
            Comment = comment;


        }

        //Checks whether mobile objective has Chiefs (it should) and if so, reloads them
        public bool reloadMobileObjectiveChiefs()
        {

            if (Destroyed || !IsEnabled || MOMobileObjectiveType == null || MOMobileObjectiveType == MO_MobileObjectiveType.None) return false;
            if (hasChief() && hasChiefGroundactorsButTheyAreDeadOrDestroyed()) msn.MO_HandleMobileObjectivePlacement(this, reestablishObjective: true);
            return true;

        }
        //ALWAYS use this to load an objective's initial submission - it will do things like making sure
        //it is appropriate to load, making sure it is set up for the right army, etc.
        public bool loadInitSubmission()
        {
            //load submission if requested
            if (InitSubmissionName != null && InitSubmissionName.Length > 0 && !Destroyed && IsEnabled)
            {

                string s = msn.CLOD_PATH + msn.FILE_PATH + "/" + InitSubmissionName;
                try
                {

                    msn.Timeout(5, () =>
                    {
                        //ISectionFile printSectionFile(ISectionFile f, maddox.game.IGamePlay GamePlay, AMission mission, int army)
                        ISectionFile f = msn.GamePlay.gpLoadSectionFile(s);
                        f = Calcs.changeArmy_Waypoints_SectionFile(f, msn.GamePlay, msn, changeToArmy: OwnerArmy, maxWaypoints_remove: 15, maxPercentWaypoints_remove: 30);
                        if (msn.ON_TESTSERVER) Console.WriteLine("PostmissionLoad: Objective init submission ");
                        msn.GamePlay.gpPostMissionLoad(f);
                        f.save(msn.CLOD_PATH + msn.FILE_PATH + "/sectionfiles/" + "printSectionFile-" + ID + ".mis"); //testing
                        //msn.GamePlay.gpPostMissionLoad(s);
                        Console.WriteLine(s.Replace(msn.CLOD_PATH + msn.FILE_PATH, "") + " initial submission file loaded for " + ID + " " + Name);
                    });
                    return true;
                }
                catch (Exception ex) { Console.WriteLine("loadInitSubmission ERROR InitSubmission for Objective NOT loaded: {0} \n\n {1}", s, ex.ToString()); return false; }

                //
            }

            if (Destroyed) Console.WriteLine(Name + ": " + InitSubmissionName + " initsubmission NOT loaded because this objective is destroyed.");

            return false;
        }

        public bool hasChief()
        {
            if (ChiefName != null && ChiefName.Length > 0) return true;
            return false;
        }
        //Return cleaned up ID string that can be used for chief name or (for example)
        //as static name in .mis files.  Returns mo.ID by default or cleaned up for any string.
        public string IDtoCleanChiefName(string i = "")
        {
            if (i == "") i = ID;
            return i.Replace(' ', '_').Replace('.', '_').Replace('\\', '_');
        }
        //moving is like a train, submarine, convoy, ship that is underway, a "chief"
        //So now that we have actual "chiefs" on nonmoving objectives we have to differentiate
        //I'm not really sure how to except that moving things include "chief" in their name
        //However, AA/artillery & some other things do, too.
        public bool isMoving()
        {
            if (ChiefName == null && ChiefName.Length == 0) return false;
            if (ChiefName.ToLower().Contains("chief")) return true;
            return false;
        }
        public int getAndAdvance_AutoFlak_location_pointer()
        {
            try
            {
                if (AutoFlak_locations_pointer < 0) AutoFlak_locations_pointer = 0;
                AutoFlak_locations_pointer++;
                lock (msn.AutoFlak_locations_lock)
                {

                    if (msn.AutoFlak_locations == null  || !msn.AutoFlak_locations.Keys.Contains(ID) || msn.AutoFlak_locations[ID] == null)
                        AutoFlak_locations_pointer = 0;
                    else if (AutoFlak_locations_pointer >= msn.AutoFlak_locations[ID].Count) AutoFlak_locations_pointer = 0;
                }
                return AutoFlak_locations_pointer;
            }
            catch (Exception ex)
            {
                Console.WriteLine("getAndAdvance_AutoFlak_location_pointer ERROR: " + ex.Message);
                return 0;
            }
        }

        //msn.AutoFlak_locations is a separate structure so we can lock it & keep 
        //it 'threadsafe'.  We hope.
        public Point3d? getNext_AutoFlak_location()
        {
            try {
                var ret = new Point3d();
                int i = getAndAdvance_AutoFlak_location_pointer();
                lock (msn.AutoFlak_locations_lock)
                {
                    if (msn.AutoFlak_locations == null || !msn.AutoFlak_locations.Keys.Contains(ID) || msn.AutoFlak_locations[ID] == null) return null;
                    return msn.AutoFlak_locations[ID][i];
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("getNext_AutoFlak_location ERROR: " + ex.Message);
                return null;
            }
        }
        public List<Point3d> get_AutoFlak_locations()
        {
            try
            {
               
                lock (msn.AutoFlak_locations_lock)
                {
                    if (msn.AutoFlak_locations == null || !msn.AutoFlak_locations.Keys.Contains(ID) || msn.AutoFlak_locations[ID] == null) return new List<Point3d>();
                    return msn.AutoFlak_locations[ID];
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("get_AutoFlak_locations ERROR: " + ex.Message);
                return new List<Point3d>();
            }
        }
        public void fixDestructionValues()
        {
            if (Double.IsNaN(DestroyedPercent)) DestroyedPercent = 0;
            if (Double.IsPositiveInfinity(DestroyedPercent)) DestroyedPercent = 1;
            if (Double.IsNegativeInfinity(DestroyedPercent)) DestroyedPercent = -.5;

            if (Double.IsNaN(AirfieldDamagePoints)) AirfieldDamagePoints = 0;
            if (Double.IsPositiveInfinity(AirfieldDamagePoints)) AirfieldDamagePoints = AirfieldPointsRequired;
            if (Double.IsNegativeInfinity(AirfieldDamagePoints)) AirfieldDamagePoints = -.5 * AirfieldPointsRequired;

            if (Double.IsNaN(ActorsDestroyed_num)) ActorsDestroyed_num = 0;
            if (Double.IsPositiveInfinity(ActorsDestroyed_num)) ActorsDestroyed_num = ActorsRequiredToTrigger_num;
            if (Double.IsNegativeInfinity(ActorsDestroyed_num)) ActorsDestroyed_num = -.5 * ActorsRequiredToTrigger_num;

            if (Double.IsNaN(ObjectsDestroyed_num)) ObjectsDestroyed_num = 0;
            if (Double.IsPositiveInfinity(ObjectsDestroyed_num)) ObjectsDestroyed_num = ObjectsRequiredToTrigger_num;
            if (Double.IsNegativeInfinity(ObjectsDestroyed_num)) ObjectsDestroyed_num = -.5 * ObjectsRequiredToTrigger_num;

            if (Double.IsNaN(OrdnanceOnTarget_kg)) OrdnanceOnTarget_kg = 0;
            if (Double.IsPositiveInfinity(OrdnanceOnTarget_kg)) OrdnanceOnTarget_kg = OrdnanceRequiredToTrigger_kg;
            if (Double.IsNegativeInfinity(OrdnanceOnTarget_kg)) OrdnanceOnTarget_kg = -.5 * OrdnanceRequiredToTrigger_kg;

        }

        public double adjustDestroyedPercent(double newDestroyedPercent)
        {
            //So for actors & objects destroyed, if these numbers become NEGATIVE
            //the problem is that there may not be enough actors left to kill the target!  At all!
            //So we put a limit.  But if we reduce here, we add a bit more to the ordnance requirement.
            //For targets like ships with very few actors, there is no ordnance requirement, so it still works OK.  Those are just UNABLE to have truly negative destroyedpercent.

            //This shouldn't ever happen, but just in case . . . 
            if (Double.IsNaN(newDestroyedPercent)) newDestroyedPercent = 0;

            ActorsDestroyed_num = newDestroyedPercent * ActorsRequiredToTrigger_num;
            double ordnance_fact = 1;
            if (ActorsDestroyed_num< 0)
            {
                ActorsDestroyed_num = ActorsDestroyed_num / 3;
                if (ActorsDestroyed_num < -ActorsRequiredToTrigger_num / 3) ActorsDestroyed_num = -ActorsRequiredToTrigger_num / 3;
                ordnance_fact *= 1.3333;
            }           
            ObjectsDestroyed_num = newDestroyedPercent * ObjectsDestroyed_num;
            if (ObjectsDestroyed_num < 0)
            {
                ObjectsDestroyed_num = ObjectsDestroyed_num / 3;
                if (ObjectsDestroyed_num < -ObjectsRequiredToTrigger_num / 3) ObjectsDestroyed_num = -ObjectsRequiredToTrigger_num / 3;
                ordnance_fact *= 1.3333;
            }
            OrdnanceOnTarget_kg = newDestroyedPercent * OrdnanceRequiredToTrigger_kg * ordnance_fact;
            AirfieldDamagePoints = newDestroyedPercent * AirfieldPointsRequired;
            DestroyedPercent = newDestroyedPercent;
            //really should do the calculation about time left to undestroy here, also
            //but for now it is done in ObjectiveRepairMissions

            //But if it is destroyed, but destroyedpercent is now 0 or negative, it IS 
            //definitely time to undestroy it now.  We don't actually need to 
            //handle the undestruction here as the normal _recurs routine will handle it
            if (Destroyed && DestroyedPercent <= 0) TimeToUndestroy_UTC = DateTime.UtcNow;
            return DestroyedPercent;
        }
        //The num of defense units will last until expiration date, which is by default 7 days
        //Also adjusts obj repair time appropriately to include new DUs
        //tuple is <new total DUs, amount repair sped up (hours)>
        public Tuple<int, double> addDefenseUnits(int numToAdd = 1, double daysUntilExpiration = 13)
        {
            try
            {
                int oldDefenseUnits = numDefenseUnits();
                
                DateTime currTime_UTC = DateTime.UtcNow;
                DateTime dt = DateTime.UtcNow.AddDays(daysUntilExpiration); //we'll say defense unit last for 13 days by default
                if (DefenseUnits == null) DefenseUnits = new SortedDictionary<DateTime, int>();
                DefenseUnits[dt] = numToAdd;

                TimeSpan time_remaining = TimeSpan.Zero;
                if (TimeToUndestroy_UTC.HasValue) time_remaining = TimeToUndestroy_UTC.Value.Subtract(currTime_UTC);

                //If the OBJ is destroyed then the new defense crews will speed up repair
                //up to 2X if a full 10 loads delivered
                //This isn't as dramatic as repair loads - it is more crews that can work over time
                //to repair things a bit faster
                double hours_left = time_remaining.TotalHours;
                double new_hours_left = hours_left;
                if (hours_left < 0 || !Destroyed) hours_left = 0; //timetoundestroy is meaniningless unless the MO is actually destroyed
                if (hours_left > 0)
                {
                    //we take some time off repairs for the new DU.  But the following formula
                    //ensures that there are diminishing returns, the 20th unit helps a lot 
                    //less than the first, etc.  Also, how much additional units add, is 
                    //diminished by how many existing units are already in place.
                    //It takes 20 DUs to speed up repair by 2X
                    double duf_add = Math.Pow(Math.Abs(numToAdd + oldDefenseUnits), 0.7) - Math.Pow(Math.Abs(oldDefenseUnits), 0.7) / Math.Pow(20,0.7);
                    double newDefenseUnits_factor = 1 + duf_add;

                    new_hours_left = hours_left / newDefenseUnits_factor;
                    TimeToUndestroy_UTC = currTime_UTC.AddHours(new_hours_left);
                }
                return new Tuple<int, double>(oldDefenseUnits + numToAdd, hours_left - new_hours_left);
            } catch (Exception ex) {
                Console.WriteLine("MO addDefenseUnits ERROR: " + ex.ToString());
                return new Tuple<int, double>(numToAdd, 0); 
            }

        }
        
        public int numDefenseUnits()
        {
            if (DefenseUnits == null) return 0;
            int ndu = 0;
            DateTime dt = DateTime.UtcNow;
            foreach (DateTime exp_dt in DefenseUnits.Keys.ToList())
            {
                try
                {
                    if (dt.CompareTo(exp_dt) <= 0) ndu += DefenseUnits[exp_dt];
                    else DefenseUnits.Remove(exp_dt); //remove any old/expired defense units
                }
                catch (Exception ex) { }
            }
            return ndu;
        }
        //defense units speed up the OBJ's repairs.  But there is a somewhat tricky formula
        //More defense units have diminishing returns...
        public double defenseUnitsHelpFactor()
        {
            return 1 + Math.Pow(Math.Abs(numDefenseUnits()), 0.7) / Math.Pow(10.0, 0.7);            
        }

