    public int MO_MissionObjectivesNear(Point3d p, double dist_m)
    {
        int total = 0;
        List<string> keys = new List<string>(MissionObjectivesList.Keys);
        foreach (var key in keys)
        {
            MissionObjective mo = MissionObjectivesList[key];
            double d_m = Calcs.CalculatePointDistance(mo.Pos, p);
            if (d_m <= dist_m) total++;
        }
        return total;
    }

    //2021-11 Jubilee: The turn map requirements can vary, sometimes just a few, sometimes many points required to turn the map
    //This is calculated indpendently for each army, randomly, and saved to disk so that we 
    //know/remember what is required to turn
    public void MO_CalculateTurnMapRequirements(int army)
    {
        /*
        public double MO_MaxPrimariesRequired 150;
    public double MO_MinPrimariesRequired = 10;
    public double MO_MinMaxPolarization = 0.8;
        */
        double rn = Math.Pow(random.NextDouble(), MO_MinMaxPolarization);
        Console.WriteLine(" MO_CalculateTurnMapRequirements: rn = {0:n4}", rn);
        if (random.Next(0, 2) == 1) rn = 1 - rn;
        Console.WriteLine(" MO_CalculateTurnMapRequirements: rn = {0:n4}", rn);

        MO_PrimaryPointsRequired[(ArmiesE)army] = Math.Round((MO_MaxPrimariesRequired - MO_MinPrimariesRequired) * rn + MO_MinPrimariesRequired);

        /*  2022/11/25 - with new scheme (fixed # of points required, primaries are a small but flexible part of that) the below calcs are NOT NEEDeD or WANTED
         *  
        double extraObjectives = MO_PointsRequired[(ArmiesE)army] * 0.4;
        if (extraObjectives < 10) extraObjectives = 10;
        
        MO_PointsRequiredWithMissingPrimary[(ArmiesE)army] = MO_PointsRequired[(ArmiesE)army] + extraObjectives;

        double noPrimaries = MO_PointsRequiredWithMissingPrimary[(ArmiesE)army] * 1.2;
        if (noPrimaries < 30) noPrimaries = 30;

        MO_PointsRequiredWithNoPrimary[(ArmiesE)army] = MO_PointsRequiredWithMissingPrimary[(ArmiesE)army] + noPrimaries;

        MO_PercentPrimaryTargetsRequired[(ArmiesE)army] = 80;
        if (MO_PointsRequired[(ArmiesE)army] < 20) MO_PercentPrimaryTargetsRequired[(ArmiesE)army] = 92;
        if (MO_PointsRequired[(ArmiesE)army] < 35) MO_PercentPrimaryTargetsRequired[(ArmiesE)army] = 86;

        */

        Console.WriteLine(" MO_CalculateTurnMapRequirements: {0:n0}, {1:n0},  {2:n0},  {3:n0},  {4:n0}", MO_PrimaryPointsRequired[(ArmiesE)army], MO_PointsRequired[(ArmiesE)army], MO_PointsRequiredWithMissingPrimary[(ArmiesE)army], MO_PointsRequiredWithNoPrimary[(ArmiesE)army], MO_PercentPrimaryTargetsRequired[(ArmiesE)army]);//, extraObjectives, noPrimaries );

        //write calculation TO DISK/save
        MO_initializeTurnMapPointsRequired_toLargeDict(); //copies them into the dictionary that is then saved
        MO_WriteMissionObject(MO_TurnMapPointsRequired, "MO_TurnMapPointsRequired", wait: false);
    }

    //This creates a randomized list of Blue or Red Primary Objectives totalling (at least) the required point total
    //And sets the IsPrimaryTarget flag for each in that army, de-selecting the IsPrimaryTarget flag for all others
    //Only chooses from those in the PrimaryTargetWeight     
    //Will do either army=1 or army=2 or BOTH ARMIES if army=0   
    public void MO_SelectPrimaryObjectives(int army = 0, double totalPoints = 0, bool fresh = false, bool eraseOnly = false, bool eraseForPoints = false)
    {

        List<string> keys = new List<string>(MissionObjectivesList.Keys);
        Calcs.Shuffle(keys);

        List<int> arms = new List<int>();
        if (army == 0) { arms.Add(1); arms.Add(2); }
        else if (army == 1 || army == 2) arms.Add(army);

        Console.WriteLine("Selecting new Mission Objectives for " + ArmiesL[army]);

        foreach (var a in arms)
        {
            string objectivesList = "";
            //first, reset all the targets (in this army) to be not primaries.  
            //But ONLY if we are starting fresh; ie, choosing ALL the primaries now
            //If some have already been chosen, we have to respect the previously chosen IsPrimaryTarget = true;          
            if (fresh) foreach (var key in keys)
                {
                    if (MissionObjectivesList[key].AttackingArmy == a)
                    {
                        MissionObjectivesList[key].IsPrimaryTarget = false;
                        if (eraseForPoints)
                        {
                            MissionObjectivesList[key].ObjectiveAchievedForPoints = false; //TOBRUK, if you don't zero this out the army can't achieve their

                            //2021-11 Jubilee - targets just stay destroyed until their expiration date
                            //MissionObjectivesList[key].Destroyed = false;
                            //MissionObjectivesList[key].DestroyedPercent =0;
                        }
                    }
                }

            if (eraseOnly) continue;

            if (fresh) MO_CalculateTurnMapRequirements(a);

            int counter = 1;

            for (int x = 0; x < 250; x++) //unlikely but possible that we'd need to cycle through the list of targets multiple times to select enough targets to reach the points. Could happen though if PrimaryTargetWeights are set low, or only a few possible objectives available in the list. 
            {
                foreach (var key in keys)
                {
                    //Objectives remain destroyed for a long time now.  So we'll choose fresh
                    //objectives if possible but if there are not too many of them, we'll
                    //re-used destroyed ones
                    bool canChooseDestroyed = false;
                    if (x > 15) canChooseDestroyed = true;

                    MissionObjective mo = MissionObjectivesList[key];
                    if (mo.AttackingArmy == a && mo.PrimaryTargetWeight > 0 && mo.IsEnabled && !mo.IsPrimaryTarget && ((!mo.Destroyed && mo.DestroyedPercent <= 0.25) || canChooseDestroyed) && !mo.ObjectiveAchievedForPoints)
                    {
                        double r = stb_random.NextDouble() * 200; //was 100.  This will cut chance of everything being chosen, in half.  Except airports and a few other things, which we increased by a lot.  2020-01

                        /*Console.WriteLine("Select Primary " + mo.PrimaryTargetWeight + " " + r.ToString("N4") + " " + mo.ID + " points req: " 
                            //+ MO_BRBumrushInfo[(ArmiesE)a].PointsRequiredToBeginBumrush.ToString("N0") + totalPoints.ToString("N0")
                            );
                        */
                        Point3d pos = mo.returnCurrentPosWithChief();

                        //Except for the very highest-weighted mission objectives, make them more likely to be chosen if near the front,; less likely if distant
                        //double frontDistance = GamePlay.gpFrontDistance(mo.AttackingArmy, pos.x, pos.y);

                        //CHANNEL MAP/FRENCH POINT SPECIAL.  We choose a point in the middle of the channel, french point-
                        //english point and that becomes our central point.
                        double frontDistance = (Calcs.CalculatePointDistance(new Point3d(261615, 224384, 0), pos));

                        double distanceMult = 1;
                        //if (mo.PrimaryTargetWeight<100)

                        //We can force a few special targets to be highly prioritized by setting weight>180 if we want

                        //THIS was our method starting 11/2021 or so when we wanted to concentrate primary targets near the front
                        /* if (mo.PrimaryTargetWeight < 180)
                        {
                            //Channel - few things are > 150K from front. <80K is close to front, <120K includes most of london, Le  Havre
                            //Nice effect that as front moves across the channel, the winners will have to go ever further afield for their objectives, while the losers objectives will be more concentrated around French/English point
                            if (frontDistance > 150000) distanceMult = 0.1;
                            else if (frontDistance > 120000) distanceMult = 0.2;
                            else if (frontDistance > 100000) distanceMult = 0.3;
                            else if (frontDistance > 80000) distanceMult = 0.75;
                            else if (frontDistance > 50000) distanceMult = 0.9;
                        }*/

                        //This is the method startgin 11/2022 when the players can CHOOSE most of their targets
                        //Therefore the few chosen primaries are FURTHER AND MORE DIFFICULT as a rule
                        if (mo.PrimaryTargetWeight < 180)
                        {
                            //Channel - few things are > 150K from front. <80K is close to front, <120K includes most of london, Le  Havre
                            //Nice effect that as front moves across the channel, the winners will have to go ever further afield for their objectives, while the losers objectives will be more concentrated around French/English point
                            if (frontDistance > 150000) distanceMult = 0.1;
                            else if (frontDistance > 120000) distanceMult = 0.3;
                            else if (frontDistance > 100000) distanceMult = .7;
                            else if (frontDistance > 80000) distanceMult = 1;
                            else if (frontDistance > 50000) distanceMult = 0.3;
                        }

                        //Console.WriteLine("Select Primary " + mo.PrimaryTargetWeight + " " + r.ToString("N4") + " " + mo.ID);
                        if (mo.PrimaryTargetWeight * distanceMult < r) continue; //implement weight; if weight is less than the random number then this one is skipped; so 200% is never skipped, 100% skipped half the time, 50% 3/4 of the time, 0% skipped always
                        if (totalPoints < MO_PrimaryPointsRequired[(ArmiesE)a])
                        {
                            mo.IsPrimaryTarget = true;
                            totalPoints += mo.Points;
                            objectivesList += " - " + mo.lastScoutedSector + " " + mo.Name;
                            Console.WriteLine("Adding new Mission Objective: " + mo.lastScoutedSector + " " + mo.Name + " " + mo.Points.ToString("F0") + " " + totalPoints.ToString("F0"));
                            //if (counter % 3 == 0) MissionObjectivesString[(ArmiesE)a] += Environment.NewLine;
                            counter++;
                            if (totalPoints >= MO_PrimaryPointsRequired[(ArmiesE)a]) break;
                        }
                        else
                        {
                            mo.IsPrimaryTarget = false;
                        }

                    }

                }
                if (totalPoints >= MO_PrimaryPointsRequired[(ArmiesE)a]) break;
            }
            Console.WriteLine("Selecting/adding new Mission Objectives for " + ArmiesL[army] + ":");
            //Console.WriteLine(objectivesList);
        }
        Timeout(12.354, () => { MO_SelectPrimaryObjectiveForGeneralStaffLocation(army); });

    }

    public void MO_SelectPrimaryObjectiveForGeneralStaffLocation(int army = 0, double totalPoints = 0)
    {

        List<string> keys = new List<string>(MissionObjectivesList.Keys);
        Calcs.Shuffle(keys);

        List<int> arms = new List<int>();
        if (army == 0) { arms.Add(1); arms.Add(2); }
        else if (army == 1 || army == 2) arms.Add(army);

        Console.WriteLine("Selecting new Mission General Staff Location at a Primary Objective for " + ArmiesL[army]);

        foreach (var a in arms)
        {
            //first, reset all the targets (in this army) to be not the General Staff Location.            
            foreach (var key in keys)
            {
                if (MissionObjectivesList[key].AttackingArmy == a) MissionObjectivesList[key].hasGeneralStaff = false;
            }

            int counter = 1;

            for (int x = 0; x < 50; x++) //unlikely but possible that we'd need to cycle through the list of targets multiple times to select enough targets to reach the points. Could happen though if PrimaryTargetWeights are set low, or only a few possible objectives available in the list. 
            {
                bool done = false;
                foreach (var key in keys)
                {
                    MissionObjective mo = MissionObjectivesList[key];
                    if ((mo.AttackingArmy == a || x > 17) && (mo.IsEnabled || x > 15) && (mo.IsPrimaryTarget || x > 10) && (!mo.Destroyed || x > 4) && (!mo.ObjectiveAchievedForPoints || x > 1) && ((!MO_Naval_Ship_ObjectiveTypes.Contains(mo.MOObjectiveType) && mo.MOObjectiveType != MO_ObjectiveType.Submarine) || x > 40)) //allows various exceptions after we have tried & failed several times
                    {
                        mo.hasGeneralStaff = true;
                        done = true;
                        break;
                    }
                }
                if (done) break;
            }
        }
    }

    public class GeneralStaffLocationObject
    {
        public Point3d pos { get; set; }
