    public class MO_ThingsTypeNumberRadius
    {
        public List<string> things { set; get; }
        public int howmany { set; get; } //approx how many to place
        public int howmany_min { set; get; } //approx how many to place
        public bool use_howmany_min { get; set; } //if true will choose # between howman_min & howmany (as max)
        public double radius_m { set; get; } //approx radius from center to place them.  This will vary by +/- 20% or so
        public double range_m { set; get; } //Range this far in/out from the radius.  So radius 10m, range 10m will place the objects from 0 to 20m from the center.
        public double probability { set; get; } //Probability this element will appear at all. Can range 0-1. 1 (always appearing) is the default
        public double orientationAngle_deg { set; get; }
        public shapeType shape { set; get; } //you specific a list<shapeType> and here we will choose ONE of those shapes to actually be the shape this time around
        private Random ran = new Random();


        //For a specified # of things
        public MO_ThingsTypeNumberRadius(List<string> t, int hm = 7, double rm = 25, double rn = 25, double prob = 1, List<shapeType> shps = null, double orient_angle_deg = -1) 
        {
            things = t;
            howmany = hm;
            howmany_min = hm;
            use_howmany_min = false;
            radius_m = rm;
            range_m = rn;
            probability = prob;
            if (shps == null) shape = shapeType.StretchedCircle;
            else shape = Calcs.chooseRandomElement(shps); 
            orientationAngle_deg = ran.NextDouble() * 360;
            if (orient_angle_deg != -1) orient_angle_deg = orient_angle_deg;
        }
        //If we want a larger specified range of this item
        //range is INCLUSIVE< ie 3-8 will sometimes give 3 and sometimes 8
        public MO_ThingsTypeNumberRadius(List<string> t, bool useHowManyRange, int howMany_Min = 0, int howMany_Max = 7, double rm = 25, double rn = 25, double prob = 1, List<shapeType> shps = null, double orient_angle_deg = -1)
        {
            things = t;
            howmany = howMany_Max;
            howmany_min = howMany_Min;
            use_howmany_min = useHowManyRange;
            radius_m = rm;
            range_m = rn;
            probability = prob;
            orientationAngle_deg = ran.NextDouble() * 360;
            if (orient_angle_deg != -1) orient_angle_deg = orient_angle_deg;
            if (shps == null) shape = shapeType.StretchedCircle;
            else shape = Calcs.chooseRandomElement(shps);
        }
        public MO_ThingsTypeNumberRadius(MO_ThingsTypeNumberRadius mttnr, double oa_deg = -1)
        {
            things = mttnr.things;
            howmany = mttnr.howmany;
            howmany_min = mttnr.howmany_min;
            use_howmany_min = mttnr.use_howmany_min;
            radius_m = mttnr.radius_m;
            range_m = mttnr.range_m;
            probability = mttnr.probability;
            orientationAngle_deg = mttnr.orientationAngle_deg;
            if (oa_deg != -1) orientationAngle_deg = oa_deg;

        }
    }

