    ISectionFile f_placeCameras = null;

    public void MO_FinalizeCameras()
    {

        return;
        //unfortunately cameras are not really working at all - you just can't get to them any way
        //MO_MakeCameras(f_placeCameras, mo.returnCurrentPosWithChief(), staticprefix: mo.ID);

        if (ON_TESTSERVER) Console.WriteLine("PostmissionLoad: FinalizePlaceCameras");
        GamePlay.gpPostMissionLoad(f_placeCameras);

        if (!panic()) f_placeCameras.save(CLOD_PATH + FILE_PATH + "/sectionfiles" + "/placestaticcameras_"); //testing)

        f_placeCameras = GamePlay.gpCreateSectionFile();
    }

    public void MO_MakeCameras(MissionObjective mo)
    {
        if (f_placeCameras == null) f_placeCameras = GamePlay.gpCreateSectionFile();
        f_placeCameras = MO_MakeCameras(f_placeCameras, mo.returnCurrentPosWithChief(), staticprefix: "statcam_" + mo.ID.Substring(1));
    }

    public ISectionFile MO_MakeCameras(ISectionFile f, Point3d pos, string staticprefix = "")
    {
        for (int i = -1; i<6; i++)
        {
            //Point3d thingPos = pos;
            double height_m = Math.Pow(2, i) * 100;
            if (i == -1) height_m = 3;

            f = Calcs.makeStatic(f, GamePlay, this, pos.x, pos.y, height_m , type: "StaticCamera" , sect: "StaticCamera", staticprefix: staticprefix);

        }
        return f;
    }

    public enum shapeType { Circle, StretchedCircle, Rectangle, Line, DoubleLine };

	//subHeading -1, choose a random heading for each object
	//subHeading -2 means align with the circle perimeter, ie tangent to the circle
	//variance is a random amount the object will be moved inside OR outside the circle radius (up to variance_m distance plus or minus)
	//orientationAngle is orientation of the square, rectangle, line, double line etc.  
	//for circle, doesn't matter.  -1 means choose a randome orientation
	public ISectionFile PlaceObjectsInCircles(ISectionFile f, List<string> things, Point3d newPos, double radius_m, double variance_m, int howmany, int army, int percentSide = 33, double subHeading_deg = -1,
	int stretcherType = 0, double stretcherAmt = 0, bool avoidWater = false, bool resetCount = false,
	string addString = "", bool randomizeHowmany = true, string staticprefix = "", shapeType shape =  shapeType.StretchedCircle, double orientationAngle_deg = -1 )
    { 
        string ownerside = "nn";
        if (army == 2) ownerside = "de";
        if (army == 1) ownerside = "gb";
        double orientationAngle_rad = random.NextDouble() * Math.PI * 2;
        if (orientationAngle_deg != -1) orientationAngle_rad = Calcs.DegreesToRadians(orientationAngle_deg);

        //Calcs.Shuffle(things);
        if (randomizeHowmany) howmany += random.Next(howmany / 4) - howmany / 8; //slightly randomize howmany
        //Console.WriteLine("Cirles: " + howmany.ToString());

        bool rstCnt = resetCount;

        for (int i = 0; i < howmany; i++)
        {

            string side = "nn";
            if (random.Next(100) <= percentSide) side = ownerside; //setting them as enemy makes them show up as black dots. So some, but not all.

            double angle1 = 0;

            Point3d thingPos = new Point3d(newPos.x, newPos.y, newPos.z);
            if (radius_m <= 5)
            {
                thingPos.x = newPos.x + (random.NextDouble() * 2.0 - 1.0) * radius_m;
                thingPos.y = newPos.y + (random.NextDouble() * 2.0 - 1.0) * radius_m;
            }
            else
            {
                /*
                angle1 = i * 2.0 / howmany * Math.PI + random.NextDouble() / howmany * Math.PI * 2.0 / 3.0;
                double radius1 = radius_m + (circleStretcher(angle1, stretcherAmt, stretcherType));
                double radius2 = (random.NextDouble() * 2.0 - 1.0) * variance_m + radius1; //vary by up to variance amount, plus or minus from given radius.

                thingPos.x = newPos.x + Math.Cos(angle1) * radius2;
                thingPos.y = newPos.y + Math.Sin(angle1) * radius2;
                */
                switch (shape)
                {
                    case shapeType.Circle:
                    thingPos = Calcs.pointsOnACircle(newPos, radius_m, howmany, i, 1 / (double)howmany * Math.PI * 2.0 / 3.0, variance_m);
                        break;
                    case shapeType.Rectangle:
                        thingPos = Calcs.pointsOnARectangle(newPos, radius_m, radius_m * variance_m, orientationAngle_rad, howmany, i, radius_m / 8 );
                        break;
                    case shapeType.DoubleLine:
                        thingPos = Calcs.pointsOnADoubleLine(newPos, radius_m, radius_m * variance_m,  orientationAngle_rad, howmany, i, radius_m / 8);
                        break;

                    case shapeType.Line:
                        thingPos = Calcs.pointsOnALine(newPos, radius_m, orientationAngle_rad, howmany, i, radius_m / 10);
                        break;

                    case shapeType.StretchedCircle:
                    default:
                        thingPos = Calcs.pointsOnAStretchedCircle(newPos, radius_m, howmany, i, 1 / (double)howmany * Math.PI * 2.0 / 3.0, variance_m, stretcherAmt, stretcherType);
                        break;
                }
            }

            double subsubHeading = subHeading_deg + random.Next(24) - 12;
            if (subHeading_deg == -1) subsubHeading = random.Next(360);

            angle1 = i * 2.0 / howmany * Math.PI + random.NextDouble() / howmany * Math.PI * 2.0 / 3.0;
            if (subHeading_deg == -2) subsubHeading = Calcs.RadiansToDegrees(angle1); //reverse angle seems to work best (otherwise angle trenches etc are angled the wrong way relative to the circle) 2020/02/24 now trying the original angle as the arch sandbags seem reversed & are common
            //Console.WriteLine("Cirles: {0:F2} {1:F2} {2:F2} " + howmany.ToString(), angle1, subHeading, subsubHeading);


            if (avoidWater) thingPos = MO_FindNoWaterPos(thingPos, radius_m);

            int ranThing = random.Next(things.Count);

            //special mod to keep the WW1 Steamer and MTBs from going crazy with a lot of fire/slowing CPU
            var moderateMilitaryShips = new List<string>() { "ShipUnit.Rion", "Schnellboot", "Vosper", "Leipzig" };

            var hardcoreMilitaryShips = new List<string>() { "Zara", "SanGiorgio", "1936_DD", "Spica", "Minensuchtboote", "Hospital_Ship", "QueenElizabeth", "Revenge", "Leander", "Tribal", "Corvette" };

            //Sleep 10 makes them sleep for 10 mins at the beginning of the mission, or whenever they are loaded
            //Skill 0 makes them rookies
            //slowfire 100 makes them fire 100X slower than normal (which would be slowfire 1)
            //2022/12 - for now we are allowing like ONE of these in the server MAX and it is supposed 
            //to be a boss target, so it needs to be MEAN and HARD.

            //these are more commonly used as escorts and so we want them to be pretty reasonably/normal
            if (moderateMilitaryShips.Any(things[ranThing].Contains)) addString = "/sleep 2/skill 2/slowfire 80";

            //These appear only VERY rarely but when they they are major bosses & should be super-hard to kill
            //skill 3 is 'ace'
            if (hardcoreMilitaryShips.Any(things[ranThing].Contains)) addString = "/sleep 2/skill 3/slowfire 1";
            
            f = Calcs.makeStatic(f, GamePlay, this, thingPos.x + random.Next(2), thingPos.y + random.Next(2), 0, type: things[ranThing], heading: subsubHeading, side: side, resetCount: rstCnt, addString: addString, staticprefix: staticprefix);
            rstCnt = false;

        }
        return f;
    }

    public double MO_CalcMobileObjRadius_m(MissionObjective mo)
    {
        if (mo.MOMobileObjectiveType != MO_MobileObjectiveType.None)
        {
            var things = mo_mobileobjectivethings[mo.MOMobileObjectiveType];

            double searchRadius_m = 50;
            if (mo.radius > 50) searchRadius_m = mo.radius;

            foreach (MO_MobileObjectiveThings t in things.Keys)
            {
                MO_ThingsTypeNumberRadius mttnr = new MO_ThingsTypeNumberRadius(things[t]);
                if (mttnr.radius_m + mttnr.range_m > searchRadius_m) searchRadius_m = mttnr.radius_m + mttnr.range_m;
            }
            return searchRadius_m;
        } else
        {
            return mo.radius;
        }

    }

    public bool MO_WaterInRadius(Point3d p, double radius_m)
    {
        Point3d testPos = new Point3d(0, 0, 0);
        for (int i = 1; i < 300; i++)
        {
            double angle1 = i; //radians
            double radius2 = i * radius_m / 200.0;
            testPos.x = p.x + Math.Cos(angle1) * radius2;
            testPos.y = p.y + Math.Sin(angle1) * radius2;
            maddox.game.LandTypes landType = GamePlay.gpLandType(testPos.x, testPos.y);
            if (landType == maddox.game.LandTypes.WATER) return true;
        }
        return false;
    }

    public bool MO_LandInRadius(Point3d p, double radius_m)
    {
        Point3d testPos = new Point3d(0, 0, 0);
        int testpoints = 300;
        if (radius_m > 2000) testpoints = Convert.ToInt32(300.0 * radius_m / 2000.0);
        for (int i = 1; i < testpoints; i++)
        {
            double angle1 = i; //radians
            double radius2 = i * radius_m / (testpoints - 10); //make it go slightly beyond the actual radius
            testPos.x = p.x + Math.Cos(angle1) * radius2;
            testPos.y = p.y + Math.Sin(angle1) * radius2;
            maddox.game.LandTypes landType = GamePlay.gpLandType(testPos.x, testPos.y);
            if (landType != maddox.game.LandTypes.WATER) return true;
        }
        return false;
    }

    //check if the pos is on water and if so try to return a new non-water pos withing the given radius
    //If it fails thne it just returns the initial point
    public Point3d MO_FindNoWaterPos(Point3d p, double radius_m)
    {
        Point3d testPos = p; //preserves p.z value
        for (int i = 0; i < 300; i++)
        {
            double angle1 = i; //radians
            double radius2 = i * radius_m / 200.0;
            testPos.x = p.x + Math.Cos(angle1) * radius2;
            testPos.y = p.y + Math.Sin(angle1) * radius2;
            maddox.game.LandTypes landType = GamePlay.gpLandType(testPos.x, testPos.y);
            if (landType != maddox.game.LandTypes.WATER) return testPos;
        }
        return p;
    }

    public void MO_PlaceDetritusInObjectArea(MissionObjective mo, int numDetrit = 6, int rangeDetrit = 6, bool placeSmoke = true, double searchRadius_m = 0, bool minimum = false)
    {
        if (ON_TESTSERVER) Console.WriteLine("Placing detritus field at " + mo.ID + " " + mo.Name);

        if (searchRadius_m == 0) searchRadius_m = MO_CalcMobileObjRadius_m(mo);
        double stretchA = (searchRadius_m + 40) / 3.0 * random.NextDouble();

        //7 * Math.Pow(Math.Ceiling(searchRadius_m/1000),2) - say it takes 7 Jerrycan282 to cover 1000m radius, if it is 2000m the amount increases by the ^2, etc

        int numCrater = (int)Math.Round((double)(numDetrit + random.Next(rangeDetrit)) / 6.0);
        if (numCrater < 2) numCrater = 2;

        ISectionFile f = GamePlay.gpCreateSectionFile();
        if (!minimum) f = PlaceObjectsInCircles(f, MO_Detritus, mo.Pos, searchRadius_m / 2, 4.0 * searchRadius_m / 5.0, numDetrit + random.Next(rangeDetrit), mo.OwnerArmy, percentSide: 0, subHeading_deg: -1, stretcherType: 1, stretcherAmt: stretchA, resetCount: true);
        if (!minimum && !Calcs.isPointInOrNearWater(GamePlay, mo.Pos, Convert.ToInt32(searchRadius_m / 2)))
        {
            f = PlaceObjectsInCircles(f, MO_BombCraters, mo.Pos, searchRadius_m / 4, 4.0 * searchRadius_m / 5.0, numCrater, 0, percentSide: 0, subHeading_deg: -1, stretcherType: 1, stretcherAmt: stretchA, resetCount: false, staticprefix: "detritus");
            f = PlaceObjectsInCircles(f, MO_Remnants, mo.Pos, 10, 10, 3, 0, percentSide: 0, subHeading_deg: -1, stretcherType: 1, stretcherAmt: 1, resetCount: false, staticprefix: "detritus");

            f = PlaceObjectsInCircles(f, MO_Remnants, mo.Pos, 45, 10, 10, 0, percentSide: 0, subHeading_deg: -1, stretcherType: 1, stretcherAmt: 10, resetCount: false, staticprefix: "detritus");

        }
        //f = PlaceObjectsInCircles(f, MO_Jerrycan282, mo.Pos, searchRadius_m / 2, 4.0 * searchRadius_m / 5.0, 7 * Math.Pow(Math.Ceiling(searchRadius_m/1000),2), mo.OwnerArmy, percentSide: 70, subHeading: -1, stretcherType: 1, stretcherAmt: stretchA);

        Timeout(55 + random.Next(1, 240), () => //no rush here, better to wait a bit
         {
             if (!minimum)
             {
                 if (ON_TESTSERVER) Console.WriteLine("PostmissionLoad: PlaceDetritus");
                 GamePlay.gpPostMissionLoad(f);

                 if (!panic()) f.save(CLOD_PATH + FILE_PATH + "/sectionfiles" + "/detritusobj_" + Calcs.GetSafeFileName(mo.ID)); //testing)
             }

             Point3d smokePos = new Point3d(mo.Pos.x + (random.NextDouble() * 2.0 - 1.0) * searchRadius_m, mo.Pos.y + (random.NextDouble() * 2.0 - 1.0) * searchRadius_m, -15); //try -z position to see if it will make a diff effect

             smokePos = MO_FindNoWaterPos(smokePos, searchRadius_m + 40);

             if (placeSmoke & !minimum) Calcs.loadSmokeOrFire(GamePlay, this, smokePos.x, smokePos.y, smokePos.z, "BuildingFireSmall", 24 * 3600);

             MO_PlaceAppropriateJerrycan(mo); //there is still a jerrycan there so players can get stats points for bombing it, but there is just no objective here any more.
         });

    }

    public void MO_RemoveObjective(MissionObjective mo, bool immediate = false, double percent = 1)
    {
        //2021/07 - removing task.run over concerns it might cause server crashes.
        //Task.Run(() =>
        //{
        try {
            //var things = mo_mobileobjectivethings[mo.MOMobileObjectiveType]; //only valid for  mobileobjective types , and we're not using it yet.

            if (ON_TESTSERVER) Console.WriteLine("MO_RemoveObjective: Removing/killing objective statics at " + mo.ID + " " + mo.Name);

            double searchRadius_m = MO_CalcMobileObjRadius_m(mo);
           
            if (MO_ObjectiveIsNavalVessel(mo))
            {
                searchRadius_m *= 3;

            }//double the search radius for ships because they DRIFT.  Even this might not be large enough.

            double radiusAdder_m = 400; //we look for AA./artillery in this additional radius

            bool destroyObjects = false; //mostly we just "kill" the objects/actors which makes them "dead" but still in the sim
            if (mo.MOMobileObjectiveType != MO_MobileObjectiveType.None) destroyObjects = true; //for mobile objective types that are actually MOVING though we actually cart.destroy() the items so that they are not on the map or on the ground any more.

            List<GroundStationary> gs = new List<GroundStationary>(GamePlay.gpGroundStationarys(mo.Pos.x, mo.Pos.y, searchRadius_m + 40).ToList());
            ISectionFile f = GamePlay.gpCreateSectionFile();
            //Stationary.Environment.Polotnische_X_white_1
            f = Calcs.makeStatic(f, GamePlay, this, mo.Pos.x, mo.Pos.y, 0, "Stationary.Environment.Polotnische_X_white_1", 0, "nn", staticprefix: "remove_destroyed_MO_");
            foreach (GroundStationary g in gs)
            {
                //For chief type objectives, we only remove items matching the chief
                //because this type is MOBILE...
                if (mo.hasChief() && !g.Name.ToLower().Contains(mo.ChiefName.ToLower())) continue;
                f = MO_HandleGroundThingRemoval(mo, g.Type, groundStationary: g, immediate: immediate, percent: percent, destroyObjects: destroyObjects, sectFile:f);
            }
            if (!MO_Naval_Vessel_ObjectiveTypes.Contains(mo.MOObjectiveType))
            {
                Timeout(random.Next(5, 120), () =>
                {
                    GamePlay.gpPostMissionLoad(f);
                    f.save(CLOD_PATH + FILE_PATH + "/sectionfiles" + "/destroy_MO_replaced_objects_" + Calcs.GetSafeFileName(mo.ID) +random.Next(1, 10).ToString());

                });
            }
            //allStaticActors doesn't get inited until 20-30 seconds into the mission start
            Timeout(40, () =>
            {
                if (covermission != null && covermission.allStaticActors != null)
                {
                    var asa = new List<AiActor>();
                    lock (covermission.allStaticActors_lock)
                    {
                        asa = new List<AiActor>(covermission.allStaticActors);
                    }
                    List<AiActor> closeStaticActors = new List<AiActor>(CoverCalcs.gpGetAllGroundActorsNear(asa.ToArray(), mo.Pos, searchRadius_m + radiusAdder_m).ToList());
                    ISectionFile f2 = GamePlay.gpCreateSectionFile();
                    foreach (AiActor a in closeStaticActors)
                    {
                        var ga = a as AiGroundActor;

                        if (ga != null)
                        {
                            //For chief type objectives, we only remove items matching the chief
                            //because this type is MOBILE...
                            if (mo.hasChief() && !a.Name().ToLower().Contains(mo.ChiefName.ToLower())) continue;

                            //Remove all actors within the radius (usually = objective radius), PLUS 
                            //any AA/Artillery from a larger radius around the objective.  Autoflak places AA 250m out, sometimes more
                            //Or if percent<1 then remove that percentage
                            double dist_m = Calcs.CalculatePointDistance(mo.Pos, (ga as AiActor).Pos());
                            if (dist_m < searchRadius_m || ga.Type() == AiGroundActorType.AAGun || ga.Type() == AiGroundActorType.Artillery)
                               f2 = MO_HandleGroundThingRemoval(mo, ga.Type(), groundActor: ga, immediate: immediate, percent: percent, destroyObjects: destroyObjects, sectFile:f2);
                        }
                    }
                    if (!MO_Naval_Vessel_ObjectiveTypes.Contains(mo.MOObjectiveType))
                    {
                        Timeout(random.Next(5, 120), () =>
                        {
                            GamePlay.gpPostMissionLoad(f2);
                            f2.save(CLOD_PATH + FILE_PATH + "/sectionfiles" + "/destroy_MO_replaced_objects_"+Calcs.GetSafeFileName(mo.ID) + random.Next(1, 10).ToString());

                        });
                    }

                }
                //Only place detritus for mobile objectives ?
                //A lot of detritus seems to slow the server quite a bit ?  Or maybe it's the smoke or ???  Or AA?
                if (percent >= 1 && mo.MOMobileObjectiveType != MO_MobileObjectiveType.None) MO_PlaceDetritusInObjectArea(mo, searchRadius_m: searchRadius_m);
                if (percent >= 1 && mo.MOMobileObjectiveType == MO_MobileObjectiveType.None) MO_PlaceDetritusInObjectArea(mo, searchRadius_m: searchRadius_m, minimum: true); //only smoke &  jerrycan
            });

            //}

            //);

        }
        catch (Exception ex) { Console.WriteLine("MO_RemoveObjective ERROR: " + ex.ToString()); }

    }

    public ISectionFile MO_HandleGroundThingRemoval(MissionObjective mo, AiGroundActorType type, AiGroundActor groundActor = null, GroundStationary groundStationary = null, bool immediate = false, double percent = 1, bool destroyObjects = false, ISectionFile sectFile = null)
    {
        try
        {
            string type_str = type.ToString().ToLower();

            if (groundStationary != null)
            {
                string gst = groundStationary.Title.ToLower();
                string gsu = groundStationary.Title;
                if (gst.Contains("fire") || gst.Contains("crater") || gst.Contains("_dmg") || gst.Contains("jerrycan") || gst.Contains("smoke")
                    || gsu.Contains("AEC_Regent_II") || gsu.Contains("MG_TA") || type_str.ToLower().Contains("unknown")) return sectFile;
            }
            //If an AA_Artillery objective, when destroyed we remove ONLY artillery & Aa from the area, leaving any other
            //ground objects.  This is because the AA usually surrounds some other objective that might still be in place.
            if (mo.MOObjectiveType == MO_ObjectiveType.Artillery_and_AA && type != AiGroundActorType.AAGun && type != AiGroundActorType.Artillery) return sectFile;

            //For percentage destroyed, for now we're just deleting the percentage destroyed of groundactors (AA, artillery, vehicles, tanks, etc).  Ships is the one exception, just because usually you only have to sink like 4 ships out of 20 for 100% victory.  So the math doesn't work.  Don't delete groundStationaries because they are bomb fodder & don't fight.
            if (percent < 1 && (groundStationary != null || type_str.Contains("ship"))) return sectFile;
            if (percent < 1 && mo.MOTriggerType == MO_TriggerType.Trigger) return sectFile;

            //If it is some percent destroyed, like 0.2, then we remove just 20% of groundACtors (like AA, vehicles, tanks)
            if (percent < 1 && random.NextDouble() > percent) return sectFile;

            //remove only ships if objective type is ships.  (Note this includes "ShipSubmarine")
            if (MO_Naval_Ship_ObjectiveTypes.Contains(mo.MOObjectiveType) && !type_str.Contains("ship")) return sectFile;

            if (mo.MOObjectiveType == MO_ObjectiveType.Submarine && !type_str.Contains("shipsubmarine")) return sectFile;


            string names = "";
            Point3d rpos = new Point3d();
            if (groundStationary != null)
            {
                names = (groundStationary.Type.ToString() + groundStationary.Title).ToLower();
                rpos = groundStationary.pos;
            }
            if (groundActor != null)
            {
                names = (groundActor.Type().ToString() + groundActor.Name()).ToLower();
                rpos = groundActor.Pos();
            }

            //So, sometimes one objective is WITHIN another, like a building is 
            //within an airfield.  In that case, if the other obj is not yet destroyed, we want
            //to keep it all there to still be able to destroy it
            foreach (MissionObjective mo2 in MissionObjectivesList.Values)
            {
                if (!mo2.IsEnabled || mo2.Destroyed) continue;
                if (mo == mo2) continue;

                //if it's chief of this OBJ or just a stationary/groundactor created specially
                //for this OBJ then don't delete it unless its your own.
                if (names.ToLower().Contains(mo.ChiefName.ToLower()) || names.ToLower().Contains(mo.IDtoCleanChiefName().ToLower()))
                {
                    Console.WriteLine("MO_HandleGroundThingRemoval: This object's name has the ID or Chief name of another OBJ, so NOT removing it: {0} {1} {2} ({3:F0},{4:F0}) stationary names {5} OBJ ID/chief {6} {7}", mo.ID, mo2.ID, names, rpos.x, rpos.y, names, mo.ChiefName, mo.IDtoCleanChiefName());
                    return sectFile;
                }
                //Don't delete things in the radius of this OBJ.
                //double radius1 = mo.radius;
                //if (mo.TriggerDestroyRadius > radius1) radius1 = mo.TriggerDestroyRadius;
                double radius2 = mo2.radius;
                if (mo2.TriggerDestroyRadius > radius2) radius2 = mo.TriggerDestroyRadius;

                //if (Calcs.CalculatePointDistance(mo.Pos, mo2.Pos) > 1.2 * (radius1 + radius2)) continue;
                if (Calcs.CalculatePointDistance(rpos, mo2.Pos) < 1.2 * radius2)
                {
                    Console.WriteLine("MO_HandleGroundThingRemoval: This object was within the radius of another objective, so NOT removing it: {0} {1} {2} ({3:F0},{4:F0})", mo.ID, mo2.ID, names, rpos.x, rpos.y);
                    return sectFile;
                }
            }

            Console.WriteLine("REMOVEOBJECTIVE: Removing G " + names + " from " + mo.Name + " at ({0:F0}{1:f0})", rpos.x, rpos.y);

            string typ = "Stationary.Environment.JerryCan_GER1_2";
            
            if (names.Contains("industrial")) typ = "Stationary.Environment.CamoNetPlaneBig";
            else if (names.Contains("building")) typ = "Stationary.Environment.TentTroopLarge_GER1"; //
            else if (names.Contains("airfield")) typ = "Stationary.Environment.CamoNetPlane";
            else if (names.Contains("aircraft")) typ = "Stationary.GladiatorMkII";
            else if (names.Contains("tent")) typ = "Stationary.Environment.CamoNetTank";
            else if (names.Contains("car")) typ = "Stationary.Opel_Blitz_fuel";
            else if (names.Contains("tank")) typ = "Stationary.Environment.TelegaBallon_UK1";
            else if (names.Contains("truck")) typ = "Stationary.Ford_G917";
            else if (random.Next(5) < 1) typ = "Stationary.Environment.CamoNetPlane";

            if (sectFile!= null) sectFile = Calcs.makeStatic(sectFile, GamePlay, this, rpos.x, rpos.y, 0, typ, 0, "nn", staticprefix: "remove_destroyed_MO_");

            //We wait, then try once to disapparate when no one is looking, but then just do it
            //Waith 120s because likely a pilot is near; gives them time to fly off
            int delay1 = 120;
            int delay2 = 1200;
            if (immediate)
            {
                if (groundActor != null)
                {
                    //groundActor.Destroy();
                    if (destroyObjects) (groundActor as AiCart).Destroy();
                    else Calcs.KillActor(gpBattle, this, groundActor, waitTime: 2);
                    Console.WriteLine("REMOVEOBJECTIVE: Removing GA " + groundActor.Type().ToString() + " from " + mo.Name + " at ({0:F0}{1:f0})", rpos.x, rpos.y);
                }
                if (groundStationary != null)
                {


                    //groundStationary.Destroy();
                    if (destroyObjects) groundStationary.Destroy();
                    else Calcs.KillStationary(gpBattle, this, groundStationary, waitTime: 2);
                    Console.WriteLine("REMOVEOBJECTIVE: Removing GS {0} {1} {2} from " + mo.Name + " at ({3:F0}{4:f0})", groundStationary.Type.ToString(), groundStationary.Name, groundStationary.Title, rpos.x, rpos.y);
                }
            }
            else
            {
                Timeout(random.Next(delay1, delay2), () =>
                {
                    if (movebombtargetmission.getPlainDistanceToNearestLivePilot(mo.Pos, armyToMatch: 0) > 10000)
                    {
                        if (groundActor != null)
                        {
                            //groundActor.Destroy();
                            if (destroyObjects) (groundActor as AiCart).Destroy();
                            else Calcs.KillActor(gpBattle, this, groundActor, waitTime: 2);
                            Console.WriteLine("REMOVEOBJECTIVE: Removing GA " + groundActor.Type().ToString() + " from " + mo.Name + " at ({0:F0}{1:f0})", rpos.x, rpos.y);
                        }
                        if (groundStationary != null)
                        {
                            //groundStationary.Destroy();
                            if (destroyObjects) groundStationary.Destroy();
                            else Calcs.KillStationary(gpBattle, this, groundStationary, waitTime: 2);
                            Console.WriteLine("REMOVEOBJECTIVE: Removing GS {0} {1} {2} from " + mo.Name + " at ({3:F0}{4:f0})", groundStationary.Type.ToString(), groundStationary.Name, groundStationary.Title, rpos.x, rpos.y);
                        }
                    }
                    else Timeout(random.Next(delay1, delay2), () =>
                    {
                        if (groundActor != null)
                        {
                            //groundActor.Destroy();
                            if (destroyObjects) (groundActor as AiCart).Destroy();
                            else Calcs.KillActor(gpBattle, this, groundActor, waitTime: 2);
                            Console.WriteLine("REMOVEOBJECTIVE: Removing GA " + groundActor.Type().ToString() + " from " + mo.Name + " at ({0:F0}{1:f0})", rpos.x, rpos.y);
                        }
                        if (groundStationary != null)
                        {
                            //groundStationary.Destroy();
                            if (destroyObjects) groundStationary.Destroy();
                            else Calcs.KillStationary(gpBattle, this, groundStationary, waitTime: 2);
                            Console.WriteLine("REMOVEOBJECTIVE: Removing GS {0} {1} {2} from " + mo.Name + " at ({3:F0}{4:f0})", groundStationary.Type.ToString(), groundStationary.Name, groundStationary.Title, rpos.x, rpos.y);
                        }
                    });
                }); //COULD check to make sure they are the same type we placed, here.
                    //Timeout makes the group disappear gradually over time but ALSO avoids the issue with deleting items in the list while looping it
            }
            return sectFile;
        }
        catch (Exception ex) { Console.WriteLine("MO_HandleGroundThingRemoval ERROR: " + ex.ToString()); return sectFile; }
    }

    //ships & submarines, BUT only applies to MOBILE OBJECTIVE types
    public bool MO_MobileObjectiveIsShipOrSubmarineObjective(MissionObjective mo)
    {
        bool shipObjective = false;
        if (mo.MOMobileObjectiveType == MO_MobileObjectiveType.TankerShipGroup_DE ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.TankerShipGroup_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.LargeTankerShipGroup_DE ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.LargeTankerShipGroup_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.FreighterShipGroup_DE ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.FreighterShipGroup_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.SmallShipGroup_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.SmallShipGroup_DE ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneShipGroup_DE ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneShipGroup_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneMTBGroup_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneMTBGroup_DE ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneSubmarineGroup_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneSubmarineGroup_DE ||
		   mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneSubmarineGroupVeryHard_GB ||
           mo.MOMobileObjectiveType == MO_MobileObjectiveType.OneSubmarineGroupVeryHard_DE
           )
            shipObjective = true;
        return shipObjective;
    }

    //ANY ship, submarine, other anyting else floating on the water or under it, and works for ALL objective types
    public bool MO_ObjectiveIsNavalVessel(MissionObjective mo)
    {
        if (mo.MOObjectiveType == null) return false;
        if (MO_Naval_Vessel_ObjectiveTypes.Contains(mo.MOObjectiveType)) return true;
        return false;
    }

    public ISectionFile MO_HandleTriggerObjectiveRefresh(MissionObjective mo, ISectionFile f = null, bool loadIndividually = false)
    {
        try
        {

            if (mo.MOTriggerType != MO_TriggerType.Trigger) return f;
            if (mo.Destroyed || !mo.IsEnabled) return f;


            if (GamePlay.gpLandType(mo.Pos.x, mo.Pos.y) == maddox.game.LandTypes.WATER) return f;

            double rad = mo.TriggerDestroyRadius;
            if (rad < 10) rad = 10;

            int count = 0;

            List<GroundStationary> gs = new List<GroundStationary>(GamePlay.gpGroundStationarys(mo.Pos.x, mo.Pos.y, rad).ToList());
            int foundCount = 0;
            if (gs != null) foundCount = gs.Count;

        if (mo.TotalInitialObjects_num == 0 ) mo.TotalInitialObjects_num = 25;

            if (foundCount >= mo.TotalInitialObjects_num)
            {

                Console.WriteLine("MO_HandleTriggerObjectiveRefresh: Refreshing objective {0}; found {2} and added {1} statics to the objective area", mo.ID, count, foundCount);
                return f;
            }

            int num_needed = Convert.ToInt32(mo.TotalInitialObjects_num - foundCount);
            int x_count = Convert.ToInt32(Math.Sqrt((double)num_needed));
            if (x_count < 2) x_count = 2;
            int y_count = num_needed / x_count + 1;
            if (y_count < 2) y_count = 2;

            double stretchA = 1;

            if (loadIndividually) f = GamePlay.gpCreateSectionFile();
            double sqr_len = Math.Sqrt(2) * rad;
            double xStart = mo.Pos.x - sqr_len;
            double yStart = mo.Pos.y - sqr_len;
            double xStep = 2 * sqr_len / (x_count - 1);
            double yStep = 2 * sqr_len / (y_count - 1);

            for (double x = xStart; x <= mo.Pos.x + sqr_len + 0.001; x += xStep)
            {
                for (double y = yStart; y <= mo.Pos.y + sqr_len + 0.001; y += yStep)

                {
                    string sname = "Stationary.Environment.JerryCan_GER1_1";
                    if (random.Next(0, 4) == 0) sname = "Stationary.Environment.TelegaBallon_UK1";
                    string armyside = "gb";
                    if (mo.OwnerArmy == 2) armyside = "de";
                    string side = "nn";
                    if (random.Next(0, 9) == 0) side = armyside;
                    f = Calcs.makeStatic(f, GamePlay, this, x, y, 0, sname, 0, side, staticprefix: "trigger_refresh_" + mo.IDtoCleanChiefName() + "_");

                    count++;
                    if (count > num_needed) break;

                }
                if (count > num_needed) break;
            }



            Console.WriteLine("MO_HandleTriggerObjectiveRefresh: Refreshing objective {0}; found {2} and added {1} statics to the objective area", mo.ID, count, foundCount);

            if (loadIndividually)
            {
                double to = 30 + random.Next(1, 800);
                if (ON_TESTSERVER) to = 5;
                Timeout(to, () => //no rush here, better to wait a bit
                {

                    if (ON_TESTSERVER) Console.WriteLine("PostmissionLoad: TriggerObjectiveRefresh");
                    GamePlay.gpPostMissionLoad(f);

                    if (!panic()) f.save(CLOD_PATH + FILE_PATH + "/sectionfiles" + "/trigger_objective_refresh_" + Calcs.GetSafeFileName(mo.ID)); //testing)

                });
            }
            return f;
        }
        catch (Exception ex) { Console.WriteLine("MO_HandleTriggerObjectiveRefresh ERROR: " + ex.ToString()); return f; }
    }

    public int num_Capital_Ships_in_Server = 0;
    //Designed so that you can send every objective to this routine at the start of the session and several times throughout, and it will
    //just return on any non-mobile objectives, and do nothing if the objective doesn't need to be changed/updated
    //On startup it will draw all objectives in place, even if it is not their time to change location.
    //reestablishObjective = true is used in case all Chiefs/Actors of an objective have been killed & we
    //need to refresh it mid-session
    public void MO_HandleMobileObjectivePlacement(MissionObjective mo, bool startup = false, bool reestablishObjective = false)
    {
        if (mo == null || mo.MOMobileObjectiveType == null || mo.MOMobileObjectiveType == MO_MobileObjectiveType.None) return;

        bool mobileShipObjective = MO_MobileObjectiveIsShipOrSubmarineObjective(mo);

        if (mobileShipObjective && !startup && !reestablishObjective) return; //only move ships at start of mission due to, they DRIFT and then don't get removed 100%. 2021-11.

        DateTime currTime = DateTime.UtcNow;

        if (!mo.IsEnabled) {

            if (mo.MobileNextMoveTime_dt.HasValue && !startup) MO_RemoveObjective(mo); //if disabled and placed (ie, has value), just remove it
            mo.MobileNextMoveTime_dt = null;
            //if (startup) MO_PlaceDetritusInObjectArea(mo); //if startup & !enabled, then just place the detritus.  Ok, we're doing this for ALL disabled objectives now, not just the mobile ones.  So skip it here.
            return;
        }

        if (!startup && !reestablishObjective && mo.MobileNextMoveTime_dt.HasValue && mo.MobileNextMoveTime_dt.Value.CompareTo(currTime) > 0) return; //only update them at start of session OR if their nextmovetime is null OR in the past

        if (GamePlay == null)
        {
            Console.Write("");
            Console.Write("MO_HandleMobileObjectivePlacement: MAJOR ERROR *************************************************** ");
            Console.Write("MO_HandleMobileObjectivePlacement: MAJOR ERROR GamePlay not initialized, nothing done.  Exiting routine. " + mo.Name);
            Console.Write("MO_HandleMobileObjectivePlacement: MAJOR ERROR *************************************************** ");
            Console.Write("");
            Console.Write("");
            return;
        }

        Console.WriteLine("MobileObjective: Handling placement of mobile objective ({0}) startup: {1} reestablishObjective: {2}" + mo.Name, ArmiesL[mo.OwnerArmy], startup, reestablishObjective);

        if (!startup && mo.MobileNextMoveTime_dt.HasValue && mo.MobileNextMoveTime_dt.Value.CompareTo(currTime) <= 0) {
            Console.WriteLine("MobileObjective: It's time to move " + mo.ID + " " + mo.Name);
            MO_RemoveObjective(mo);

        }

        Point3d newPos = mo.Pos; //this will be the randomly selected point for the objective IF that has previously been selected

        if (!mo.MobileNextMoveTime_dt.HasValue || (mo.MobileNextMoveTime_dt.HasValue && mo.MobileNextMoveTime_dt.Value.CompareTo(currTime) <= 0)) //if move time is null OR it exists & is in the past, then reset it now AND select the new location now
        {
            Console.WriteLine("Picking a new location for mobile objective ({2}) {0:F0} {1:F0} " + mo.Name, newPos.x, newPos.y, ArmiesL[mo.OwnerArmy]);
            mo.MobileNextMoveTime_dt = currTime.AddHours(mo.MobileMoveTime_hrs);


            //OK, select the new location

            //it is a rectangle defined by sw corner & ne corner
            Point3d swPos = mo.MobileSWPoint;
            Point3d nePos = mo.MobileNEPoint;


            double searchRadius_m = MO_CalcMobileObjRadius_m(mo);


            //try to find a place that is not water, not near an airport, outwards at least mo.radius + adder_m from the center of the objective, within min/max move distance specified
            //try it a bunch of times if no success
            int maxSearchNum = 5000;
            for (int i = 0; i < maxSearchNum; i++)
            {

                /*//if having trouble finding a place, expand the search area . . . 
                if (i > 50) {
                    double adder = i * 27;
                    swPos.x -= adder;
                    swPos.y -= adder;
                    nePos.x += adder;
                    nePos.y += adder;
                }
                */

                bool withinMinMax = false;
                Point3d mopos = mo.Pos;

                if (mopos.x < swPos.x) mopos.x = swPos.x;
                if (mopos.y < swPos.y) mopos.y = swPos.y;
                if (mopos.x > nePos.x) mopos.x = nePos.x;
                if (mopos.y > nePos.y) mopos.y = nePos.y;

                if (i< maxSearchNum/10) //we search this many times within the minx/max distance
                {
                    newPos.x = mopos.x + (random.NextDouble() * (mo.MobileMaxMoveDist_km - mo.MobileMinMoveDist_km) + mo.MobileMinMoveDist_km) * 1000 * (random.Next(2) * 2 - 1);
                    newPos.y = mopos.y + (random.NextDouble() * (mo.MobileMaxMoveDist_km - mo.MobileMinMoveDist_km) + mo.MobileMinMoveDist_km) * 1000 * (random.Next(2) * 2 - 1);

                    Console.WriteLine("MoBileObj: Find Pos {0:F2} {1:F2}", newPos.x, newPos.y);

                    if (newPos.x < swPos.x) newPos.x = swPos.x;
                    if (newPos.y < swPos.y) newPos.y = swPos.y;
                    if (newPos.x > nePos.x) newPos.x = nePos.x;
                    if (newPos.y > nePos.y) newPos.y = nePos.y;


                    withinMinMax = true;

                }
                else if (i < maxSearchNum / 5) //we search this many times within 3X the minx/max distance
                {
                    newPos.x = mopos.x + (random.NextDouble() * 3*mo.MobileMaxMoveDist_km + mo.MobileMaxMoveDist_km) * 1000 * (random.Next(2) * 2 - 1);
                    newPos.y = mopos.y + (random.NextDouble() *3 * mo.MobileMaxMoveDist_km + mo.MobileMaxMoveDist_km) * 1000 * (random.Next(2) * 2 - 1);

                    //Console.WriteLine("MoBileObj: Find Pos 3X {0:F2} {1:F2}", newPos.x, newPos.y);
                    if (newPos.x < swPos.x) newPos.x = swPos.x;
                    if (newPos.y < swPos.y) newPos.y = swPos.y;
                    if (newPos.x > nePos.x) newPos.x = nePos.x;
                    if (newPos.y > nePos.y) newPos.y = nePos.y;

                    withinMinMax = true;

                }
                else
                {
                    newPos.x = swPos.x + random.NextDouble() * (nePos.x - swPos.x);
                    newPos.y = swPos.y + random.NextDouble() * (nePos.y - swPos.y);

                }

                //bool withinMinMax = false;
                double distFromOldPos_m = Calcs.CalculatePointDistance(newPos, mopos);
                //Console.WriteLine("Trying location {0:F0} {1:F0} for " + mo.Name, newPos.x, newPos.y);


                int terr = GamePlay.gpFrontArmy(newPos.x, newPos.y);
                bool onEnemyTerritory = (mo.AttackingArmy == terr); //We can place these on friend OR neutral territory but not enemy.  Unless there is NO other choice.  Or, it's a ship - they can go anywhere.
				//Or if the entire region is on enemy territory, the OBJ will just switch sides.

                if (mobileShipObjective) onEnemyTerritory = false; //ships can be on enemy territory no prob.

                if (i % 500 == 0) Console.WriteLine("Battle begins! \nMOBILE OBJECTIVE PLACEMENT1 trial #{7} - {0} terr: {1} attacking: {2} Owner: {3} Pos: {4:n0} {5:n0}  OnEnemyTerr: {6}", new object[] { mo.Name, terr, mo.AttackingArmy, mo.OwnerArmy, newPos.x, newPos.y, onEnemyTerritory, i});


                if (onEnemyTerritory && i < 9 * maxSearchNum / 10) continue;

                //so most objectives don't want any WATER within their boundary but ship/tanker/cargo type 
                //objectives must have all water and NO LAND within their boundary.
                bool wrongLandOrWaterinObjectiveArea = false;

                //2021-11 ships have to be placed at least 10km from land.  Otherwise, artillery from land will 
                //attack them & vice-versa
                //2022-01 - this is not so mucha concern now that ships stay (mostly) in their own
                //front lines
                double sr = searchRadius_m + 5000;
                if (i > maxSearchNum / 5.0) sr = searchRadius_m + 2000;
                if (i > 2 * maxSearchNum / 5.0) sr = searchRadius_m + 1000;
                if (i > 3 * maxSearchNum / 5.0) sr = searchRadius_m + 500;
                if (i > 4 * maxSearchNum / 5.0) sr = searchRadius_m + 100;

                if (mobileShipObjective)
                    wrongLandOrWaterinObjectiveArea = MO_LandInRadius(newPos, sr);
                else wrongLandOrWaterinObjectiveArea = MO_WaterInRadius(newPos, searchRadius_m);

                if (i % 500 == 0) Console.WriteLine("Battle begins! \nMOBILE OBJECTIVE PLACEMENT2 trial #{7} - {0} terr: {1} attacking: {2} Owner: {3} Pos: {4:n0} {5:n0} OldPos: {9:n0} {10:n0} OnEnemyTerr: {6} flags: wrong land/water - {8}  ", new object[] { mo.Name, terr, mo.AttackingArmy, mo.OwnerArmy, newPos.x, newPos.y, onEnemyTerritory, i, wrongLandOrWaterinObjectiveArea, mopos.x, mopos.y });


                if (wrongLandOrWaterinObjectiveArea && onEnemyTerritory && i < 19 * maxSearchNum / 20) continue;

                //move by a certain min & max amount
                //if (distFromOldPos_m <= mo.MobileMaxMoveDist_km * 1000 && distFromOldPos_m >= mo.MobileMinMoveDist_km * 1000) withinMinMax = true;

                //if (!withinMinMax && i < maxSearchNum / 3.0) continue; //no need to fool around with airport & objective dist if we're not within min/max


                double dist = 5000;
                bool farEnoughFromAirport = true;

                if (i < 2.0 * maxSearchNum / 3.0)
                {
                    try
                    {
                        AiAirport ap = Calcs.nearestAirport(GamePlay, newPos);
                        dist = Calcs.CalculatePointDistance(ap.Pos(), newPos);
                    }
                    catch (Exception ex) { Console.WriteLine("ERROR MOBILE OBJECTIVE PLACEMENT! " + ex.ToString()); }

                    if (dist - searchRadius_m < 3500) farEnoughFromAirport = false;
                }

                bool tooNearAnotherObjective = false;

                if (i < 2.0 * maxSearchNum / 3.0) tooNearAnotherObjective = MO_oneObjectiveTooNearAnother(mo, newPos);

                ////!!!!!! TODO !!!!!!! Also check that this isn't close to any other existing mobile objective




                if (i % 500 == 0) Console.WriteLine("Battle begins! \nMOBILE OBJECTIVE PLACEMENT3 trial #{7} - {0} terr: {1} attacking: {2} Owner: {3} Pos: {4:n0} {5:n0} OldPos: {12:n0} {13:n0} OnEnemyTerr: {6} flags: wrong land/water {8} farenoughfromairport {9} withinminmax {10} too near another  {11}", new object[] { mo.Name, terr, mo.AttackingArmy, mo.OwnerArmy, newPos.x, newPos.y, onEnemyTerritory, i, wrongLandOrWaterinObjectiveArea, farEnoughFromAirport, withinMinMax, tooNearAnotherObjective, mopos.x, mopos.y });

                //if (!wrongLandOrWaterinObjectiveArea && farEnoughFromAirport && withinMinMax && !tooNearAnotherObjective) Console.WriteLine("MOBILE OBJECTIVE PLACEMENT - {0} terr: {1} attacking: {2} Owner: {3} Pos: {4} {5} OnEnemyTerr: {6}",new object[] { mo.Name, terr, mo.AttackingArmy, mo.OwnerArmy, newPos.x, newPos.y, onEnemyTerritory});

                if (!wrongLandOrWaterinObjectiveArea && farEnoughFromAirport && !onEnemyTerritory && withinMinMax && !tooNearAnotherObjective) break;
				
				if (!wrongLandOrWaterinObjectiveArea && farEnoughFromAirport && !tooNearAnotherObjective && onEnemyTerritory && i >= maxSearchNum / 5.0 ) {
					Console.WriteLine("MOBILE OBJECTIVE PLACEMENT - PROBLEM!  Found a good position but within enemy territory.  So switching sides.");
					mo.OwnerArmy = 3 - mo.OwnerArmy;
					mo.AttackingArmy = 3 - mo.OwnerArmy;
					mo.Scouted = false;
					
					break;
				}

                if (!wrongLandOrWaterinObjectiveArea && farEnoughFromAirport && !onEnemyTerritory && !tooNearAnotherObjective && i >= maxSearchNum / 3.0)
                {
                    Console.WriteLine("MOBILE OBJECTIVE PLACEMENT - PROBLEM!  Couldn't find a location within min/max movement parameters.  Just picking another location meeting ALL other criteria except it is a big jump. {0} min search, {1} searched, distance from old position: {2:n1}km.", maxSearchNum / 3.0, i, distFromOldPos_m / 1000);
                    break; //if not working we'll relax the requirement for moving by a certain amount
                }

                if (!wrongLandOrWaterinObjectiveArea && !onEnemyTerritory && i >= 2.0 * maxSearchNum / 3.0) // if still not working we'll relax the requirement to avoid airport
                {
                    Console.WriteLine("MOBILE OBJECTIVE PLACEMENT - PROBLEM!  Couldn't find a location within min/max movement parameters && outside of airport radius && any other objective radius.  Just picking another location meeting all criteria except Big Jump & Close to Airport OR objective. {0} min search, {1} searched.", 2.0 * maxSearchNum / 3.0, i);
                    break; //if not working we'll relax the requirement for moving by a certain amount
                }
                if (!onEnemyTerritory && i >= 5.0 * maxSearchNum / 6.0) // if still not working we'll relax the requirement to avoid airport
                {
                    Console.WriteLine("MOBILE OBJECTIVE PLACEMENT - PROBLEM!  Couldn't find a location within min/max movement parameters && not on water && outside of airport radius && not too close to another objective.  Just picking another location outside of Enemy Territory. {0} min search, {1} searched.", 5.0 * maxSearchNum / 6.0, i);
                    break; //if not working we'll relax the requirement for moving by a certain amount
                }
                if (i >= maxSearchNum - 1)
                {
                    Console.WriteLine("MOBILE OBJECTIVE PLACEMENT - BIG PROBLEM!  Couldn't find a location not too near an airport && another objective, or on water/land (as required) or on enemy territory, and right movement distance. Placing near center of area as last resort.");
                    newPos.x = (swPos.x + nePos.x) / 2.0 + random.NextDouble() * 10000 - 5000;
                    newPos.y = (swPos.y + nePos.y) / 2.0 + random.NextDouble() * 10000 - 5000;
                }
            }
        }


        var things = mo_mobileobjectivethings[mo.MOMobileObjectiveType];

        double masterHeading = random.Next(360);

        newPos.z = twcLandscape.HQ(newPos.x, newPos.y); //saving altitude/elevation of the objective.
        if (mo.AttackingArmy == 1) newPos.z = Calcs.meters2feet(newPos.z); //(in feet for Red army)
        mo.Pos = newPos;
        mo.ChiefName = mo.ID.Replace(' ', '_').Replace('.','_').Replace('\\','_'); //trying out using the ID as static name ...


        mo.Sector = Calcs.correctedSectorNameDoubleKeypad(this, newPos);
        mo.bigSector = Calcs.makeBigSector(this, newPos, mo.Points);

        int stretchType = 1;
        double stretchPercent = random.NextDouble() * 0.3;

        shapeType perimeterShape = Calcs.chooseRandomElement(perimeterShapes);

        //Now actually PLACE mobile objective.
        ISectionFile f = GamePlay.gpCreateSectionFile();
        bool resetCount = true;

        foreach (MO_MobileObjectiveThings t in things.Keys)
        {
            MO_ThingsTypeNumberRadius mttnr = new MO_ThingsTypeNumberRadius(things[t], masterHeading);

            //for testing, on test server
            double probability_add = 0;
            if (ON_TESTSERVER && MO_All_VeryDangerous_Military_Navy_Ships.Contains(t) && num_Capital_Ships_in_Server < 1)
            {
                probability_add = 0.035; //should be enough to get a capital/navy ship in each session , on the test server, most of the time
            }

            if (mttnr.probability < 1)
            {
                if (random.NextDouble() > mttnr.probability + probability_add)
                {
                    Console.WriteLine("Mobile objective {2}: Skipping {0} because of probability setting = {1}", t, mttnr.probability, mo.Name);
                    continue;
                }
            }

            if (mttnr.probability < 0.01 && (MO_All_VeryDangerous_Military_Navy_Ships.Contains(t)))
            {
                if (num_Capital_Ships_in_Server >= 1) continue;  //only let in one of these at a time
                Console.WriteLine("Mobile objective {2}!!!!!! Massively increasing objective score because Military Ship included! Ship type = {0} Probability setting = {1} - Level 200 AND 25 points/objects required to kill it", t, mttnr.probability, mo.Name);
                mo.Points = 1000; //in case where the military ship is included but only rarely, when it IS included the points for the obj are massively bigger  for that session.
                if (t == MO_MobileObjectiveThings.MO_Military_Ships_VeryLarge_DE || t == MO_MobileObjectiveThings.MO_Military_Ships_VeryLarge_GB) mo.Points = 1300;
                else if (t == MO_MobileObjectiveThings.MO_Military_Ships_Large_DE || t == MO_MobileObjectiveThings.MO_Military_Ships_Large_GB) mo.Points = 1100;
                else if (t == MO_MobileObjectiveThings.MO_Military_Ships_Medium_DE || t == MO_MobileObjectiveThings.MO_Military_Ships_Medium_GB) mo.Points = 800;
                mo.ObjectsRequiredToTrigger_num = 25; //ShipBattleship, ShipCruiser, SmallWarship etc etc are all worth at least 25 pts killed.  Plus there  will be some other ships around at 5-10-ish points
                mo.ActorsRequiredToTrigger_num = 3; //This is tricky bec. we want them to destroy the BATTLESHIP but actor wise that is the same points as the dinky small barge. 
                //But this becomes a failsafe incase the ships DRIFT out of the RADIUS, which even though it is LARGER is still not completely FAILSAFE. 
                //make the radius BIG in this exact case so that the ships SHOULDN'T drift out of it.
                //SHOULDN'T that is.
                mo.radius = 7500;
                mo.TriggerDestroyRadius = 7500;
                num_Capital_Ships_in_Server++;
            }

            double subHeading = masterHeading + random.Next(40) - 20;

            shapeType shp = mttnr.shape;

            if (t == MO_MobileObjectiveThings.Sandbags || t == MO_MobileObjectiveThings.Trenches || t == MO_MobileObjectiveThings.Hedgehogs)
            {
                subHeading = -2; //meaning, align them with the circle rather than the prevailing angle
                shp = perimeterShape;
            }


            if (t == MO_MobileObjectiveThings.Humans) newPos.z = 1;
            else newPos.z = 0;

            //Console.WriteLine("Cirles: " + t.ToString() + " " + subHeading.ToString());
            string addString = "";
            if (mobileShipObjective) addString = "/sleep 2/skill 1/slowfire 50";
            //shiptesting 2022/12
            //if (mobileShipObjective) addString = "/sleep 2/skill 1/slowfire 1";
            //trying skill 1 instead of skill - to see if that keeps the barges etc alive a bit better?
            //for military ships this really needs to be /slowfire 100 - we'll add that later for the
            //few military ships we're actually using now.


            if (t == MO_MobileObjectiveThings.MO_Military_Cargo_Tanker_Ships_Small_GB)
            {
                //This ensures motorbarge_Large1 has the red skin for GB ships
                //Should not do anything harmful to other ships
                addString += "/skin materialSummer1_red";
            }
            if (t == MO_MobileObjectiveThings.MO_Military_Cargo_Tanker_Ships_Small_DE)
            {
                //This ensures motorbarge_Large1 has the gray skin for DE ships
                //Should not do anything harmful to other ships
                addString += "/skin materialSummer2_gray";
            }




            bool randomizeHowmany = true; //this allows the draw things in circles routine to randomize the # even further
            int howmany = mttnr.howmany;

            if (mttnr.use_howmany_min) {
                randomizeHowmany = false;
                howmany = random.Next(mttnr.howmany_min, mttnr.howmany + 1);
                Console.WriteLine("MobileObjective: Using howmany_min - min {0} max {1} num chose: {2}", mttnr.howmany_min, mttnr.howmany, howmany);
            }
            else
            {

                howmany = Convert.ToInt32(mttnr.howmany + random.Next(Convert.ToInt32(mttnr.howmany / 4.0)) + mttnr.howmany / 2.0);
                if (t == MO_MobileObjectiveThings.MO_Military_Ships_DE || t == MO_MobileObjectiveThings.MO_Military_Ships_GB)
                {
                    randomizeHowmany = false; //We have to be careful in deploying these ships as they have many guns/aa and kill the server if not careful
                    howmany = mttnr.howmany;
                }
            }

            int percentSide = 28; //2022-12 - was 33%, now making it to 28% just to cut visibility of black dots a little.  2023-01, now 22%
            if (howmany > 14) percentSide = 14;
            if (howmany > 32) percentSide = 6;
            if (mobileShipObjective) percentSide = 100;


            f = PlaceObjectsInCircles(f, mttnr.things, newPos, mttnr.radius_m, mttnr.range_m, howmany, mo.OwnerArmy, subHeading_deg: subHeading, percentSide: percentSide, stretcherType: stretchType, stretcherAmt: stretchPercent * mttnr.radius_m, avoidWater: !mobileShipObjective, resetCount: resetCount, addString: addString, randomizeHowmany: randomizeHowmany, staticprefix: mo.ChiefName, shape: shp, orientationAngle_deg: masterHeading);
            //Console.WriteLine("mobile obj: {0} {1} ", mo.ID, resetCount);
            resetCount = false;

        }

        //Timeout(random.Next(47, 100), () => { GamePlay.gpPostMissionLoad(f); });
        if (ON_TESTSERVER) Console.WriteLine("PostmissionLoad: MobileObjectivePlacement");
        GamePlay.gpPostMissionLoad(f);


        f.save(CLOD_PATH + FILE_PATH + "/sectionfiles" + "/mobileobj_" + Calcs.GetSafeFileName(mo.ID)); //testing)

        Console.WriteLine("The mobile objective {0} ({3}) is at ({1:F0},{2:F0})", new object[] { mo.Name, mo.Pos.x, mo.Pos.y, ArmiesL[mo.OwnerArmy] });

    }

    double panicRating = 0;
    public bool panic() 
    {
        if (random.Next(100) < panicRating) return true;
        return false;
    }

    Dictionary<string, Point3d> MobileConvoyPositionList = new Dictionary<string, Point3d>();
    public double distanceToNearestMobileConvoy_m(Point3d pos)
    {
        try
        {
            double ret = 9999999999;
            if (MobileConvoyPositionList == null || MobileConvoyPositionList.Count == 0) return ret;
            foreach (Point3d mcPos in MobileConvoyPositionList.Values)
            {
                double dist = Calcs.CalculatePointDistance(pos, mcPos);
                if (dist < ret) ret = dist;
            }
            return ret;
        }
        catch (Exception ex)
        {
            Console.WriteLine("distanceToNearestMobileConvoy_m ERROR: " + ex.Message);
            return 9999999999.0;
        }
    }

    public void updateMobileConvoyPositionList()
    {
        try
        {
            MobileConvoyPositionList = new Dictionary<string, Point3d>();
            foreach (MissionObjective mo in MissionObjectivesList.Values)
            {
                if (!mo.isMoving()) continue; //we want the moving/mobile/CHIEF objectives, like shore patrol convoys
                if (MO_ObjectiveIsNavalVessel(mo)) continue; //but NOT naval objectives/ships/submarines
                if (!mo.IsEnabled || mo.Destroyed) continue;
                MobileConvoyPositionList[mo.ID] = mo.returnCurrentPosWithChief();

            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("updateMobileConvoyPositionList() ERROR: " + ex.Message);
            return;
        }
    }


    /*******************************************************************************
     * TEMPFLAK - flak that pops up where players are, then disappears when they leave
     * 
     * variables below determine how much tempflak, how long it lasts, when to distribute
     * With too many live players online you can't distribute TOO MUCH flak OR
     * load section files too often. So as more players, less flak and also slower load times
     * 
     * 
     * ******************************************************************************/
    public string tempFlakPrefix = "tflak";
	public string autoFlakPrefix = "aflak";
	
    public double tempFlak_Lifetime_s = 115; //was 125, but seems like they fired a while then sat for a long time, typically.  This was with 15 sec runs
    public int tempFlak_currentArmy = 1;
    //int tempflaktoAllocatePerRound = 80; //number to hand out each time tempFlakPlacement runs.
    //We were doing 80.  But due to error, 3/4 of them were lost.  And it still seemed adequate?
    //So trying maybe not 1/4 but say 1/3.
    int tempflaktoAllocatePerRound = 22; //number to hand out each time tempFlakPlacement runs. Was 28/2022-01-05
    int minTempflaktoAllocatePerRound = 14; //we don't have to cut the # of flak so much bec we cut the frequency loaded, # of files loaded, etc.  Was 16 2022-01-05
    double maxACAltitudeforTempflak = 2500;
    double minRatingForFlak = 25;
    int maxSectionFiles = 16;

    int numpToStartReducing = 8;
    int numpForMaxReduction = 16;
    int numpForCompleteElimination = 50;

    int testTempFlakNumPilots = 0;
    List<int> leftoverTempflak = new List<int>() { 0, 0, 0 }; //We keep track if any of the 80 is left over, if so the other army can use it in the next round
    public System.Threading.Timer tempFlakTimer;


    public void tempFlakTimer_recurs()
    {
        //Console.WriteLine("balanceAILoad: Starting timer! " + DateTime.UtcNow.ToString("T"));
        tempFlakTimer = new System.Threading.Timer(
            new TimerCallback(tempFlak),
            null,
            dueTime: 300000, //wait time @ startup
            period: 16342); //periodically call the callback at this interval, every 20 seconds say (it alternates armies, so 40 seconds for each army).  That puts up to 4*80 = 320*2 = 640 pieces in play FOR EACH ARMY.  Hmmmmm.... 
           //2023-02-01 - doubled frequency/halved period here BUT also halved everything else below
           //starting at 5 players online.

    }
    public void tempFlakTimer_dispose()
    {
        try
        {
            if (tempFlakTimer != null) tempFlakTimer.Dispose();
        } catch (Exception ex) { }
    }

    private int tempflakcounter = 0;
    private int tempflakcalledcounter = 0;
    private int[] sinceLastTempFlakCalledCount = { 1000, 1000, 1000 }; //keep track of how many runs since tempflak was last placed, for each army.  We start with a high # so it starts to work on 1st round. (helps testing.)

    public void tempFlak(object o)
    {
        try
        {
            if (panic()) return;
            if (threadloadmission.recentCPUPercent > 95 || threadloadmission.rollingAverageCPUPercent > 98) return; //prevents again both (adding to) a sudden surge of CPU but also if the long term CPU is getting high, preventively just stop adding more tempflak
            if (threadloadmission.rollingAverageCPUPercent > 93 && random.NextDouble() > 0.5) return; //start culling

            tempflakcalledcounter++;

            Thread thr = Thread.CurrentThread;
            thr.Priority = ThreadPriority.BelowNormal;

            int currentArmy = 1;
            if (tempFlak_currentArmy == 1) currentArmy = 2;
            tempFlak_currentArmy = currentArmy;
            sinceLastTempFlakCalledCount[tempFlak_currentArmy]++;

            int nump = Calcs.gpNumberOfPlayers(GamePlay);
            if (testTempFlakNumPilots > 0 && testTempFlakNumPilots > nump) nump = testTempFlakNumPilots;
            if (nump > 50) return;

            tempFlak_Lifetime_s = 95; //default/starting situation
            double sectionFileDelay_s = 2.42324;
            maxSectionFiles = 16; //2.5X16 = 40, each army section file is loaded in @ 40 seconds apart.

            if (nump > 16)
            {
                if (sinceLastTempFlakCalledCount[currentArmy] <= 12)
                {
                    if (ON_TESTSERVER) Console.WriteLine("TempFlak: Not long enough since last run for nump: {2} army: {0} cycles since last called: {1}", currentArmy, sinceLastTempFlakCalledCount[currentArmy], nump);
                    return; //place flak every 2:00 minutes only - meaning 4:00 mins per army wait
                }
                tempFlak_Lifetime_s = 1000; //but flak lifetime proportionate
                minRatingForFlak = 150;
                maxACAltitudeforTempflak = 1000;
                sectionFileDelay_s = 60;
                maxSectionFiles = 1;
            }
            else if (nump > 12)
            {
                if (sinceLastTempFlakCalledCount[currentArmy] <= 8)
                {
                    if (ON_TESTSERVER) Console.WriteLine("TempFlak: Not long enough since last run for nump: {2} army: {0} cycles since last called: {1}", currentArmy, sinceLastTempFlakCalledCount[currentArmy], nump);
                    return; //every 1:20 minutes only - meaning 2:40 mins per army wait
                }
                tempFlak_Lifetime_s = 500; //but flak lifetime proportionate
                minRatingForFlak = 125;
                maxACAltitudeforTempflak = 1000;
                sectionFileDelay_s = 40;
                maxSectionFiles = 2;
            }
            else if (nump > 9)
            {
                if (sinceLastTempFlakCalledCount[currentArmy] <= 6)
                {
                    if (ON_TESTSERVER) Console.WriteLine("TempFlak: Not long enough since last run for nump: {2} army: {0} cycles since last called: {1}", currentArmy, sinceLastTempFlakCalledCount[currentArmy], nump);
                    return;  //every 1:00 minute only - meaning 2:00 mins per army wait
                }
                tempFlak_Lifetime_s = 240; //but flak lifetime proportionate
                minRatingForFlak = 100;
                maxACAltitudeforTempflak = 1500;
                sectionFileDelay_s = 6.5;
            }
            else if (nump > 6)
            {
                if (sinceLastTempFlakCalledCount[currentArmy] <= 4)
                {
                    if (ON_TESTSERVER) Console.WriteLine("TempFlak: Not long enough since last run for nump: {2} army: {0} cycles since last called: {1}", currentArmy, sinceLastTempFlakCalledCount[currentArmy], nump);
                    return; //every 40 secs only - meaning 1:20 mins per army wait
                }
                tempFlak_Lifetime_s = 125; //but flak lifetime proportionate
                minRatingForFlak = 50;
                maxACAltitudeforTempflak = 2500;
                sectionFileDelay_s = 3.25;
            }
            else if (nump > 4)
            {
                if (sinceLastTempFlakCalledCount[currentArmy] <= 2)
                {
                    if (ON_TESTSERVER) Console.WriteLine("TempFlak: Not long enough since last run for nump: {2} army: {0} cycles since last called: {1}", currentArmy, sinceLastTempFlakCalledCount[currentArmy], nump);
                    return; //every 40 secs only - meaning 1:20 mins per army wait
                }
                tempFlak_Lifetime_s = 125; //but flak lifetime proportionate
                minRatingForFlak = 50;
                maxACAltitudeforTempflak = 2500;
                sectionFileDelay_s = 3.25;
            }
            //if num live players is > 16 we reduce the # of available flak down from
            //80 at 16 players linearly down to 20 when 90 players online.  Min is 20.
            //this should make the server more responsive when many breathers online
            int numToDistribute = tempflaktoAllocatePerRound;
            int minDistribution = minTempflaktoAllocatePerRound;
            int variableNumToDistribute = numToDistribute - minDistribution;
            if (variableNumToDistribute < 0) variableNumToDistribute = 0;


            if (nump > numpToStartReducing)
            {

                int numer = numpForMaxReduction - nump;
                if (numer < 0) numer = 0;
                // numToDistribute = (numToDistribute/4) + numToDistribute * 3 * numer /( (numpForMaxReduction - numpToStartReducing) * 4); //1/4 of numtodistribute is min & 3/4 is reduced, depending on what nump online

                numToDistribute = variableNumToDistribute * numer / ((numpForMaxReduction - numpToStartReducing)) + minDistribution;

                //if (numToDistribute == 0 && (numpForCompleteElimination - nump > random.Next(200))) numToDistribute = 4;

                if (numToDistribute <= 0) return;

            }

            if (ON_TESTSERVER) Console.WriteLine("TempFlak: Calling TempFlak for army: {0} numToDistribute: {1} nump: {2} minRatingforFlak: {3}, maxACAltitudefor flak {4}, section file delay {5}, maxSectionFiles: {6}", currentArmy, numToDistribute, nump, minRatingForFlak, maxACAltitudeforTempflak, sectionFileDelay_s, maxSectionFiles);

            int numDistributed = tempFlakPlacement(currentArmy, numToDistribute, nump, minRatingForFlak, maxACAltitudeforTempflak, sectionFileDelay_s, maxSectionFiles);
            if (numDistributed > 0) sinceLastTempFlakCalledCount[currentArmy] = 0;

            //update mobile ocnvoy position & associated autoflak positions occasionally; low priority
            tempflakcounter++;
            if (tempflakcounter % 60 == 0)
            {
                //Thread thr = Thread.CurrentThread;
                thr.Priority = ThreadPriority.Lowest;
                updateMobileConvoyPositionList();
                foreach (MissionObjective mo in MissionObjectivesList.Values.ToList())
                    MO_AutoFlak_selectLocations(mo, refresh: true);
                thr.Priority = ThreadPriority.BelowNormal;
            }
            
        
        } catch (Exception ex)
        {
            Console.WriteLine("tempFlak main ERROR: " + ex.Message);
        }
    }

    //tempflak only lives for 2 minutes or so
    public void handleTempflakSpawn(string shortname, AiActor actor) {
        try
        {
            if (!shortname.Contains(tempFlakPrefix)) return;
            Timeout(tempFlak_Lifetime_s, () =>
             {
                 if (actor != null) (actor as AiCart).Destroy();
             });
        }
        catch (Exception ex)
        {
            Console.WriteLine("handleTempflakSpawn ERROR: " + ex.ToString());
        }
    }

    public int tempFlakPlacement(int defendingArmy, int numToDistribute, int nump, double minRatingForFlak, double maxACAltitudeforTempflak, double sectionFileDelay_s = 3.5, double maxSectionFiles = 16)
    {
        int numDistributed = 0;

        try
        {

            if (ON_TESTSERVER) Console.WriteLine("Main: Starting tempFlakPlacement for defending army {0} ", defendingArmy);

            int attackingArmy = 3 - defendingArmy;
            int numAttackingPilots = 0;

            double max_altitude_m = maxACAltitudeforTempflak;  //above this altitude we'll skip the flak 100%.

            Dictionary<string, double> objRating = new Dictionary<string, double>();

            var aaAG = GamePlay.gpAirGroups(attackingArmy);

            if (aaAG != null && aaAG.Length > 0)
            {
                foreach (AiAirGroup airGroup in aaAG)
                {
                    if (airGroup != null && airGroup.GetItems() != null && airGroup.GetItems().Length > 0)
                    {
                        foreach (AiActor actor in airGroup.GetItems())
                        {
                            if (actor is AiAircraft)
                            {
                                AiAircraft aircraft = actor as AiAircraft;
                                if (aircraft != null)
                                {
                                    //For testserver, we'll defend against AI to see how the system works//testing

                                    double rating = 0;

                                    //if (!ON_TESTSERVER && (isAiControlledPlane(aircraft) || !aircraft.IsAirborne())) break; //for testserver we count AI planes the same as breathers, for testing purposes.  On the real server, this only spawns in AA for real/breather pilots
									if (isAiControlledPlane(aircraft) || !aircraft.IsAirborne()) break;
                                    if (actor.Pos().z < 10 || actor.Pos().z > max_altitude_m) continue; //skip very high alt ppl as flak doesn't help
                                    
                                    //getParameter seems like a lighter-weight way to get the AGL?
                                    //double pilotAGL_m = Calcs.AltitudeAGL_m(actor);
                                    double pilotAGL_m = aircraft.getParameter(part.ParameterTypes.Z_AltitudeAGL, 0);
                                    if (pilotAGL_m < 12) continue;
                                  
                                    numAttackingPilots++;
                                    //if (ON_TESTSERVER) Console.WriteLine("TempFlak: Checking pilot {0}", numAttackingPilots);
                                    foreach (MissionObjective mo in MissionObjectivesList.Values.ToList())
                                    {
                                        if(!mo.IsEnabled) continue;

                                        if (MO_ObjectiveIsNavalVessel(mo)) continue;
                                        if (mo.isMoving()) continue;

                                        double dist_m = Calcs.CalculatePointDistance(actor.Pos(), mo.Pos);
                                        if (dist_m > 10000) continue;//300mph for 2 mins=~16000m

                                        double timeSinceLastHit_s = 100000;
                                        if (mo.LastHitTime_UTC.HasValue) timeSinceLastHit_s = DateTime.UtcNow.Subtract(mo.LastHitTime_UTC.Value).TotalSeconds;

                                        //Pilots can evade AA by flying low.  BUT not if the 
                                        //MO has been hit very recently.  BUT even there, give
                                        //the pilot like 30-45 seconds reaction time for AA crews.
                                        if (timeSinceLastHit_s < 45 || timeSinceLastHit_s > 400) {
                                            if (mo.AttackingArmy == attackingArmy) {
                                                //if @ low level they can evade detection until
                                                //very close
                                                if (dist_m > 1000 &&
                                                    (pilotAGL_m < 35 ||
                                                    (pilotAGL_m < 80 && 80 - pilotAGL_m > random.Next(0, 45))
                                                    )) continue;
                                                //even if close, they still get reduced/slower response
                                                //if at low level
                                                else if (random.NextDouble() < 0.5 &&
                                                        ((pilotAGL_m < 35 ||
                                                    (pilotAGL_m < 80 && 80 - pilotAGL_m > random.Next(0, 45))
                                                    ))) continue;
                                            }

                                            double vel_mps = Calcs.CalculatePointDistance(airGroup.Vwld());
                                            if (vel_mps == 0) { continue; }
                                            else if (dist_m / vel_mps > 120) continue; //too far away for next 2 mins
                                            var ac_to_obj_vwld = new Vector3d(mo.Pos.x - actor.Pos().x, mo.Pos.y - actor.Pos().y, 0);
                                            double ac_to_obj_bearing_deg = Calcs.CalculateBearingDegree(ac_to_obj_vwld);
                                            double ac_current_heading_deg = Calcs.CalculateBearingDegree(airGroup.Vwld());
                                            double heading_different_deg = ac_to_obj_bearing_deg - ac_current_heading_deg;
                                            if (heading_different_deg > 90 && heading_different_deg < 270 && dist_m > 4000) continue; //not too close & heading away
                                            bool headed_towards = false;
                                            if (heading_different_deg > 300 || heading_different_deg < 60) headed_towards = true;
                                            double pass_distance_m = Math.Abs(Calcs.PointToLineDistance(new Point2d(actor.Pos().x, actor.Pos().y), new Point2d(actor.Pos().x + airGroup.Vwld().x, actor.Pos().y + airGroup.Vwld().y), mo.Pos));

                                            

                                            if (timeSinceLastHit_s < 120) rating += 300; //it's under current attack
                                            else if (timeSinceLastHit_s < 210) rating += 200; //it's under current attack

                                            if (dist_m < 1000) rating += 250;
                                            else if (dist_m < 2000) rating += 150;
                                            else rating += (16000 - dist_m) / 14000.0 * 150.0;

                                            if (headed_towards)
                                            {
                                                if (pass_distance_m < 100) rating += 150;
                                                if (pass_distance_m < 1000) rating += 50;
                                                if (pass_distance_m < 2500) rating += 25;
                                                if (pass_distance_m < 5000) rating += 10;
                                            }

                                            //They can sneak in at low alt.  OTOH, low but not
                                            //low enough to avoid being seen is EMERGENCY!!!11!!
                                            double agl_m = Calcs.AltitudeAGL_m(airGroup.Pos());
                                            if (agl_m < 90) rating = 0;
                                            else if (agl_m < 120) rating *= 0.6;
                                            else if (agl_m < 333) rating *= 4.0;
                                            else if (agl_m >= 333 && agl_m < max_altitude_m) rating *= (max_altitude_m - agl_m) / (max_altitude_m - 333) * 4.0;

                                            //Add a little plus if this is under double or triple etc attack
                                            if (objRating.ContainsKey(mo.ID))
                                            {
                                                double oR = objRating[mo.ID];
                                                if (oR >= rating) rating = oR + rating / 4.0;
                                                else rating = rating + oR / 4.0;
                                            }
                                            //Console.WriteLine("TempFlak: Checking pilot {0}, adding obj rating {1:n0} for {2} : {3}", numAttackingPilots, rating, mo.ID, aircraft.Type());
                                            //If it's partially destroyed this cuts AA responsiveness
                                            //but not completely
                                            //note a deduction for mo.Destroyed == true also, below.
                                            double reducPerc = 1.0;
                                            if (mo.DestroyedPercent > 0) reducPerc = 1 - mo.DestroyedPercent / 2.0;
                                            if (reducPerc < 0.01) reducPerc = 0.01;
                                            rating *= reducPerc;
                                        } else
                                        {//case where a friendly pilot is flying near their own OBJ

                                            if (dist_m > 4000) continue;
                                            if (pilotAGL_m > 3000) continue;
                                            rating += 10; //just a very low/baseline rating but it can be increased if there are enemies near etc.
                                        }
                                        if (objRating.ContainsKey(mo.ID)) {
                                            //Don't just add additional ratings but give a bit of a discount for 2nd, 3rd, etc
                                            if (objRating[mo.ID] > rating) objRating[mo.ID] += rating / 2;
                                            else objRating[mo.ID] = rating + objRating[mo.ID] / 2;
                                        }
                                        else objRating[mo.ID] = rating;
                                    }

                                }
                            }
                        }
                    }
                }
            }

            //Console.WriteLine("TempFlak: Adding bonuses...");

            //bonus for how many nearby bombers to obj
            //also adjust for if it is a primary or destroyed
            //var tempList = new List<string>();
            foreach (string ID in objRating.Keys.ToList())
            {
                MissionObjective mo = MissionObjectivesList[ID];
                double rating = objRating[ID];
                int neb = statsmission.countNearbyEnemyBombers(mo.Pos, defendingArmy, 5000, 0, 3500, 90);  //gets 'enemy' bombers, ie, we send it the defending army #
                                                                                                       //This also picksup AI bombers, so there will be  more flak if there is (at least) one breather bomber plus many AI OR breather bombers in the area.
                if (neb > 20) rating *= 4.0;
                else if (neb > 2) rating *= (neb - 2) / 18.0 * 3.0 + 1;

                if (mo.IsPrimaryTarget && !mo.ObjectiveAchievedForPoints) rating *= 3;
                if (mo.PrimaryTargetWeight < 100) rating *= 0.3;

                //Military objectives get more protection and non-military ones less
                if (MO_objectivetype_by_strengthtype[MO_MilitaryStrengthType.Military_Leadership].Contains(mo.MOObjectiveType) ||
                    MO_objectivetype_by_strengthtype[MO_MilitaryStrengthType.Military].Contains(mo.MOObjectiveType) ||
                    MO_objectivetype_by_strengthtype[MO_MilitaryStrengthType.Military_Fuel_Supply].Contains(mo.MOObjectiveType)
                    ) rating *= 1.3;
                else rating *= 0.4;

				//gets very weak if destroyed
				//and proportionally weaker if partially destroyed, 
				//sqrts mean most decrease comes 0-100%, a little more 100-200%
                if (mo.Destroyed) rating *= 0.1;
				else if (mo.DestroyedPercent> 0.05) {
					double desFact = Math.Sqrt(Math.Sqrt( (2.0-mo.DestroyedPercent).Clamp (0,2) / 2.0));
					rating *= desFact;
				}

                //Each 10 defenseunits adds ~ 100% to defense rating here, further 10s have diminishing returns however
                double defenseUnits_factor = mo.defenseUnitsHelpFactor();
                rating *= defenseUnits_factor;

                objRating[ID] = rating;
            }

            double totalRatings = 0;
            double totalRatingsOver10 = 0;
            double totalRatingsOver10_sqrt = 0; //sum of sqrt of all ratings>10, for sqrt mean purposes
            double totalRatingsOver100 = 0;
            double totalRatingsOver100_sqrt = 0; //sum of sqrt of all ratings>100, for sqrt mean purposes
            int totalObj = 0;
            int totalObjOver10 = 0;
            int totalObjOver100 = 0;

            //Console.WriteLine("TempFlak: Combining nearby objs");

            //reduce ratings for any objectives withing 1.2km of the higher-rated obj
            var newObjRating = new Dictionary<string, double>();
            foreach (KeyValuePair<string, double> item in objRating.OrderByDescending(key => key.Value))
            {
                MissionObjective mo = MissionObjectivesList[item.Key];
                double rating = item.Value;
                if (rating < minRatingForFlak)
                {
                    if (rating < minRatingForFlak)
                    {
                        if (nump < 5 || ON_TESTSERVER) Console.WriteLine("TempFlak Objective Eval - skipping bec rating<minRating ({2:n0}): {0} Rating: {1:n0} ", mo.ID, rating, minRatingForFlak);
                        continue;
                    }
                    continue;
                }
                foreach (string ID2 in newObjRating.Keys)
                {
                    MissionObjective mo2 = MissionObjectivesList[ID2];
                    double rating2 = newObjRating[ID2];

                    //we do the defense response from the rating here because:
                    // - it is rate limited by its own system per objective
                    // - it only applies to OBJs with Defense Units, so the winnowing we are doing at this step does not apply or work here

                    if (rating2 > 800) mo2.defenseUnitsAttackResponse();
                    
                    double objdist_m = Calcs.CalculatePointDistance(mo.Pos, mo2.Pos);
                    if (objdist_m < 1200 && rating2 > rating)
                    {
                        rating *= 0.1 * mo.defenseUnitsHelpFactor(); //this is normally 1 (no DUs) but ranges 2+ for those with DUs.  So MOs with DUs can be reduced a bit, but not as much in rating.
                        break;
                    }
                    else if (objdist_m < 2400 && rating2 > rating)
                    {
                        rating *= 0.2 * mo.defenseUnitsHelpFactor();
                        break;
                    }
                    else if (objdist_m < 3600 && rating2 > rating)
                    {
                        rating *= 0.3 * mo.defenseUnitsHelpFactor();
                        break;
                    }
                }
                newObjRating[item.Key] = rating;
                totalRatings += rating;
                totalObj++;
                if (rating >= 100) { totalRatingsOver100 += rating; totalRatingsOver100_sqrt += Math.Sqrt(rating); totalObjOver100++; }
                else if (rating >= 10) { totalRatingsOver10 += rating; totalRatingsOver10_sqrt += Math.Sqrt(rating); totalObjOver10++; }

            }

            double averageRatingOver100 = 500;
            if (totalObjOver100 > 0) averageRatingOver100 = totalRatingsOver100 / totalObjOver100;

            //int numToDistribute = tempflaktoAllocatePerRound + leftoverTempflak[ attackingArmy ]; //We can use anything left over from the last round of the opposite army...  helpful in cases where there are a BUNCH of players on for, say, Blue but none for Red.



            int maxNumFor100s = numToDistribute / 2;

            //Increase that max num if it looks like there is more of an emergency
            if (totalObjOver100 > 0 && maxNumFor100s / totalObjOver100 < 8) maxNumFor100s = numToDistribute * 3 / 4;
            if (totalObjOver100 > 0 && totalRatingsOver100 / totalObjOver100 > 500 && maxNumFor100s / totalObjOver100 < 10) maxNumFor100s = numToDistribute * 5 / 6;



            int numFor100s = 12 * totalObjOver100;
            if (numFor100s > numToDistribute / 2) numFor100s = maxNumFor100s;

            if (minRatingForFlak >= 100 || maxSectionFiles == 1) numFor100s = numToDistribute;

            int leftovers = maxNumFor100s - numFor100s;
            if (leftovers <= 0) leftovers = 0;

            int maxNumFor10s = numToDistribute * 5 / 8;
            int numFor10s = 4 * totalObjOver10;
            if (totalObjOver10 > 0)
            {
                if (numFor10s > maxNumFor10s) numFor10s = maxNumFor10s;
                numFor10s += leftovers * 4 / 5;
                if (numFor10s > 10 * totalObjOver10) numFor10s = 10 * totalObjOver10;
            }

            int totalObjOver1 = totalObj - totalObjOver10 - totalObjOver100;
            int numFor1s = 0;
            if (totalObjOver1 > 0)
            {
                numFor1s = (numToDistribute - numFor100s - numFor10s); //they get anything left over
            }



            Console.WriteLine("TempFlak: Calculated numAttacking Pilots, totalObj, totalObjOver1, totalObjOver10, totalObjOver100, numFor100s, numFor10s, numFor1s {0:n0} {1:n0} {2:n0} {3:n0} {4:n0} {5:n0} {6:n0} {7:n0} numtoDistribute: {10} leftovers: {8:n0} {9}", new object[] { numAttackingPilots, totalObj, totalObjOver1, totalObjOver10, totalObjOver100, numFor100s, numFor10s, numFor1s, leftovers, DateTime.UtcNow.ToString("[HH:mm:ss]"), numToDistribute });

            double delay = 1;


            int leftovers2 = 0;
            bool hundredsExceptionalRule = false;
            bool first = true;
            int totalInSectionFile = 0;
            int sectionFilesLoaded = 0;
            int loop_count = 0;
            bool reset_count = true;
            var autoFlakF = GamePlay.gpCreateSectionFile();

            foreach (KeyValuePair<string, double> item in newObjRating.OrderByDescending(key => key.Value))
            {
                loop_count++;
                MissionObjective mo = MissionObjectivesList[item.Key];
                double rating = item.Value;

                int num_aa_forobj = 10;

                if (rating >= 100)
                {
                    if (rating >= 1200) hundredsExceptionalRule = true;

                    if (!hundredsExceptionalRule && totalObjOver100 > 0) //just being safe to avoid /0
                    {
                        num_aa_forobj = numFor100s / totalObjOver100;

                        //This might SLIGHTLY Overexceed our given allotment of AAs but it shouldn't
                        //be by much if so
                        if (rating > averageRatingOver100 * 1.25) num_aa_forobj = num_aa_forobj * 13 / 10;
                        if (rating < averageRatingOver100 * 0.75) num_aa_forobj = num_aa_forobj * 8 / 10;
                    }
                    else if (hundredsExceptionalRule && totalRatingsOver100 > 0) num_aa_forobj = Convert.ToInt32(numFor100s * Math.Sqrt(rating) / totalRatingsOver100_sqrt);


                    //Limit the # somewhat, but still keep it pretty high for any high ratings
                    //Otherwise if there is one very highly rated objective in the server it 
                    //gets ALL the flak & nothing else gets any
                    if (rating < 1200 && num_aa_forobj > 10) { leftovers += num_aa_forobj - 10; num_aa_forobj = 10; }
                    else if (rating < 900 && num_aa_forobj > 8) { leftovers += num_aa_forobj - 8; num_aa_forobj = 8; }
                    else if (rating < 600 && num_aa_forobj > 5) { leftovers += num_aa_forobj - 5; num_aa_forobj = 5; }
                    else if (rating < 300 && num_aa_forobj > 4) { leftovers += num_aa_forobj - 4; num_aa_forobj = 4; }


                    //and for super-high ratings we are going to break the rules a bit
                    //but only for EXACTLY one objective
                    //Doing this for all or most objectives, say over 1000, BREAKS the SERVER
                    //we were putting in 160 or more AAs sometimes, instead of 80.
                    //But doing it for JUST ONE *should* be OK.
                    if (first && rating >= 1000 && num_aa_forobj < 8 && numToDistribute > 27) num_aa_forobj = 8;
                    else if (first && rating >= 700 && num_aa_forobj < 6 && numToDistribute > 22) num_aa_forobj = 6;
                    first = false;

                }
                else if (rating >= 10)
                {
                    //Distribute more of these to higher-scored objectives
                    if (totalRatingsOver10 == 0 && totalObjOver10 > 0) num_aa_forobj = numFor10s / totalObjOver10; //cya just in case totalObjOver10 is zero for some wierd reason
                    else if (totalRatingsOver10 > 0) num_aa_forobj = Convert.ToInt32(numFor10s * Math.Sqrt(rating) / totalRatingsOver10_sqrt); //What happens 99.9999999% of the time

                    if (num_aa_forobj > 9) { leftovers += num_aa_forobj - 9; num_aa_forobj = 9; }


                    if (numDistributed > numToDistribute)
                        if (rating > 40 && numDistributed - numToDistribute < 10 && numToDistribute > 30) num_aa_forobj = 1; //if we have run out, we will still give them a token # of 1 if it seems warranted & possible
                        else num_aa_forobj = 0; //we're out of AA, so we stop

                }
                else
                {
                    num_aa_forobj = (numFor1s + leftovers) / totalObjOver1;
                    if (num_aa_forobj < 1) num_aa_forobj = 1;
                    if (num_aa_forobj > 8) num_aa_forobj = 8;

                }


                numDistributed += num_aa_forobj;



                //batteries of 6-8-ish seem to work best while batteries of say 15 don't seem to work at all?
                int nib = 4; //num in battery //update 2023/01/06, 4 seems to be really sufficient
                int nfb = num_aa_forobj / nib; //num flak batteries
                if (num_aa_forobj % nib > 0) nfb++; //add an extra battery for the remainder, in case their are leftovers

                //this will give nfb batteries of nib guns, but the last battery will have the remainder/any leftovers.  So like 6,6,3 will make 15 guns.

                //split up loads into one battery at a time and then 2 seconds between loads
                //see if that helps with stuttering
                int count_aa_forobj = 0;

                count_aa_forobj += nib;

                if (nump < 5 || ON_TESTSERVER) Console.WriteLine("TempFlak Objective Eval: {0} Rating: {1:n0} Num: {2:n0} Batteries: {3} Numdistributed so far: {4}", mo.ID, rating, num_aa_forobj, nfb, numDistributed);
                totalInSectionFile += num_aa_forobj;


				//was Substring(1), not sure why. 2026/08
                autoFlakF = MO_AutoFlakPlacement(mo, autoFlakF, reset_count, tempFlak: true, nfb_temp: nfb, nib_temp: nib, total_flak_temp: num_aa_forobj, prefix_replace: tempFlakPrefix + "_" + mo.OwnerArmy.ToString() + "_" + mo.IDtoCleanChiefName().Substring(0) + "_");

                reset_count = false;


                if (totalInSectionFile >= 10 || numDistributed >= numToDistribute || loop_count >= newObjRating.Count())
                {
                    //Timeout(delay, () =>
                    {
                        GamePlay.gpPostMissionLoad(autoFlakF);
                        reset_count = true;
                        if (nump < 5 && !panic() || ON_TESTSERVER) autoFlakF.save(CLOD_PATH + FILE_PATH + "/sectionfiles/" + "tempflakfile-" + Calcs.GetSafeFileName(mo.ID) + ".mis"); //testing

                    }
                    //);

                    totalInSectionFile = 0;
                    autoFlakF = GamePlay.gpCreateSectionFile();
                    sectionFilesLoaded++;
                    if (sectionFilesLoaded >= maxSectionFiles)
                    {
                        if (ON_TESTSERVER) Console.WriteLine("TempFlak: Completed max section files allowed - Exiting. {0} Rating: {1:n0} Num: {2:n0} Batteries: {3} Numdistributed so far: {4}, sectionFilesLoaded: {5}, maxSectionFiles: {6}", mo.ID, rating, num_aa_forobj, nfb, numDistributed, sectionFilesLoaded, maxSectionFiles);
                        break;
                    }

                    Thread.Sleep(Convert.ToInt32(sectionFileDelay_s * 1000));//slow down the loads just a little bit by delaying between each load
                    delay += sectionFileDelay_s;
                }

                if (numDistributed > numToDistribute) break; //we're out of AA, so we stop

            }


            Console.WriteLine("TempFlak: Complete. Numdistributed: {0} over the past {1} seconds", numDistributed, delay);


            leftoverTempflak[defendingArmy] = 0;// tempflaktoAllocatePerRound - numDistributed;
            if (leftoverTempflak[defendingArmy] < 0) leftoverTempflak[defendingArmy] = 0;
            return numDistributed;
        }
        catch (Exception ex)
        {
            Console.WriteLine("tempflakSpawnPlacement ERROR: " + ex.ToString()); return numDistributed;
        }
    }


    int tempFlakTotal = 0;
    int autoFlakTotal = 0;
    int autoFlakChiefNum = 0;
    int autoFlakRun = 0;

    public ISectionFile MO_AutoFlakPlacement(MissionObjective mo, ISectionFile f = null, bool resetCount = false, bool tempFlak = false, int nfb_temp = 1, int nib_temp = 8, int total_flak_temp = 8, string prefix_replace = null)
    {
        try
        {
            //return; //testing
            List<string> keys = new List<string>(MissionObjectivesList.Keys);
            if (!mo.IsEnabled) return f;
            autoFlakRun++;
            //
            //Console.WriteLine("Handling autoFlakPlacement for {0} {1} {2} {3}", mo.ID, mo.Pos.x, mo.Pos.y, mo.OwnerArmy);
            Point3d newPos = mo.Pos;
            newPos.z = Math.Round(newPos.z);
			

            //Console.WriteLine("Auto/TempFlak Radiushide: {0:n0} Distenemy: {1:n0} Dist Neutral {2:n0}", radiusHide, distanceToEnemyFront, distanceToNeutralFront);

            int nfb = mo.NumFlakBatteries;
            int nib = mo.NumInFlakBattery;


            //TESTING!!!!
            //Below will apply to primary targets, others are overridden below
            nfb = 1;
            nib = 2;
            //2023-01, now setting ALL OBJ to 1x2, the rest is supplied via tempflak
            //2022-12, was 2x4, but with tempflak system reducing to 1x2.  That frees up about
            //24 flak guns for tempflak use (even with reduced primaries of the 2022 Jubilee campaign
            // - about 4x2 primaries only)
            //bhugh, temp, XX2021-10, for final rush increasing # of primaries so decreasing primary autoflak.  Was 2,2
            //2021-11 - primary # still 110 so just leaving it
            //2022-12 - very small # of primaries now, so can increase the flak some.  Went from 1,2 to 2,4.
            if (ON_TESTSERVER)
            {
                nfb = 0;
                nib = 0;
            }

            //2021-06 - WAS 2 X 5, MEANING 10 FLAK added for each primary obj.
            //Maybe this is too much, we had some occasions of long load times in server.
            //Trying 2X4 instead. Now 2x3.  Now 2x2 (8/2/2021).
            //TOBRUK is 2X2


            if (MO_ObjectiveIsNavalVessel(mo) || mo.MOObjectiveType == MO_ObjectiveType.Submarine) return f;
            if (mo.isMoving()) return f; //we don't provide flak for moving objectives - they will just move away from it anyway

            //too much flak seems to bring the server to it's knees, so if not a primary just 2x2 flak, otherwise what is requested
            if (!mo.IsEnabled || !mo.IsPrimaryTarget)
            {


                if (mo.MOObjectiveType == MO_ObjectiveType.Artillery_and_AA ){ //For AA objectives, this IS the objective, so make sure something is there
					nfb = 1;
                    nib = 4;                    

                    if (ON_TESTSERVER)
                    {
                        nfb = 1;
                        nib = 1;
                    }
				} else if (mo.MOObjectiveType == MO_ObjectiveType.Radar || mo.MOObjectiveType == MO_ObjectiveType.KnickebeinHQ) //radar needs more flak to protect it, so just half the req amount if not primary.
                {
                    /*nfb = nfb / 3;
                    nib = nib;
                    if (nfb < 2) nfb = 2;
                    if (nib < 2) nib = 2;
                    */
                    //Console.WriteLine("RADAR autoFlakPlacement  {0} {1} ", nfb, nib);
                    nfb = 1;
                    nib = 2;
                    //2022-12 = was 1x3, now reducing to 1x1 so we can use the remainder for tempflak
                    //bhugh, temp, XX2021-10, for final rush increasing # of primaries so decreasing primary autoflak.  Was 1,3 now 1,1
                    //abt 55 radars, so this frees up about 110 flak pieces.
                    //2021-11 leaving it
                    //2022-12 - trying 1,3 again now, we'll see.

                    if (ON_TESTSERVER)
                    {
                        nfb = 1;
                        nib = 1;
                    }


                }
                else //for everything else, just a little bit. 
                {
                    nfb = 1;
                    nib = 1;
                    //bhugh, temp, XX2021-10, for final rush increasing # of primaries so decreasing primary autoflak.  Was 1,2 now 1,1
                    //2021-11 leaving it

                    if (ON_TESTSERVER)
                    {
                        nfb = 0;
                        nib = 0;
                        if (random.NextDouble() > 0.98)
                        {
                            nfb = 1;
                            nib = 1;

                        }
                    }

                }
            }

            //Add a little autoflak in case of having any defense units
            if (!tempFlak)
            {
                //Basically add one unit per 10 defense units, but at least 1 if there are at least 10 DUs
                int nibAdd = 0;
                try
                {
                    double du = mo.numDefenseUnits();
                    if (ON_TESTSERVER) Console.Write("Autoflak: numdefenseunits {0:f6} nfb {1} ", du, nfb);
                    if (nfb == 0) nfb = 1;
                    double defenseUnits_add = du / (10.0 * nfb) + 0.1;
                    if (du >= 10 & defenseUnits_add < 1) defenseUnits_add = 1;
                    nib += Convert.ToInt32(Math.Round(defenseUnits_add));
                }
                catch (Exception ex) { Console.WriteLine("Autoflak INT32 conv ERROR: " + ex.ToString()); nibAdd = 0; }

                nib += nibAdd;
            }

            if (tempFlak)
            {
                nfb = nfb_temp;
                nib = nib_temp;
            }

            //ISectionFile  f = GamePlay.gpCreateSectionFile();
            if (f == null) f = GamePlay.gpCreateSectionFile();

            //$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
            //$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

            int flakType = 0;
            int totalFlakPlaced = 0;

            for (int j = 0; j < nfb; j++)
            {
                /*
                 *     if (nfb * nib < 2 && batteryRadius > 75) batteryRadius = 75; //experimental, if just a couple of flak try placing it right amid the actual target

                */
                Point3d? temp = mo.getNext_AutoFlak_location();
                if (!temp.HasValue) {
                    Console.WriteLine("AutoFlak: No AutoFlak location for {0} - exiting ({1})", mo.ID, mo.Name);
                    return GamePlay.gpCreateSectionFile();
                }

                newPos = temp.Value;

                //slightly randomize the position
                newPos.x += random.Next(12) - 6;
                newPos.y += random.Next(12) - 6;
				
				int terr = GamePlay.gpFrontArmy(newPos.x, newPos.y);
				double radiusHide = 6000;

				double distanceToEnemyFront = GamePlay.gpFrontDistance(mo.AttackingArmy, newPos.x, newPos.y);
				double distanceToNeutralFront = GamePlay.gpFrontDistance(0, newPos.x, newPos.y);


				if (distanceToEnemyFront < 8000 && distanceToEnemyFront > 1000) radiusHide = distanceToEnemyFront * 0.75;
				else if (distanceToEnemyFront <= 1000) radiusHide = radiusHide = distanceToEnemyFront * 0.6;
				if (radiusHide > 1000 && distanceToNeutralFront < 4000) {
					radiusHide = distanceToNeutralFront * 0.6; //we pretty much need to do this to avoid killing any enemy objectives in the neutral zone
				}
				if (terr == 0 && radiusHide > 250 ) radiusHide = 250; //It's neutral ground, perhaps there should be NO flak at all... 2026/08 - see below.
				
				if(ON_TESTSERVER) Console.WriteLine("Autoflak/tempflak placement: {0} {1:N0} {2:N0} {3:N0}", Calcs.correctedSectorNameDoubleKeypad(this,newPos), radiusHide, newPos.x, newPos.y  );


                string owner = "nn";
                if (mo.OwnerArmy == 1) owner = "gb";
                else if (mo.OwnerArmy == 2) owner = "de";
                else { 
					Console.WriteLine("Autoflak Placement ARMY ERROR for {0} objective - Owner Army was not 1 or 2", new object[] { mo.Name });					
				}
				
				if (owner == "nn" || terr == 0) {
					Console.WriteLine("Autoflak Placement - no army for OBJ OR flak location in NEUTRAL ZONE.  Not placing any flak here.", new object[] { mo.Name });					
					return GamePlay.gpCreateSectionFile();
				}

                //Bofors_StandAlone is very good.
                //37mm_PaK_35_36 doesn't seem to work at all?
                //.3_7_inch_QF_Mk_I might work OK, hit me.  Doesn't fire very often.
                //Artillery.Flak30_Shield is very good, maybe better than Bofors.  Fires often and accurately.

                //var flak = new List<string> { "Artillery.37mm_PaK_35_36", /*"Artillery.Flak37",*/
                //"Artillery.Bofors_StandAlone", "Artillery.3_7_inch_QF_Mk_I", "Artillery.Flak30_Shield", };
                //2023-01 - trying to go with like 90% Flak30 and 10% Bofors, to see if we can
                //make them more of a low-level oriented flak shield type thing,
                //rather than reaching up to 10-15000ft also.
                var flak = new List<string> { "Artillery.Flak30_Shield", "Artillery.Flak30_Shield",
                    "Artillery.Flak30_Shield",
                    "Artillery.Flak30_Shield","Artillery.Flak30_Shield","Artillery.Flak30_Shield",
                    "Artillery.Flak30_Shield","Artillery.Flak30_Shield","Artillery.Flak30_Shield",
                    "Artillery.Bofors_StandAlone", };

                //OK, the artillery chief is one of my prime suspects for the warping/rubberbanding.  Trying to disable them all to see if that helps.  2020/03/07
                //Next thing to try would be disabling all this autoflak.  It does seem to slow down/tie up the server noticeably.
                //Trying chiefs onliy for primary targets

                //if (mo.IsPrimaryTarget) //experimentally making Chiefs only for primary target artillery.

                string staticprefix = autoFlakPrefix + "_" + owner + "_" + mo.ID.Substring(1).Replace(' ', '_')+"_";
                if (tempFlak) staticprefix = tempFlakPrefix;
                if (prefix_replace != null) staticprefix = prefix_replace;
                staticprefix += "_" + autoFlakRun.ToString() + "_"; //prevent dup staticXX #s plus traceable.

                autoFlakChiefNum++;

                f = Calcs.makeAIChief(f, GamePlay, this, newPos.x, newPos.y, newPos.z, 10 + nfb * 2 + 50, chiefNum: autoFlakChiefNum, resetCount: resetCount, chiefprefix: staticprefix);
                resetCount = false;

                //Now actually PLACE the flak.

                double hdg = random.Next(360);
                Calcs.Shuffle(flak);
                var newPoint = new Point3d();
                int formation = random.Next(4);
                //formation = 1;
                int orientation = random.Next(360);

                for (int i = 0; i < nib; i++)
                {
                    double radius2 = 10 + 2 * nib;
                    if (formation == 0)
                    {
                        newPoint = Calcs.pointsOnACircle(newPos, radius2, nib, i, 1 / (2.0 * nib), 1);
                    } else if (formation == 1)
                    {
                        newPoint = Calcs.pointsOnALine(newPos, 10 + 7 * nib, orientation, nib, i, 1);
                    }
                    else if (formation == 2)
                    {
                        newPoint = Calcs.pointsOnADoubleLine(newPos, 5 + 3.5 * nib, 8, orientation, nib, i, 1);
                    } else
                    {
                        newPoint = Calcs.pointsOnARectangle(newPos, 5 + 3.5 * nib, 7 + 4.5 * nib, orientation, nib, i, 1);
                    }

                    string side = owner;

                    double head = Math.Round(hdg + random.Next(15));

                    //Radius_Hide 6000 means (I ASSUME) that the flak gun won't look away further than 6000.  Or ???.
                    if (ON_TESTSERVER) Console.WriteLine("Placing flak gun placed for {4} ({6}) at ({0:N0} {1:N0} {2:N0}) heading: {3:N0}, formation: {5})", Math.Round(newPoint.x), Math.Round(newPoint.y), Math.Round(mo.Pos.z), head, mo.Name, formation, side);
                    //Update - I THINK radius_hide is how far away the object is VISIBLE.
                    f = Calcs.makeStatic(f, GamePlay, this, Math.Round(newPoint.x), Math.Round(newPoint.y), 0, type: flak[flakType], heading: head, side: side, radiusHide: Convert.ToInt32(radiusHide), chiefNum: autoFlakChiefNum, resetCount: resetCount, staticprefix: staticprefix);
                    resetCount = false;
                    if (tempFlak) tempFlakTotal++;
                    totalFlakPlaced++;
                    if (totalFlakPlaced >= total_flak_temp) break; //allow partial batteries for tempflak
                    flakType++; //so we're just going to alternate between the two types of effective flak and that way if you have at least 2 flaks at each location you'll have one of each type.
                    if (flakType >= flak.Count) flakType = 0;
                    //});
                }

            }
            if (!tempFlak) autoFlakTotal += nib * nfb;

            //Console.WriteLine("{2} flak guns placed for {3} at {0} {1} - AutoFTotal: {4} TempFTotal: {5})", mo.Pos.x, mo.Pos.y, totalFlakPlaced, mo.Name, autoFlakTotal, tempFlakTotal);
            //wait to load, saves a lot of scrolling @ mission start.
            //Timeout(45, () => { GamePlay.gpPostMissionLoad(f); });
            return f;
        } catch (Exception ex)
        {
            Console.WriteLine("autoflakPlacement ERROR: " + ex.Message);
            return GamePlay.gpCreateSectionFile();
        }
    }

    public Dictionary<string, List<Point3d>> AutoFlak_locations = new Dictionary<string, List<Point3d>>() { };
    public object AutoFlak_locations_lock = new object();

    public bool MO_AutoFlak_selectLocations(MissionObjective mo, int no_to_find = 10, bool refresh = false)
    {
        try
        {
            bool dbug = false;

            //var MO_AutoFlak_locations = new List<Point3d>();
            if (ON_TESTSERVER) Console.WriteLine("AutoFlak_selectLocation: Finding autoflak location for {0} pos=({1:n0},{2:n0})", mo.ID, mo.Pos.x, mo.Pos.y);
            if (dbug) Console.WriteLine("MASL 1");
            if (MO_ObjectiveIsNavalVessel(mo) || mo.MOObjectiveType == MO_ObjectiveType.Submarine || mo.isMoving())
            {
                if (ON_TESTSERVER) Console.WriteLine("AutoFlak_selectLocation: Exiting autoflak location for {0} pos=({1:n0},{2:n0}) because moving? {3} {4}", mo.ID, mo.Pos.x, mo.Pos.y, mo.isMoving(), mo.MOMobileObjectiveType);

                return false;
            }
            double batteryRadius = mo.radius;
			
			//For AA/artillery these are concentrated at the center rather than being out beyond the perimeter
			if (mo.MOObjectiveType == MO_ObjectiveType.Artillery_and_AA) batteryRadius = 3;
            if (mo.MOObjectiveType == MO_ObjectiveType.Radar && mo.OwnerArmy == 2) batteryRadius += 65;  //For Blue radars, the exact location of flak can help locate the radar position, which we don't want. So we spread the batteries out a fair bit more.

            if (dbug) Console.WriteLine("MASL 2");
            List <Point3d> MO_AutoFlak_locations = mo.get_AutoFlak_locations();

            if (dbug) Console.WriteLine("MASL 2a");
            double nmc_to_Obj_Dist_m = distanceToNearestMobileConvoy_m(mo.Pos);

            if (dbug) Console.WriteLine("MASL 2b");
            if (refresh && nmc_to_Obj_Dist_m > 6000 && MO_AutoFlak_locations != null && MO_AutoFlak_locations.Count > 5) return true;

            //bool resetCount = true;


            //try to find a place that is not water,  outwards at least mo.radius + adder_m from the center of the objective
            int tries = 2000;
            double distmult = 2.5;

            if (dbug) Console.WriteLine("MASL 3");
            if (refresh)
            {
                tries = 50;
                distmult = 60;
            }

            double radius_hide = 6000; //I ASSUME this means the radar looks out only to 6000m ???
                                       //or, more likely, the item is VISIBLE to players at 6000m out. Er, whatever

            int no_found = 0;

            //Hmm, can't really do this as some we are refreshing due to moving objective moved away
            //others becuase it might have moved CLOSER
            //if (refresh && MO_AutoFlak_locations != null) no_found = MO_AutoFlak_locations.Count;

            //mo.AutoFlak_locations_pointer = 0;
            Point3d newPos = new Point3d();

            bool noSuitablePointFound = false;
            double min_nmc_dist_m = 5000;

            if (dbug) Console.WriteLine("MASL 4");

            for (int i = 0; i < tries; i++)
            {
                radius_hide = 6000;
                if (i * distmult > 1000) min_nmc_dist_m = 4000;
                if (i * distmult > 2000) min_nmc_dist_m = 3500;
                if (i > 0.85 * tries) min_nmc_dist_m = 3000;

                if (dbug) Console.WriteLine("MASL 5");

                double angle = random.NextDouble() * 2.0 * Math.PI;
                double radius = random.Next(10) + batteryRadius + i * distmult;  //try ever-greater distances if it's not working well
                                                                                 //Last resort, last 10% of tries, go inside the radius
                if (i > 0.9 * tries) radius = random.Next(10) + batteryRadius - (tries - i) * distmult;

                newPos.x = Math.Round(mo.Pos.x + Math.Cos(angle) * radius);
                newPos.y = Math.Round(mo.Pos.y + Math.Sin(angle) * radius);

                maddox.game.LandTypes landType = GamePlay.gpLandType(newPos.x, newPos.y);

                if (dbug) Console.WriteLine("MASL 6");
                double nmcDist_m = distanceToNearestMobileConvoy_m(newPos);

                double dist = 1000;
                double apRadius = 1000;
                try
                {
                    AiAirport ap = Calcs.nearestAirport(GamePlay, newPos);
                    dist = Calcs.CalculatePointDistance(ap.Pos(), newPos);
                    apRadius = ap.FieldR();
                }
                catch (Exception ex) { Console.WriteLine("ERROR FLAKPLACE! " + ex.ToString()); }

                if (dbug) Console.WriteLine("MASL 7");

                if (landType != maddox.game.LandTypes.WATER && dist > 999 && dist > apRadius && nmcDist_m >= min_nmc_dist_m)
                {
                    if (nmcDist_m < radius_hide - 1000) radius_hide = nmcDist_m - 1000;
                    newPos.z = radius_hide;
                    MO_AutoFlak_locations.Add(newPos);
                    no_found++;
                    //if (ON_TESTSERVER) Console.WriteLine("AutoFlak_selectLocation: Found autoflak location ({0:n0},{1:n0}) for {2} pos=({3:n0},{4:n0})", newPos.x, newPos.y, mo.ID, mo.Pos.x, mo.Pos.y);
                    if (no_found >= no_to_find) break;
                }

            }

            if (dbug) Console.WriteLine("MASL 8");
            if (no_found > 0)
            {
                lock (AutoFlak_locations_lock)
                {
                    AutoFlak_locations[mo.ID] = MO_AutoFlak_locations;
                }
                if (ON_TESTSERVER) Console.WriteLine("AutoFlak_selectLocation: Found {0} autoflak locations for {1} ({2})", no_found, mo.ID, mo.Name);
                return true;
            }

            if (dbug) Console.WriteLine("MASL 9");

            return false;

        }
        catch (Exception ex)
        {
            Console.WriteLine("AutoFlak_selectLocation ERROR: " + ex.Message);
            return false;
        }
    }

    public void MO_TestObjectiveWithFlak(MissionObjective mo, int NumFlakBatteries, int NumInFlakBattery)
    {
        {
            List<string> keys = new List<string>(MissionObjectivesList.Keys);



            Console.WriteLine("Handling TESTFLAK for {0} {1} {2} {3} {4}", mo.ID, mo.Pos.x, mo.Pos.y, NumFlakBatteries, NumInFlakBattery);
            Point3d newPos = mo.Pos;

            for (int j = 0; j < NumFlakBatteries; j++)
            {

                double rd = mo.radius;

                if (rd < 250) rd = 20;
                if (rd < 5000) rd = 5000;

                Point3d pos = mo.returnCurrentPosWithChief(); //use the "chief position calculator" where necessary

                newPos.x = pos.x + random.Next(Convert.ToInt32(mo.radius));
                newPos.y = pos.y + random.Next(Convert.ToInt32(mo.radius));


                //This is place ENEMY flake in the middle of a FRIENDLY objective, so that the enemyflak will destroy the objective
                string enemy = "de";
                if (mo.AttackingArmy == 1) enemy = "gb";

                //var flak = new List<string> { "Artillery.37mm_PaK_35_36", /*"Artillery.Flak37",*/ "Artillery.Bofors_StandAlone", "Artillery.3_7_inch_QF_Mk_I", "Artillery.Flak30_Shield", };
                var flak = new List<string> { "Artillery.Bofors_StandAlone", "Artillery.Bofors", }; //These are the big guns, literally

                //Now actually PLACE the flak.
                ISectionFile f = GamePlay.gpCreateSectionFile();



                double hdg = random.Next(360);
                Calcs.Shuffle(flak);
                for (int i = 0; i < NumInFlakBattery; i++)
                {
                    double angle1 = i * 2.0 / NumInFlakBattery * Math.PI + random.NextDouble() / NumInFlakBattery;
                    double radius2 = random.Next(2) + 10 + NumInFlakBattery * 2;

                    double nex = newPos.x + Math.Cos(angle1) * radius2;
                    double ney = newPos.y + Math.Sin(angle1) * radius2;

                    //Console.WriteLine("The artillery is at {0} {1})", new object[] { nex, ney });

                    string side = enemy;

                    //Timeout(30 + 2 * i, () =>
                    //{
                    f = Calcs.makeStatic(f, GamePlay, this, nex, ney, 0, type: flak[0], heading: hdg + random.Next(15), side: side);
                    //});
                }

                if (ON_TESTSERVER) Console.WriteLine("PostmissionLoad: TestObjectiveWithFlak");
                GamePlay.gpPostMissionLoad(f);


                Console.WriteLine("The TESTFLAK is at {0} {1})", new object[] { newPos.x, newPos.y });



            }
        }
    }

    static ManualResetEvent resetEvent = new ManualResetEvent(false);

    public bool MO_WriteMissionObject(object mo, string name, bool wait = false)
    {
        Console.WriteLine("Writing " + name + " to file (at "  + STATSCS_FULL_PATH + CAMPAIGN_ID + ")");

        string ext = ".xml";
        string filepath = STATSCS_FULL_PATH + CAMPAIGN_ID + "_SESSIONSTATE_" + name + ext;
        string suffix = "_SESSIONSTATE_" + name;
        string fileName_base = CAMPAIGN_ID;
        string backupDir = CAMPAIGN_ID + @" campaign backups\"; //will be added at the end of STATSCS_FULL_PATH

        //WriteAllTextAsyncWithBackups(string fileDir_base, string fileName_base, string suffix, string ext, string backupDir, bool wait = false, ManualResetEvent resetEvent = null)

        try
        {
            /* 
             * //System.Xml.Serialization.XmlSerializer writer = new System.Xml.Serialization.XmlSerializer(mo.GetType());
            BinaryFormatter writer = new BinaryFormatter();
            using (FileStream fs = File.Create(filepath))
            {
                writer.Serialize(fs, mo);
            }
            */

            //List<Type> knownTypes = new List<Type> { typeof(List<string>), typeof(Tuple<int, int, Player>) };
            //var serializer = new DataContractSerializer(mo.GetType(), knownTypes);
            var serializer = new DataContractSerializer(mo.GetType());
            string xmlString;
            using (var sw = new StringWriter())
            {
                using (var writer = new XmlTextWriter(sw))
                {
                    writer.Formatting = Formatting.Indented; // indent the Xml so it's human readable
                    serializer.WriteObject(writer, mo);
                    writer.Flush();
                    xmlString = sw.ToString();
                }
            }
            //File.WriteAllText(filepath, xmlString);

            int count = 0;

            //if wait is set we block the thread & wait until it's complete
            //we only do this at final program exit, just to make sure file write actually complete/not corrupted
            if (wait)
            {

                /*Task<bool> task = Calcs.WriteAllTextAsync(filepath, xmlString);
                bool res = await task; */
                //Calcs.WriteAllTextAsync(filepath_new, xmlString, wait: true, resetEvent: resetEvent);
                Calcs.WriteAllTextAsyncWithBackups(xmlString, STATSCS_FULL_PATH, fileName_base, suffix, ext, backupDir, wait: true, resetEvent: resetEvent);
                Console.WriteLine("MO_WriteMissionObject: waiting . . . to write " + name);
                resetEvent.WaitOne(); // Blocks the thread until until "set"
                Console.WriteLine("MO_WriteMissionObject: . . . . released.");

            } else Calcs.WriteAllTextAsyncWithBackups(xmlString, STATSCS_FULL_PATH, fileName_base, suffix, ext, backupDir);

        }
        catch (Exception ex)
        {
            Console.WriteLine("WriteMissionObjectivesClass ERROR: " + ex.ToString());
            return false;
        }
        return true;

    }

    public object MO_ReadMissionObject(object mo, string name)
    {
        Console.WriteLine("Reading " + name + " from file (at "  + STATSCS_FULL_PATH + CAMPAIGN_ID + ")");

        string filepath = STATSCS_FULL_PATH + CAMPAIGN_ID + "_SESSIONSTATE_" + name + ".xml";

        try
        {
            /* 
             * //System.Xml.Serialization.XmlSerializer writer = new System.Xml.Serialization.XmlSerializer(mo.GetType());
            BinaryFormatter writer = new BinaryFormatter();
            using (FileStream fs = File.Create(filepath))
            {
                writer.Serialize(fs, mo);
            }
            */
            string xmlString = File.ReadAllText(filepath);

            //XmlDictionaryReader reader =
            //    XmlDictionaryReader.CreateTextReader(fs, new XmlDictionaryReaderQuotas());

