    //Returns a # between 0 & 1 indicating the overall military strength/readiness for that army
    public double MO_AllMilitaryStrength_averaged(ArmiesE army)
    {
        double total = 0;
        double total_possible = 0;
        if (army == ArmiesE.None) return 1; //should never happen....
                                            //var armies = new List<ArmiesE> { ArmiesE.Red, ArmiesE.Blue };


        foreach (MO_MilitaryStrengthType type in MO_objectivetype_by_strengthtype.Keys)
        {
            //MO_MilitaryStreng
            //MO_military
            double res = MO_CalculateMilitaryStrength(army, type);
            total += res;
            total_possible += 1;
        }
        if (total_possible == 0) total_possible = 1;

        return total/total_possible;
    }


    public string MO_AllMilitaryStrength_ToString()
    {
        string ret = "";
        var armies = new List<ArmiesE> { ArmiesE.Red, ArmiesE.Blue };
        foreach (ArmiesE army in armies)
        {
            foreach (MO_MilitaryStrengthType type in MO_objectivetype_by_strengthtype.Keys)
            {
                //MO_MilitaryStreng
                //MO_military
                double res = MO_CalculateMilitaryStrength(army, type);
                MO_MilitaryStrengths[new Tuple<ArmiesE, MO_MilitaryStrengthType>(army, type)] = res;
                ret += army.ToString() + " " + type.ToString().Replace('_',' ') + " is at " + (res * 100.0).ToString("n0") + "%";
                ret += Environment.NewLine;
            }
            ret += Environment.NewLine;
        }
        return ret;
    }

    public void MO_CalculateAllMilitaryStrength()
    {
        var armies = new List<ArmiesE> { ArmiesE.Red, ArmiesE.Blue };
        foreach (ArmiesE army in armies)
        {
            foreach (MO_MilitaryStrengthType type in MO_objectivetype_by_strengthtype.Keys)
            {
                //MO_MilitaryStreng
                //MO_military
                double res = MO_CalculateMilitaryStrength(army, type);
                MO_MilitaryStrengths[new Tuple<ArmiesE, MO_MilitaryStrengthType>(army, type)] = res;
                Console.WriteLine(army.ToString() + " strength for " + type.ToString() + " is " + (res*100.0).ToString("n0") + "%");
            }
        }
    }

    //Returns the percent operational of the given army's objective types, for whichever type you request
    //Should be 0-100% (ie, values range 0-1);
    //return -1 indicates error some kind/ shouldn't ever happen
    public double MO_CalculateMilitaryStrength(ArmiesE army, MO_MilitaryStrengthType type)
    {
        double output = 1;

        double total = 0;
        double good = 0;
        double bad = 0;

        if (!MO_objectivetype_by_strengthtype.ContainsKey(type)) return -1;

        foreach (MissionObjective mo in MissionObjectivesList.Values)
        {
            if ((ArmiesE)mo.OwnerArmy != army) continue;
            if (!MO_objectivetype_by_strengthtype[type].Contains(mo.MOObjectiveType)) continue;
            double level = mo.Points;
            total += level;
            double add_amt = 0;
            if (mo.Destroyed) {
                add_amt = 1; //We're saying each thing destroyed reduces the capability by 1%; but see adjustments below.
                if (mo.DestroyedPercent > 1) add_amt += (mo.DestroyedPercent - 1) / 5; //little bonus for extra destruction of targets
            }
            else if (mo.DestroyedPercent > 0) add_amt = mo.DestroyedPercent/3;  //Doesn't count as much if only partially destroyed

            bad += add_amt * level;
        }
        good = total - bad;
        if (good < 0) good = 0;
        if (total == 0) total = 1;
        return good / total;
    }

    //Whenever team stats is updated, we include a list of all objectives destroyed & which players contributed.
    //This adds the objective name, time, and which players contributed to a string, which is then
    //Fetched when teams stats are output, then zeroed out again to start over
    public string MO_addPlayersWhoContributedforTeamStatsList_onObjectiveDestroyed(MissionObjective mo, bool html = false, bool display = false)
    {
        try
        {
            string nl = "<br>" + Environment.NewLine;
            if (!html) nl = Environment.NewLine;

            Tuple<string, DateTime> stl = showTimeLeft(player: null, showMessage: false, inGameTimeOnly: true);
            string inGameTime = stl.Item1;

            string ms = "On " + inGameTime + " " + ((ArmiesE)mo.AttackingArmy).ToString() + " destroyed " + mo.Name + nl;

            int count = 0;
            string output = "";
            foreach (string name in mo.PlayersWhoContributedNames)
            {
                if (count != 0) output += ", ";
                output += name;
                count++;
            }

            if (count > 0)
            {
                ms += "Pilots who contributed: " + output + nl;
            }

            count = 0;
            output = "";
            foreach (string name in mo.PlayersWhoScoutedNames.Keys)
            {
                if (count != 0) output += ", ";
                output += name;
                if (mo.PlayersWhoScoutedNames[name] > 1) output += string.Format(" ({0:n0}X)", mo.PlayersWhoScoutedNames[name]);
                count++;
            }

            if (count > 0)
            {
                ms += "Pilots who scouted this objective: " + output + nl;
            }

            count = 0;
            output = "";
            foreach (string name in mo.PlayersWhoRepairedNamesTimes.Keys)
            {
                if (count != 0) output += ", ";
                output += name;
                if (mo.PlayersWhoRepairedNamesTimes[name] >= 1) output += string.Format(" ({0:n0} loads)", mo.PlayersWhoRepairedNamesTimes[name]);
                count++;
            }

            if (count > 0)
            {
                ms += ArmiesL[mo.OwnerArmy] + " pilots who repaired this objective: " + output + nl;
            }

            //ms += nl;
            MissionObjectivesCompleteContributors_thisStatsPeriod[(ArmiesE)mo.AttackingArmy] += ms;

            return ms;
        }
        catch (Exception ex) { Console.WriteLine("main MO_addPlayersWhoContributedforTeamStatsList_onObjectiveDestroyed ERROR: " + ex.ToString()); return ""; }


    }

    public string MO_getAndClearPlayersWhoContributedforTeamStatsList(ArmiesE army, bool clear = true)
    {
        if (!MissionObjectivesCompleteContributors_thisStatsPeriod.ContainsKey(army)) return "";
        string ret = MissionObjectivesCompleteContributors_thisStatsPeriod[army];
        if (clear) MissionObjectivesCompleteContributors_thisStatsPeriod[army] = "";
        return ret;
    }    



    public string MO_PlayersWhoContributedToObjectivesList(string winner)
    {
        string output = "";

        int army = 0;
        if (winner == "Red") army = 1;
        if (winner == "Blue") army = 2;
        if (army == 0) return output;

        var contribs = new HashSet<string>();

        foreach (MissionObjective mo in MissionObjectivesList.Values)
        {
            if (mo.AttackingArmy != army) continue;
            if (!mo.Destroyed) continue;
            if (mo.PlayersWhoContributedNames == null || mo.PlayersWhoContributedNames.Count == 0) continue;

            output += " - " + mo.Name + ": ";
            int count = 0;
            foreach (string name in mo.PlayersWhoContributedNames)
            {
                if (count != 0) output += ", ";
                output += name;
                count++;
                contribs.Add(name);
            }

            output += "<br>" + Environment.NewLine;
        }

        if (contribs.Count > 0) output += "<br>" + Environment.NewLine + (contribs.Count).ToString("F0") + " players contributed to destroying objectives that contributed to this victory.<br>" + Environment.NewLine;
        return output;
    }

