            }
            catch (Exception ex) { Console.WriteLine("MO_addDamagersToListOfPlayersWhoContributed ERROR : {0} ", ex.ToString()); }
        }
        ); //task.run()
    }

    public void MO_addInitiatorToListOfPlayersWhoContributed(AiDamageInitiator initiator, string ID)
    {
        if (MissionObjectivesList.ContainsKey(ID)) MO_addInitiatorToListOfPlayersWhoContributed(initiator, MissionObjectivesList[ID]);
        else Console.WriteLine("MO_addInitiatorToListOfPlayersWhoContributed ERROR: Couldn't find Mission Objective ID: " + ID);
    }

    public void MO_addInitiatorToListOfPlayersWhoContributed(AiDamageInitiator initiator, MissionObjective mo)
    {
        try
        {
            if (initiator == null) return;
            if (initiator.Player == null) return;
            if (initiator.Player.Name() == null) return;
            if (initiator != null && initiator.Player != null && initiator.Player.Name() != null)
            {
                mo.makeScoutedFromBombRun(initiator.Player);
                mo.PlayersWhoContributedNames.Add(initiator.Player.Name());
            }
        }
        catch (Exception ex) { Console.WriteLine("MO_addInitiatorToListOfPlayersWhoContributed ERROR: {0}", ex.ToString()); }
    }

    //Ships often kill themselves or nearby ships, so this is trying to identify those & not count them
    public bool MO_isDeathOnlyDuetoSelf(List<DamagerScore> damages, AiActor damagedAct)
    {
        try
        {
            //Console.WriteLine("main_PointArea_actor");
            foreach (DamagerScore d in damages)
            {
                if (d == null) continue;
                AiDamageInitiator adi = d.initiator;
                if (adi == null) continue;
                
                if (adi.Player != null) return false; //at least 1 player contributed to the death, so it's good
                if (adi.Person != null) return false;
                if (adi.Actor == null) continue;
                AiActor damageAct = adi.Actor;
                if (damageAct == damagedAct) continue; //damager & damaged are same, this doesn't count as actual death, just suicide
                if (damageAct.Army() > 0 && damageAct.Army() != damagedAct.Army()) return false;  //damager actxor is not neutral, and the damaged thing is neutral or opposite army)
                if (damageAct.Name() == damagedAct.Name()) continue; //its very common for one BritishBarge to ram the next BritishBarge etc & kill it
                if (adi as AiGroundActor != null && damagedAct as AiGroundActor != null)
                {
                    AiGroundActor adig = adi as AiGroundActor;
                    AiGroundActor dAg = damagedAct as AiGroundActor;
                    if (adig == dAg) continue;  //same ground actor or
                    if (adig.Type() == dAg.Type() ) continue; //same type of ground actor
                }

                return false; //This one passed the test - the damager is some different actor, not the same army, not the same type etc
            }
            return true;
        }

        catch (Exception ex) { Console.WriteLine("MO_isDeathOnlyDuetoSelf ERROR: {0}", ex.ToString()); return false; }
    }


    public void MO_CalculateAndRecordTriggerObjectivesDamagePercent(string shortName, bool active)
    {
        if (!active) return;
        foreach (MissionObjective mo in MissionObjectivesList.Values)
        {
            if (mo.MOTriggerType != MO_TriggerType.Trigger) continue;
            if (mo.TriggerName != shortName) continue;
            MO_CalculateAndRecordTriggerObjectivesDamagePercent(mo, triggerCalled: true);

            Console.WriteLine("MO_DestroyObjective: Disabling trigger " + shortName);
            if (GamePlay.gpGetTrigger(shortName) != null) GamePlay.gpGetTrigger(shortName).Enable = false;
            return;
        }

    }

    public void MO_CalculateAndRecordTriggerObjectivesDamagePercent(MissionObjective mo, bool triggerCalled = false)
    {
        try {


            if (mo.ObjectsRequiredToTrigger_num == 0) mo.ObjectsRequiredToTrigger_num = 10;

            if (triggerCalled && mo.ObjectsDestroyed_num < mo.ObjectsRequiredToTrigger_num) mo.ObjectsDestroyed_num = mo.ObjectsRequiredToTrigger_num;

            DateTime currTime_dt = DateTime.UtcNow;
            double repairSpeedupFactor = 1;
            if (MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy].ContainsKey("RepairCrewEndTime_dt") && MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy]["RepairCrewEndTime_dt"] > currTime_dt) repairSpeedupFactor = 4;

            double tempDestroyedPercent = mo.ObjectsDestroyed_num / mo.ObjectsRequiredToTrigger_num;

            if (tempDestroyedPercent > 1) tempDestroyedPercent = 1 + 0.4 * Math.Pow(tempDestroyedPercent - 1.0, 0.7);

            double oldDestroyedPercent = mo.DestroyedPercent;
            mo.DestroyedPercent = tempDestroyedPercent;
            double addedPercent = tempDestroyedPercent - oldDestroyedPercent;

            if (addedPercent < 0) addedPercent = 0; //We might for some reason REDUCE the percent destroyed, which if negative will cause problems below


            if (mo.ObjectsDestroyed_num >= mo.ObjectsRequiredToTrigger_num)
            {
                if (!mo.Destroyed || !mo.ObjectiveAchievedForPoints)
                    MO_DestroyObjective(mo.ID, percentdestroyed: mo.ObjectsDestroyed_num / mo.ObjectsRequiredToTrigger_num, timetofixFromNow_sec: mo.TimetoRepairIfDestroyed_hr * 3600 / repairSpeedupFactor);
            }
            else if (mo.DestroyedPercent > 1)
            {
                double additionalTimeToFix_hr = (mo.TimetoRepairIfDestroyed_hr * addedPercent / repairSpeedupFactor);
                if (mo.TimeToUndestroy_UTC.HasValue) mo.TimeToUndestroy_UTC.Value.AddHours(additionalTimeToFix_hr);  //just add time proportional to how many objects required to kill it 100%.  But divided by 4 since we are discounting the destruction
                else mo.TimeToUndestroy_UTC = DateTime.UtcNow.AddHours(additionalTimeToFix_hr);
                MO_DestroyObjective_addTimeOrPoints(mo.ID, percentdestroyed: mo.DestroyedPercent); //adds possible Campaign points, mostly, in this case
            }
            else if (Math.Floor(oldDestroyedPercent * 100.0 / 10.0) % 2 != Math.Floor(mo.DestroyedPercent * 100.0 / 10.0) % 2) //if crossing threshold @ 10, 20, 30, etc, 50, 100% give a message with status update of objective
            {
                twcLogServer(null, "{0} damaged: {1}% destroyed, {2} items damaged of {3} required to destroy objective", new object[] { mo.Name, (Math.Floor(mo.DestroyedPercent * 100.0)).ToString("F0"), mo.ObjectsDestroyed_num.ToString("F0"), mo.ObjectsRequiredToTrigger_num.ToString("F0") });
            }
        }
        catch (Exception ex) { Console.WriteLine("MO_CalculateAndRecordTriggerObjectivesDamagePercent ERROR: " + ex.ToString()); }
    }


    //calculates & returns the destroyed percentage based on # of objects killed w/in the radius
    //kg of ordnance dropped in radius, & number of "Chief" actors killed belonging to this objective
    //So it is a complex thing where requirements for any of those can be zero and if so  that factor just drops out
    //But any factors remaining get a percentage of the total damage points (1/3 or 1/2, if 3 or 3)
    //BUT if say objects is 2/30 requires and KG bombs is 20000/5000 required then the ordnance points
    //start counting towards the total, just at a lower rate.
    //The idea here is that people don't get "stuck" being unable to finish off an objective.
    public void MO_CalculateAndRecordPointareaObjectivesDamagePercent(MissionObjective mo)
    {
        try
        {
            if (mo == null) return;
            mo.fixDestructionValues();

            DateTime currTime_dt = DateTime.UtcNow;
            double repairSpeedupFactor = 1;
            if (MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy].ContainsKey("RepairCrewEndTime_dt") && MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy]["RepairCrewEndTime_dt"] > currTime_dt) repairSpeedupFactor = 4;


            double divisor = 0;
            if (mo.OrdnanceRequiredToTrigger_kg > 0) divisor++;
            if (mo.ObjectsRequiredToTrigger_num > 0) divisor++;
            if (mo.ActorsRequiredToTrigger_num > 0) divisor++;
            if (mo.ActorsDestroyed_num == 0 && mo.OrdnanceRequiredToTrigger_kg == 0 && mo.ActorsRequiredToTrigger_num > 0 && mo.OrdnanceOnTarget_kg > 8000) mo.ActorsDestroyed_num = 1;

            //Special case where you are supposed to destroy actors but the area has been pounded
            //over & over and still actors not destroyed.  With this the obj will still trigger.
            if (mo.ActorsDestroyed_num == 0 && mo.OrdnanceRequiredToTrigger_kg == 0 && mo.ActorsRequiredToTrigger_num > 0 && mo.OrdnanceOnTarget_kg > 12000) mo.ActorsDestroyed_num = mo.ActorsRequiredToTrigger_num;

            if (divisor == 0) divisor = 1; //If both objects & KG required to trigger, we give each of them 50% of the required 100% for destruction.  If Objects, KG, AND Actors, then each gets 33%.

            //So this is a bit complicated, but percentage destroyed due to ordinance & KG can't go above 50% (or 33%...) UNLESS the other type of objective is completed also.
            //The prevents, ie, showing 125% destroyed purely by bombing KG, when 0 of the 10 required targets have been killed.
            //In that case it will show 50% complete, not 125%
            //Now, once both sides are complete (KG & objects) then additional KG or objects killed will add more percent
            double dst_pc_ord = 0;
            if (mo.OrdnanceRequiredToTrigger_kg > 0) dst_pc_ord = mo.OrdnanceOnTarget_kg / mo.OrdnanceRequiredToTrigger_kg / divisor;
            double dst_pc_obj = 0;
            if (mo.ObjectsRequiredToTrigger_num > 0) dst_pc_obj = mo.ObjectsDestroyed_num / mo.ObjectsRequiredToTrigger_num / divisor;

            double dst_pc_act = 0;
            if (mo.ActorsRequiredToTrigger_num > 0) dst_pc_act = mo.ActorsDestroyed_num / mo.ActorsRequiredToTrigger_num / divisor;

            double dst_pc_obj_orig = dst_pc_obj;
            if (dst_pc_obj > divisor && mo.OrdnanceRequiredToTrigger_kg > mo.OrdnanceOnTarget_kg) dst_pc_obj = divisor;

            //So if the KG requirement has been met, but not the OBJ requirement, we cap the KG contribution to the % total at 50%.  Except . . . if the KG contribution
            //goes over 100% then we start to add it back in at 1/3 rate.  Basically even if you can't kill the objects
            //you can still get the objective by bombing the %#$$#$ out of it
            //However, this applies only to objectives requiring 1000 or more KG on target to kill.
            //That is, some objectives we can MAKE into "kill the individual items" requirements by keeping the KG requirement to <1000
            if (dst_pc_ord > divisor && (mo.ObjectsDestroyed_num < mo.ObjectsRequiredToTrigger_num || mo.ActorsDestroyed_num < mo.ActorsRequiredToTrigger_num))
            {
                double orig_dst_pc_ord = dst_pc_ord;
                dst_pc_ord = divisor;
                double add_dst_pc_ord = 0;
                if (mo.OrdnanceRequiredToTrigger_kg > 1000 && orig_dst_pc_ord > 1) add_dst_pc_ord = (orig_dst_pc_ord - divisor) / 3;
                dst_pc_ord += add_dst_pc_ord;
            }

            //Similarly for objects - if numobj required >=15 && you're just killing bazillions of objects, then
            //they start to count towards the ordnance requirement at 1/3 rate
            if (dst_pc_obj_orig > divisor && (mo.OrdnanceRequiredToTrigger_kg > mo.OrdnanceOnTarget_kg || mo.ActorsRequiredToTrigger_num > mo.ActorsDestroyed_num))
            {
                double add_dst_pc_obj = 0;
                if (mo.ObjectsRequiredToTrigger_num >= 12 && dst_pc_obj_orig > 1) add_dst_pc_obj = (dst_pc_obj_orig - divisor) / 3;

                if (mo.ObjectsRequiredToTrigger_num < 16) add_dst_pc_obj *= mo.ObjectsRequiredToTrigger_num / 16;
                dst_pc_obj += add_dst_pc_obj;
            }
            //Similarly for actors - if numobj  you're just killing bazillions of actors, more than required, then
            //they start to count towards the ordnance requirement at 1/3 rate
            if (dst_pc_act > divisor && (mo.OrdnanceRequiredToTrigger_kg > mo.OrdnanceOnTarget_kg || mo.ObjectsRequiredToTrigger_num > mo.ObjectsDestroyed_num))
            {
                double dst_pc_act_orig = dst_pc_act;
                double add_dst_pc_act = 0;
                if (dst_pc_act_orig > 1) add_dst_pc_act = (dst_pc_act_orig - divisor) / 3;

                dst_pc_act += add_dst_pc_act;
            }

            if (mo.ObjectsRequiredToTrigger_num < 5 && dst_pc_obj * divisor > 2.5) dst_pc_obj = 2.5 / divisor; //If numobjects is real small, don't allow huge multipliers of objective killed percent 
            if (mo.OrdnanceOnTarget_kg <= 1000 && dst_pc_ord * divisor > 2.5) dst_pc_ord = 2.5 / divisor; //If KG ordnancerequired is real small, don't allow huge multipliers of  objective killed percent

            if (mo.ActorsRequiredToTrigger_num < 5 && dst_pc_act * divisor > 2.5) dst_pc_act = 2.5 / divisor; //If numobjects is real small, don't allow huge multipliers of objective killed percent

            //double oldDestroyedPercent = mo.DestroyedPercent;
            double tempDestroyedPercent = dst_pc_obj + dst_pc_ord + dst_pc_act;

            //Once we reach 100% everything is most all destroyed so the additional damage slows down a lot
            //if (tempDestroyedPercent > 1) tempDestroyedPercent = 1 + (tempDestroyedPercent - 1.0) / 4.0;
            //2023-01, we are using formulas like (some constant)*pct^0.7 to give diminishing returns for additional destruction above 100%.  So 0.4*pct^0.7 will give 40% destruction for the 2nd 100%
            //destroyed, but only 27% for the next 100% etc. pct is the percentage ABOVE 1.0 (or 100%)

            //damage above 100%
            if (tempDestroyedPercent > 1) tempDestroyedPercent = 1 + 0.4 * Math.Pow(tempDestroyedPercent - 1.0, 0.7);
			
			//5/2026 - make 500% the max destruction possible
			if (tempDestroyedPercent > 5) tempDestroyedPercent = 5;


            double oldDestroyedPercent = mo.DestroyedPercent;
            mo.DestroyedPercent = tempDestroyedPercent;
            double addedPercent = tempDestroyedPercent - oldDestroyedPercent;
            if (addedPercent < 0) addedPercent = 0; //We might for some reason REDUCE the percent destroyed, which if negative will cause problems below


            Console.WriteLine("MO_CalculateAndRecordPointareaObjectivesDamagePercent: {0:F0}% objects, {1:F0}% KG, {9:F0}% actors => {2:F0}% Tot, {3:F0} KG KGreq: {4:F0} Numreq: {5:F0} ActReq: {7:F0} ActDest: {8:F0} Name: {6} ", dst_pc_obj * 100, dst_pc_ord * 100, mo.DestroyedPercent * 100, mo.OrdnanceOnTarget_kg, mo.OrdnanceRequiredToTrigger_kg, mo.ObjectsRequiredToTrigger_num, mo.Name, mo.ActorsRequiredToTrigger_num, mo.ActorsDestroyed_num, dst_pc_act * 100);


            //if (mo.ObjectsDestroyed_num > mo.ObjectsRequiredToTrigger_num)
            if ((!mo.Destroyed || !mo.ObjectiveAchievedForPoints) && mo.DestroyedPercent >= 1)
                MO_DestroyObjective(mo.ID, true, percentdestroyed: mo.DestroyedPercent, timetofixFromNow_sec: mo.TimetoRepairIfDestroyed_hr * 3600 / repairSpeedupFactor); // 1 because, we always get 1 object here. //hnMO_DestroyObjective(ID, true, percentdestroyed: mo.DestroyedPercent, timetofix_s: mo.TimetoRepairIfDestroyed_hr * 3600); //Note - MUST use >= here as it covers the case where ordnanceKG and/or object_numrequired = 0
            else if (mo.DestroyedPercent > 1)
            {
                double additionalTimeToFix_hr = (mo.TimetoRepairIfDestroyed_hr * addedPercent / repairSpeedupFactor);
                if (mo.TimeToUndestroy_UTC.HasValue) mo.TimeToUndestroy_UTC.Value.AddHours(additionalTimeToFix_hr);  //just add time proportional to how many objects required to kill it 100%.  But divided by 4 since we are discounting the destruction
                else mo.TimeToUndestroy_UTC = DateTime.UtcNow.AddHours(additionalTimeToFix_hr);
                MO_DestroyObjective_addTimeOrPoints(mo.ID, percentdestroyed: mo.DestroyedPercent); //adds possible Campaign points, mostly, in this case
            }
            else if (Math.Floor(oldDestroyedPercent * 100.0 / 10.0) % 2 != Math.Floor(mo.DestroyedPercent * 100.0 / 10.0) % 2) //if crossing threshold @ 10, 20, 30, etc, 50, 100% give a message with status update of objective
            {
                twcLogServer(null, "{0} damaged: {1}% destroyed, {2} items damaged, {4} enemies killed, {3} kg on target", new object[] { mo.Name, (Math.Floor(mo.DestroyedPercent * 100.0)).ToString("F0"), mo.ObjectsDestroyed_num.ToString("F0"), mo.OrdnanceOnTarget_kg.ToString("F0"), mo.ActorsDestroyed_num.ToString("F0") });
            }
        }
        catch (Exception ex) { Console.WriteLine("PointArea Calculation ERROR: " + ex.ToString()); }

    }
    Dictionary<MissionObjective, DateTime> restartChief_log = new Dictionary<MissionObjective, DateTime>() { };

    public void restartChiefIfAllDead(AiActor actor, string shortName)
    {
        Console.WriteLine("restartChiefIfAllDead running... will restart {0} in 10-20 minutes if its the last actor of an objective...", shortName);

        //Timeout(random.NextDouble * 600 + 600, () => {
        Timeout(random.NextDouble() * 30 + 300, () =>
        { //speed things up for testing purposes
            var molk = new List<string>(MissionObjectivesList.Keys);

            foreach (string ID in molk)
            {
                try
                {
                    MissionObjective mo = MissionObjectivesList[ID];
                    if (actor.Army() != mo.OwnerArmy) continue;
                    if (mo.MOTriggerType != MO_TriggerType.PointArea || !mo.IsEnabled || mo.Destroyed || !mo.hasChief()) continue;
                    if (!(shortName.ToLower()).Contains(mo.ChiefName.ToLower())) continue;
                    if (mo.chiefIsAlive()) continue;
                    DateTime currTime_dt = DateTime.UtcNow;
                    if (restartChief_log.ContainsKey(mo) && currTime_dt.Subtract(restartChief_log[mo]).TotalSeconds < 600) continue; //only run this once every 10 minutes at most
                    restartChief_log[mo] = currTime_dt;

                    Console.WriteLine("restartChiefIfAllDead: {0} was the last actor in objective {1} that is still alive, so the initsubmission {2} is being run now to restart it AND/OR the mobileobjective is being re-established", shortName, mo.ID, mo.InitSubmissionName);
                    mo.loadInitSubmission();
                    mo.reloadMobileObjectiveChiefs();

                }
                catch (Exception ex) { Console.WriteLine("restartChiefIfAllDead ERROR: " + ex.ToString()); }
            }
        });
    }

    //FOR AIACTOR TARGETS DESTROYED
    public void MO_HandlePointAreaObjectives(AiActor actor, List<DamagerScore> damages, string shortName="")
    {
        try
        {
            if (actor == null || actor.Army() < 1 || actor.Army() > 2 || (actor as AiPerson) != null) return;  //we don't count people/person's killed & it causes "object reference" errors below

     
            //TODO: Could easily combine this with the GroundStationaries routine, 95% the same

            DateTime currTime_dt = DateTime.UtcNow;
            double repairSpeedupFactor = 1;

            if (MO_isDeathOnlyDuetoSelf(damages, actor))
            {
                Console.WriteLine("PointArea Actor: This was an actor that killed/destroyed itself or nearby barges crashing into each other, an actor being deleted, etc. Exiting");
                if (actor != null)
                {
                    Console.WriteLine("PointArea Actor crash: Actor {0} army: {1} pos: {2:n0}/{3:n0}/{4:n0}", actor.Name(), actor.Army(), actor.Pos().x, actor.Pos().y, actor.Pos().z);
                }
                if (actor as AiGroundActor != null)
                {
                    Console.WriteLine("PointArea Actor (ground) crash: {0}", (actor as AiGroundActor).Type());
                }

                //XXXX TODO: If these are actors/chiefs in an objective, if ALL of them are dead we should reload that submission
                //to get them going again. 2022/12.
                //restartChiefIfAllDead(actor, shortName); //removing, we're doing this a different way now, checking each OBJ periodically with _recurs
                return; //nothing to do now

            }

            var molk = new List<string>(MissionObjectivesList.Keys);

            foreach (string ID in molk)
            {
                try
                {
                    MissionObjective mo = MissionObjectivesList[ID];
                    if (actor.Army() != mo.OwnerArmy) continue;
                    if ((mo.MOTriggerType != MO_TriggerType.PointArea &&
                        mo.MOTriggerType != MO_TriggerType.Trigger)
                        || !mo.IsEnabled) continue;

                    
                    double dist = Calcs.CalculatePointDistance(actor.Pos(), mo.Pos);

                    bool chiefHit = mo.hasChief() && (shortName.ToLower()).Contains(mo.ChiefName.ToLower());
                    if (Calcs.IsNaN(actor.Pos()) && !chiefHit) continue;
                    mo.fixDestructionValues();					

                    //If this has finished off the last Chief, but the objective has not yet been  destroyed
                    //this will reload the initsubmission in 10-20 minutes, which keeps the objective alive, on the board &
                    //available for attack etc
                    if (chiefHit) restartChiefIfAllDead(actor, shortName); //we're doing this using _recurs now, maybe hsould disable this approach.

                    //For some obj, triggerdestroy radius is a small "nucleus" where hits create
                    //more damage.  For others, like naval obj, it is a MUCH LARGER radius that accounts
                    //for the fact that ships like to drift.  
                    //this is a hit - it's either in the radius OR trigger radius OR it's a chief hit
                    if (dist <= mo.TriggerDestroyRadius || dist <= mo.radius  || chiefHit)
                    {

                        if (chiefHit) Console.WriteLine("PointArea Actor matches CHIEF {3}: {0}, {1}, {2}, {3}", actor.Name(), actor.Army(), (actor as AiCart).InternalTypeName(), mo.Name, mo.ChiefName);
                        else if (true) Console.WriteLine("PointArea Actor within pointarea TriggerDestroyRadius of {3}: {0}, {1}, {2}", actor.Name(), actor.Army(), (actor as AiCart).InternalTypeName(), mo.Name);

                        string type = "";
                        if ((actor as AiCart) != null && (actor as AiCart).InternalTypeName() != null) type = (actor as AiCart).InternalTypeName();

                        string groundType = "";
                        if (actor as AiGroundActor != null) groundType = (actor as AiGroundActor).Type().ToString();

                        if (!chiefHit)
                        {
                            //For these objective types, only count actor kills that match their type
                            //(except chiefHits, which we know always count)
                            if (MO_Naval_Ship_ObjectiveTypes.Contains(mo.MOObjectiveType) && !groundType.ToLower().Contains("ship")) continue;
                            if (mo.MOObjectiveType == MO_ObjectiveType.Submarine && !groundType.ToLower().Contains("submarine")) continue;
                            if (mo.MOObjectiveType == MO_ObjectiveType.Artillery_and_AA && !groundType.Contains("AAGun") && !groundType.Contains("Artillery")) continue;
                        }

                        mo.LastHitTime_UTC = DateTime.UtcNow;
                        MO_addDamagersToListOfPlayersWhoContributed(damages, mo);

                        if (MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy].ContainsKey("RepairCrewEndTime_dt") && MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy]["RepairCrewEndTime_dt"] > currTime_dt) repairSpeedupFactor = 4;

                        if (mo.MOTriggerType == MO_TriggerType.Trigger)
                        {
                        //for triggers we don't differentiate "actors" vs "objects" - they are counted alike
                            //mo.ActorsDestroyed_num++;
                            mo.ObjectsDestroyed_num++;
                            MO_CalculateAndRecordTriggerObjectivesDamagePercent(mo);
                            return;
                        }

                        double oldOONT_num = mo.ObjectsDestroyed_num;
                        double oldAD_num = mo.ActorsDestroyed_num;

                        if (chiefHit)
                        {
                            mo.ActorsDestroyed_num = mo.ActorsDestroyed_num + 1;
                            //OK, this is a bit of a gimme, but if they have destroyed all actors/chiefs
                            //there ARE then they get credit for destroying the OBJ
                            //Sometimes actors kill themselves or whatever?  Or they just die, from artillery
                            //fire or whatever.  So even if the pilot is supposed to kill say 8 of them,
                            //of there are only 3 left and they kill all 3 of those and no more are left to kill, then that's it - they have COMPLETED the objective.
                            if (!mo.chiefIsAlive() && mo.ActorsDestroyed_num < mo.ActorsRequiredToTrigger_num) mo.ActorsDestroyed_num = mo.ActorsRequiredToTrigger_num;
                        }
                        //2022/12 OK now we are counting ACTORS hit, that match, as BOTH actor AND damagecount points.  That gives us more flexibility in scoring as actors just count as "1" where as groundtargets of all types have VARYING point values depending on their value; see below.
                        
                            //Damage bonuses for various specific types, that count for NON-chief actors/objects (as their only points) and CHIEF actors, too, as their "damage points" that they get in addition to the actor point (which is just 1 per actor).  This is hard to do systematically.
                            //type - should contain the string found in the .mis file for objects, such as Environment.TelegaBallon_UK1
                            //groundType is the enum list  of type maddox.game.world.AiGroundActorType which has a bunch of the things listed below plus more

                            double damageCount = 1;
                            if (type.Contains("Barge")) damageCount = 7;
                            //if (typeToLower().Contains("submarine")) damageCount = 11;
                            else if (groundType.Contains("ShipTransport")) damageCount = 9;
                            else if (groundType.Contains("ShipSubmarine")) damageCount = 13;
                            else if (type.Contains("Tanker")) damageCount = 12;
                            else if (groundType.Contains("ShipCarrier") || groundType.Contains("ShipBattleship")) damageCount = 30;
                            else if (groundType.Contains("ShipCruiser") || groundType.Contains("ShipDestroyer") || groundType.Contains("SmallWarship") || groundType.ToLower().Contains("warship") || type.ToLower().Contains("warship")) damageCount = 25;
                            else if (groundType.ToLower().Contains("ship")) damageCount = 9;
                            else if (groundType.Contains("AAGun") || groundType.Contains("Artillery") || groundType.Contains("Tank") || groundType.Contains("Armored") || groundType.Contains("Amphibian") || groundType.Contains("SPG")) damageCount = 4;
                            else if (groundType.ToLower().Contains("truck") || groundType.ToLower().Contains("tractor") || groundType.ToLower().Contains("trailer")) damageCount = 2;
                            else if (groundType.ToLower().Contains("radar")) damageCount = 6;
                            else if (groundType.ToLower().Contains("plane")) damageCount = 3;
                            else if (groundType.ToLower().Contains("bridge")) damageCount = 10;


                            if (!MO_ObjectiveIsNavalVessel(mo) && mo.TriggerDestroyRadius> 0 && dist > mo.TriggerDestroyRadius) damageCount *= 0.333; //less damage effectiveness if inside radius but outside triggerradius
                            mo.ObjectsDestroyed_num = damageCount + mo.ObjectsDestroyed_num;
                        

                        MO_CalculateAndRecordPointareaObjectivesDamagePercent(mo);

                    }
            
                }
                catch (Exception ex) { Console.WriteLine("MO_HandlePointAreaObjectives (actor) LOOP ERROR: " + ex.ToString()); }
            }
        }
        catch (Exception ex) { Console.WriteLine("MO_HandlePointAreaObjectives (actor) ERROR: " + ex.ToString()); }

    }

    //FOR STATIONARY TARGETS DESTROYED ***OR*** BUILDINGS
    //if st==null then it is a BUILDING instead of a groundstationary object
    public void MO_HandlePointAreaObjectives(GroundStationary st, AiDamageInitiator initiator, string title = null, Point3d? BuildingPos = null, bool destroyedByCannon = false)
    {
        try
        {
            Point3d pos = new Point3d(-1, -1, -1);

            if (initiator == null)
            {
                if (st != null) Console.WriteLine("main_PointArea_stationary " + st.Name + " killed but no initiator, probably just script killing an objective, not counting, returning.");
                return;
            }

            if (st != null) pos = st.pos;
            else if (BuildingPos.HasValue) pos = BuildingPos.Value;
            else return; //both are null, so can't really do anything here as we don't have a position

            string name = "";
            if (st != null) name = st.Name;
            else if (title != null) name = title;

            //Console.WriteLine("main_PointArea_stationary " + name + " " + title);

            DateTime currTime_dt = DateTime.UtcNow;
            double repairSpeedupFactor = 1;
						

            foreach (string ID in MissionObjectivesList.Keys.ToList())
            {
                MissionObjective mo = MissionObjectivesList[ID];
                if ( ( mo.MOTriggerType != MO_TriggerType.PointArea &&
                    mo.MOTriggerType != MO_TriggerType.Trigger)
                    || !mo.IsEnabled) continue;

                //this MIGHT double-count some things?  But then thye might be double-counted anyway byt dist?`
                bool chiefHit = mo.hasChief() && (name.ToLower()).Contains(mo.ChiefName.ToLower());

                if (Calcs.IsNaN(pos)) continue;
                double dist = Calcs.CalculatePointDistance(pos, mo.Pos);

                if (dist < 10000 && ON_TESTSERVER) try
                    {
                        Console.WriteLine("MO_HandlePointAreaObjectives stationary/building CLOSE: " + name + " " + st.country + " " + st.pos.x.ToString("F0") + " " + st.pos.y.ToString("F0") + " " + st.Title + " " + st.Type.ToString() + " " + dist.ToString("F0") + " " + mo.radius.ToString("F0") + " at MO: " + mo.ID);
                    }
                    catch (Exception ex) { }

                //Usually triggerradius< radius because it is a concentrated area in center of target.  
                //But other times (ships) radius < triggerdestroy radius 
                if (dist <= mo.radius || dist <= mo.TriggerDestroyRadius || chiefHit) //doing <= here instead of > continue avoids a problem where dist == NaN or infinity etc.  NaN > X is always false (so is NaN < x etc)
                {
                    mo.fixDestructionValues();

                    if (st != null)
                    {
                        string groundType = st.Type.ToString();
                        if (MO_Naval_Ship_ObjectiveTypes.Contains(mo.MOObjectiveType) && !groundType.ToLower().Contains("ship")) continue;
                        if (mo.MOObjectiveType == MO_ObjectiveType.Submarine && !groundType.ToLower().Contains("submarine")) continue;
                        if (mo.MOObjectiveType == MO_ObjectiveType.Artillery_and_AA && !groundType.Contains("AAGun") && !groundType.Contains("Artillery")) continue;
                    }

                    try
                    {
                        Console.WriteLine("MO_HandlePointAreaObjectives stationary/building HIT: " + name + " " + st.country + " " + st.pos.x.ToString("F0") + " " + st.pos.y.ToString("F0") + " " + title + " " + st.Type.ToString() + " at MO: " + mo.ID);
                    }
                    catch (Exception ex) { }

                    //Console.WriteLine("BSD: 1");
                    mo.LastHitTime_UTC = DateTime.UtcNow;

                    double oldOONT_num = mo.ObjectsDestroyed_num;
                    //Console.WriteLine("BSD: 2");
                    double damageCount = 1;
                    if (title !=null && (title.Contains("Barge") || title.Contains("Tanker") || title.Contains("Cruiser"))) damageCount = 10;
                    //Console.WriteLine("BSD: 4");

                    if (dist > mo.TriggerDestroyRadius) damageCount *= 0.5; //less damage effectiveness if inside radius but outside triggerradius
					
					if (destroyedByCannon) {
						damageCount *= 3; //triple credit for strafing damage of ground objects
					}
					
                    if (mo.MOTriggerType == MO_TriggerType.PointArea)
                        mo.ObjectsDestroyed_num += damageCount;
                    else if (mo.MOTriggerType == MO_TriggerType.Trigger)
                        mo.ObjectsDestroyed_num ++;
					


                    //Console.WriteLine("BSD: 3");


                    MO_addInitiatorToListOfPlayersWhoContributed(initiator, mo);

                    if (MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy].ContainsKey("RepairCrewEndTime_dt") && MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy]["RepairCrewEndTime_dt"] > currTime_dt) repairSpeedupFactor = 4;

                    //Console.WriteLine("BSD: 5");

                    if (mo.MOTriggerType == MO_TriggerType.Trigger)
                        MO_CalculateAndRecordTriggerObjectivesDamagePercent(mo);
                    //double oldDestroyedPercent = mo.DestroyedPercent;
                    else if (mo.MOTriggerType == MO_TriggerType.PointArea) MO_CalculateAndRecordPointareaObjectivesDamagePercent(mo);
					

                    //Console.WriteLine("BSD: 6");
                    if (st != null) Console.WriteLine("AreaPoint Stationary: {0}, {1}, {2}, {3}", st.Category, st.Name, st.Type, st.Title);
                    else Console.WriteLine("AreaPoint Building: {0}", name);

                    //break; //we only count it for one objective at most.  This avoids a runaway situation where one malfunctioning stationary killed like zillions of objectives somehow.
                }
            }

        }
        catch (Exception ex) { Console.WriteLine("PointArea Stationary/Building ERROR: " + ex.ToString()); }
    }


    //FOR BOMB EXPLOSIONS/Total up ordnance
    public void MO_HandlePointAreaObjectives(string title, double mass_kg, Point3d pos, AiDamageInitiator initiator)
    {
        try
        {
            //maddox.game.LandTypes landType = GamePlay.gpLandType(pos.x, pos.y);

            //For now, all things we handle below are on land, so if the land type is water we just
            //get out of here immediately
            //if (landType == maddox.game.LandTypes.WATER) return;  //Ok, doing ships & water type targets this doesn't really work.  So just X it out.

            //twcLogServer(null, "bombe 6", null);

            //So, if the damager is AI and damaging their own land area, we're not going to count it.
            //Reason is, some artillery continually hits the ground in the area where they're firing.

            //Console.WriteLine("main_PointArea_bomb");

            if (GamePlay == null) return;
            int terr = GamePlay.gpFrontArmy(pos.x, pos.y);
            if (initiator != null)
                if (initiator.Player == null || initiator.Player.Name() == null) //It's AI        
                    if (initiator.Actor != null && initiator.Actor.Army() == terr) return; //It's the same army as the territory that has been damaged



           
            string acType = "";
            if (initiator != null)
            {
                AiAircraft aircraft = initiator.Actor as AiAircraft;
                acType = Calcs.GetAircraftType(aircraft);

            }
            

            double aircraftCorrection = bomberCorrectionFactor(acType);

            mass_kg = mass_kg * aircraftCorrection;

            DateTime currTime_dt = DateTime.UtcNow;
            double repairSpeedupFactor = 1;

            foreach (string ID in MissionObjectivesList.Keys.ToList()) //avoiding 'change collection while looping through it' error vo .ToList() 2021-01
            {
                MissionObjective mo = MissionObjectivesList[ID];
                if (mo.MOTriggerType != MO_TriggerType.PointArea || !mo.IsEnabled) continue;
                //if (mo.OrdnanceRequiredToTrigger_kg == 0) continue; //0 means, don't use ordinance KG to determine destruction [nevermind, we can still track it even though not actively using it.  If 0

                if (Calcs.IsNaN(pos)) continue; 
                double dist = Calcs.CalculatePointDistance(pos, mo.Pos);

                //doing as <= radius instead of > radius continue avoids problem when dist is NaN
                if (dist <= mo.radius || dist <= mo.TriggerDestroyRadius)
                {
                    mo.fixDestructionValues();
                    double oldOONTkg = mo.OrdnanceOnTarget_kg;

                    MO_addInitiatorToListOfPlayersWhoContributed(initiator, mo);

                    if (dist > mo.TriggerDestroyRadius) mass_kg *= 0.333; //less damage effectiveness if inside radius but outside triggerradius
                    mo.OrdnanceOnTarget_kg += mass_kg;
                    mo.LastHitTime_UTC = DateTime.UtcNow;

                    if (MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy].ContainsKey("RepairCrewEndTime_dt") && MissionObjectivesTimes[(ArmiesE)mo.OwnerArmy]["RepairCrewEndTime_dt"] > currTime_dt) repairSpeedupFactor = 4;

                    //double oldDestroyedPercent = mo.DestroyedPercent;
                    MO_CalculateAndRecordPointareaObjectivesDamagePercent(mo);

                }

            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("handle PointArea bomb hit ERROR: " + ex.ToString());
        }


    }

    //returns TRUE if the point given puts the given objective too close to some other objective
    //checks all ENABLED objectives
    //checks both armies objectives if check_army == 0, otherwise the objectives of the army given
    public bool MO_oneObjectiveTooNearAnother(MissionObjective mo_check, Point3d check_pos, int check_army = 0)
    {
        try
        {
            foreach (string ID in MissionObjectivesList.Keys)
            {
                MissionObjective mo = MissionObjectivesList[ID];
                if (mo_check == mo) continue;
                if (!mo.IsEnabled) continue;
                if (check_army != 0 && check_army != mo.OwnerArmy) continue;
                double dist_m = Calcs.CalculatePointDistance(check_pos, mo.returnCurrentPosWithChief());
                if (dist_m < mo.radius + mo_check.radius) return true; //too close, the radii will overlap
            }
            return false;
        }
        catch (Exception ex) { Console.WriteLine("ERROR MO_oneObjectiveTooNearAnother! " + ex.ToString()); return false; }
    }
        

