//Various helpful calculations & formulas
public static class Calcs
{

    public static Random clc_random = new Random();

    public static double distance(double a, double b)
    {
        //This is a puzzling one but usually we are using distance to check if
        //two things are CLOSE to one another.  If one doesn't have a defined position
        //then it is definitely not CLOSE to anything.  The puzzle though is
        //sometimes we are checking whether two things are sufficiently FAR APART....
        if (Double.IsNaN(a) || Double.IsNaN(b)) return Double.PositiveInfinity;

        return (double)Math.Sqrt(a * a + b * b);

    }

    public static bool IsNaN (Point3d p)
    {
        if (Double.IsNaN(p.x) || Double.IsNaN(p.y) || Double.IsNaN(p.z)) return true;
        else return false;
    }
    public static bool IsNaN(Vector3d p)
    {
        if (Double.IsNaN(p.x) || Double.IsNaN(p.y) || Double.IsNaN(p.z)) return true;
        else return false;
    }

