    //Given two points lp1 & lp2 that determine a line, what is the distance between single point sp and that line?
    //if ax + by + c = 0 is the line equation, distance is
    //abs(ax + by + c)/sqrt(a^2 + b^2)
    //It returns values +/-.  + value means, the point is to the right side of the line, looking down the line from p1 to p2
    // - value means, to the left side of that line

    public static double PointToLineDistance(Point2d linePoint1, Point2d linePoint2, Point3d singlePoint)
    {
        return PointToLineDistance(linePoint1, linePoint2, new Point2d(singlePoint.x, singlePoint.y));
    }

    public static double PointToLineDistance(Point2d linePoint1, Point2d linePoint2, Point2d singlePoint)
    {

        if (linePoint1.x == linePoint2.x && linePoint1.y == linePoint2.y) return CalculatePointDistance(singlePoint, linePoint1); //Two points the same, not a line, but we can calculate the point distance
                                                                                                                                  //if (lp1.x == lp2.x) return Math.Sign( lp2.y-lp1.y) * (sp.x - lp1.x);                                                                                                                
        double a = linePoint2.y - linePoint1.y;
        double b = -(linePoint2.x - linePoint1.x);
        double c = (-b * linePoint1.y) - a * linePoint1.x;

        return (a * singlePoint.x + b * singlePoint.y + c) / distance(a, b);  //This will be + or - depending on the orientation of the sp and lp1/lp2.  YOu can use the +/- to determine which side of the line it's on relative to vector lp1 -> lp2
    }

    // vec1 + scalar*vec2
    public static Point3d addVectorwithScalarMultXY(Point3d vec1, Point3d vec2, double scalar )
    {
        return new Point3d(vec1.x + vec2.x * scalar, vec1.y + vec2.y * scalar, 0);
    }

    public static Point3d unitVectorXY(Point3d posA)
    {
        double dist = CoverCalcs.CalculatePointDistance(posA);
        if (dist == 0) return new Point3d(0, 0, 0); //the one error condition
        return new Point3d(posA.x / dist, posA.y / dist, 0);
    }

    //unit vector pointing from A to B
    public static Point3d unitVectorXY(Point3d posA, Point3d posB)
    {
        double dist = CoverCalcs.CalculatePointDistance(posA, posB);
        if (dist == 0) return new Point3d(0, 0, 0); //the one error condition
        Point3d unit_vec_PosAtoPosB = new Point3d((posB.x - posA.x) / dist, (posB.y - posA.y) / dist, 0);
        return unit_vec_PosAtoPosB ;
    }

    //unit vector perpendicular to A->B, going 90 degrees in a counterclockwise direction
    public static Point3d unitNormalVectorCCWXY(Point3d posA, Point3d posB) {
        Point3d unit_vec_PosAtoPosB = unitVectorXY(posA, posB);
        Point3d unit_vec_perpPosAtoPosB = new Point3d(-unit_vec_PosAtoPosB.y, unit_vec_PosAtoPosB.x, 0);
        return unit_vec_perpPosAtoPosB;
    }

    //unit vector perpendicular to A->B, going 90 degrees in a clockwise direction
    public static Point3d unitNormalVectorCWXY(Point3d posA, Point3d posB)
    {
        Point3d unit_vec_PosAtoPosB = unitVectorXY(posA, posB);
        Point3d unit_vec_perpPosAtoPosB = new Point3d(unit_vec_PosAtoPosB.y, -unit_vec_PosAtoPosB.x, 0);
        return unit_vec_perpPosAtoPosB;
    }

    //reverse direction of vector origin->pos, going 180 degrees in a opposite direction
    public static Point3d reverseVectorXY(Point3d pos)
    {
        return new Point3d(-pos.x, -pos.y,0);
    }

    //calculate angle between two vectors
    //returns a number 0 -> pi that is the angle.  Or NaN, which should never happen here but ??
    public static double angleBetweenVectorsXY_rad(Point3d pos1, Point3d pos2)
    {
        double dist1 = CalculatePointDistance(pos1);
        double dist2 = CalculatePointDistance(pos2);
        if (dist1 == 0 || dist2 == 0) return 0; //one of the vectors is zero length so this isn't a sensible question
        double intmd = (pos1.x * pos2.x + pos1.y * pos2.y) / (dist1 * dist2);
        if (intmd > 1 || intmd <0) intmd = Math.Round(intmd, 2); //sometimes there is a slight rounding error
        return Math.Acos(intmd);
    }

    //get unit vector A->B and C->D.  Then average those unit vectors, which gives the unit vector pointing halfway between the two, ie bisects the angle between the two  & is also a unit vector
    //There are two possible DIRECTIONS of this vector and this will return them so that (going CCW
    //around the circle, it will always be the order vec1 - BISECTOR - vec2
    //so if vec1 = -1,0, vec2 = 1,0 then bisector will be 0,1, NOT 0,-1
    public static Point3d bisectAngleUnitVectorXY(Point3d posA, Point3d posB, Point3d posC, Point3d posD)
    {
        Point3d vec1 = unitVectorXY(posA, posB);
        Point3d vec2 = unitVectorXY(posC, posD);
        Point3d bisectVec = unitVectorXY(new Point3d(vec1.x + vec2.x, vec1.y + vec2.y, 0));

        Point3d unvCCW = unitNormalVectorCCWXY(vec1, vec2);
        //the one degenerate case is if vec1 & vec2 are opposite directions, 180 degrees
        //then the bisectVec = (0,0,0)
        //in that case, we can go from tip of vec1 to tip of vec2 and take the perp unit vec of that
        if (Point3dEqualXY(bisectVec, new Point3d(0, 0, 0))){
            bisectVec = unvCCW;
        }
        //An additional degenerate case is if one of vec1 or vec1 is zero vector.  In that case we return the unit vec pointing the direction of the non-zero vector, a reasonable solution.
        //The other case is, both vec1 and vec2 are zero vector, in that case we return the zero vector, because ???

        //if (bisectVec.y < 0) bisectVec = reverseVectorXY(bisectVec); //We always return the vector pointing upwards, ie in the Quadrant 1 or 2, ie, with Y >= 0/
        double theta = Calcs.angleBetweenVectorsXY_rad(bisectVec, unvCCW);
        if (theta > Math.PI / 2) bisectVec = reverseVectorXY(bisectVec);

        return bisectVec;

    } 
    /**
      * Calculates the point of interception for one object starting at point
      * <code>a</code> with speed vector <code>v</code> and another object
      * starting at point <code>b</code> with a speed of <code>s</code>.
      * 
      * @see <a
      *      href="http://jaran.de/goodbits/2011/07/17/calculating-an-intercept-course-to-a-target-with-constant-direction-and-velocity-in-a-2-dimensional-plane/">Calculating
      *      an intercept course to a target with constant direction and velocity
      *      (in a 2-dimensional plane)</a>
      * 
      * @param a
      *            start vector of the object to be intercepted
      * @param v
      *            speed vector of the object to be intercepted
      * @param b
      *            start vector of the intercepting object
      * @param s
      *            speed of the intercepting object
      * @return Point3d where x,y is vvector of interception & z is time; or <code>null</code> if object cannot be
      *         intercepted or calculation fails
      * 
      * @author Jens Seiler
      * http://jaran.de/goodbits/2011/07/17/calculating-an-intercept-course-to-a-target-with-constant-direction-and-velocity-in-a-2-dimensional-plane/   
      */
    public static Point3d calculateInterceptionPoint(Point3d a, Point3d v, Point3d b, double s)
    {
        double ox = a.x - b.x;
        double oy = a.y - b.y;

        double h1 = v.x * v.x + v.y * v.y - s * s;
        double h2 = ox * v.x + oy * v.y;
        double t;
        if (h1 == 0)
        { // problem collapses into a simple linear equation 
            t = -(ox * ox + oy * oy) / (2 * h2);
        }
        else
        { // solve the quadratic equation
            double minusPHalf = -h2 / h1;

            double discriminant = minusPHalf * minusPHalf - (ox * ox + oy * oy) / h1; // term in brackets is h3
            if (discriminant < 0)
            { // no (real) solution then...
                return new Point3d(0, 0, 0); ; ;
            }

            double root = Math.Sqrt(discriminant);

            double t1 = minusPHalf + root;
            double t2 = minusPHalf - root;

            double tMin = Math.Min(t1, t2);
            double tMax = Math.Max(t1, t2);

            t = tMin > 0 ? tMin : tMax; // get the smaller of the two times, unless it's negative
            if (t < 0)
            { // we don't want a solution in the past
                return new Point3d(0, 0, 0); ;
            }
        }

        // calculate the point of interception using the found intercept time and return it
        return new Point3d(a.x + t * v.x, a.y + t * v.y, t);
    }


