	public static bool isOffMap(Point3d p){
		if (p.x <= minX - 12500 ||  //Same as players, 12500 'grace area', this is set in statsmission Stb_RemoveOffMapPlayers()
			p.y >= maxY + 12500 ||
			p.x >= maxX + 12500 ||
			p.y <= minY - 12500 ) 
			return true;
		return false;
			
	}

    //returns 2 if 1-2-3, 5 if 4-5-6, or the actual number +/-1 for all others
    //for radar returns etc
    public static int NoOfAircraft(int number, AiAirGroup airGroup = null)
    {
        var random_seeded = clc_random;

        //Using the seeded Random we'll get a predictable/repeatable 
        //count for a given airgroup, but it will be random
        //for different airgroups
        if (airGroup != null)
            random_seeded = new Random(airGroup.GetHashCode());

        if (number > 0 && number <= 3) 
        {
            return 2;
        }

        if (number <= 6) 
        {
            return 5;
        }

        int ranadd = random_seeded.Next(3) - 1;

        if (random_seeded.NextDouble() > 0.5) return number;
        return number + ranadd;
    }

    public static int NoOfAircraftBy5(int number)
    {
        int firstDecimal = 0;
        int higherDecimal = 0;

        higherDecimal = Math.DivRem(number, 10, out firstDecimal);

        if (firstDecimal > 3 && firstDecimal <= 8)
            firstDecimal = 5;
        else if (firstDecimal > 8)
            higherDecimal += 1;

        if (higherDecimal > 0)
            return (int)higherDecimal * 10;
        else
        {
            if (firstDecimal > 0 && firstDecimal <= 3) //If # is 1,2,3 then 50% of the time we get mixed up & get it wrong.  This is bec. radar can't always distinguish between 1,2,3 etc contacts.  "the height of the vertical displacement indicated formation size" - in other words it was a ROUGH estimate of the strength of the radar return, which they then turned into a guesstimate of how many a/c were in the formation.
            {
                firstDecimal = 2;
            }
            return (int)firstDecimal;
        }
    }

