        if (actor != null)
        {
            string type = (actor as AiCart).InternalTypeName(); // eg type = "bob:Aircraft.Bf-109E-3"
            string[] part = type.Trim().Split('.');

            if (part.Length > 0) return part[1]; // get the part after the "." in the type string
            else return type;
        }
        return result;
    }
	public static string CleanStationaryName(string name)
	{
		if (string.IsNullOrWhiteSpace(name)) return string.Empty;

		//Console.WriteLine("Cleaning stationary name: " + name);

		// 1. Clean up potential hidden non-breaking spaces from copy-pasting
		name = name.Replace('\u00A0', ' ');
		
		// 4. Convert underscores to spaces
		name = name.Replace("_", " ");
		// 4. Convert underscores to spaces
		name = name.Replace("-", " ");
		name = name.Replace(" GER1", " ");
		name = name.Replace(" UK1", " ");
		name = name.Replace(" GER", " ");
		name = name.Replace(" UK", " ");
		name = name.Replace(" 1", " ");
		name = name.Replace(" 9", " ");
		name = name.Replace("CamoNetPlaneBig", "Camo Net");
		name = name.Replace("CamoNetPlane", "Camo Net");

		// 2. Remove specific prefixes/substrings (case-insensitive for safety)
		string[] targets = { "Stationary", "buildings", "Environment", "TobrukBuilding", "Generic", "Industrial", "CargoPreset", "Weapons_", "Ammo_Vehicles", "Composition3", "Artillery", "Airfield", "Furniture", "Building England", "Building France", "Building Germany", "Building" };
		foreach (var target in targets)
		{
			name = Regex.Replace(name, target, "", RegexOptions.IgnoreCase);
		}

		// 3. Add spaces before capital letters, but skip successive capitals (acronyms)
        name = Regex.Replace(name, @"(?<=[a-z])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])", " ");

	

		// 5. Clean up extra internal or trailing spaces left over by removals
		name = Regex.Replace(name, @"\s+", " ").Trim();

		//Console.WriteLine("Cleaned stationary name: " + name);

		return name;
	}
	
	//the .Title seems to have a nonbreaking space between characters, to change to "." instead:
	//This can be used directly in the .mis file
	public static string cleanStationaryTitle (string title){
		if (title == null) return title;
		return title.Replace("\u00C2\u00A0", ".")
						.Replace("\u00A0", ".")
						.Replace("..", ".")
						.Trim();
	}

