    public static bool anyEnemyOrNeutralStationaries(IGamePlay GamePlay, double x, double y, double radius, int myArmy)
    {
        bool ret = false;
        string myCountry = "gb";
        if (myArmy == 2) myCountry = "de";

        foreach (GroundStationary sta in GamePlay.gpGroundStationarys(x, y, radius))
        {
            if (sta == null) continue;
            if (sta.country != myCountry) return true;
            //Console.WriteLine("Checking: " + sta.Name + " - " + sta.country);

        }
        return ret;
    }
    public static bool anyEnemyStationaries(IGamePlay GamePlay, double x, double y, double radius, int myArmy)
    {
        bool ret = false;
        string enemyCountry = "de";
        if (myArmy == 2) enemyCountry = "gb";

        foreach (GroundStationary sta in GamePlay.gpGroundStationarys(x, y, radius))
        {
            if (sta == null) continue;
            if (sta.country == enemyCountry) return true;
            //if (Console.WriteLine("Checking: " + sta.Name + " - " + sta.country);

        }
        return ret;
    }
    //Changes army of stationaries to match which side of the front line they are currently on
    //Leaves any nn items unchanged.  Also, won't change army of anything on neutral ground
    public static ISectionFile changeArmyToTerritory_SectionFile(ISectionFile f, maddox.game.IGamePlay GamePlay, AMission mission)
    {
        try
        {
            string key = "";
            string value = "";
            var armyLists = new List<List<string>>()
            {
                new List<string>() { "nn" },
                new List<string>() { "gb", "us", "fr", "gb", "ru", "rz" },
                new List<string>() { "de", "it", "hu", "fi", "ja", "ro", "sa" },
            };
            string[] mainArmy = { "nn", "gb", "de" };

            /*
            List<string> neutralarmies = new List<string>() { "nn" };
            string newarmy = "nn";

                var blueArmies = new List<string>() { "de", "it", "hu", "fi", "ja", "ro", "sa" };
                string mainBlueArmy = "de";
            
            
                var redArmies = new List<string>() { "gb", "us", "fr", "gb", "ru", "rz" };
            string mainRedArmy = "gb";
            */

            List<string> sections = new List<string>() { "Stationary" }; //could do the same with Birthplaces & maybe some other .mis file sections
            List<string> chiefs = new List<string>();

            foreach (string section in sections)
            {
                if (f.exist(section))
                {
                    int num = f.lines(section);
                    Console.WriteLine("{0}: {1} lines", section, num);
                    for (int i = 0; i < num; i++)
                    {

                        f.get(section, i, out key, out value);
                        //if (section == "Chiefs") chiefs.Add(key);
                        //Console.WriteLine("Old: {0:n0} {1} {2} ", i, key, value);

                        /* Example lines
                         * [Stationary]
                              Static9 Stationary.Environment.JerryCan_GER1_1 nn 264829.47 166242.72 659.10 
                              Static6 Stationary.Environment.JerryCan_GER1_1 nn 264819.81 166258.67 659.10 
                              Static5 Stationary.Radar.Wotan_II de 264833.13 166251.84 659.10 

                          Static9 is KEY and the remainder is VALUE.  dur.

                        */

                        string[] values = value.Trim().Split(null); //null splits on whitespace

                        double x = 0;
                        double y = 0;

                        if (!double.TryParse(values[2], out x)) continue;
                        if (!double.TryParse(values[3], out y)) continue;
                        if (x == 0 && y == 0) continue;

                        int terr = GamePlay.gpFrontArmy(x,y);

                        if (terr <= 0 || terr > 2) continue;

                        //Console.WriteLine("Changing terr: {0:n0} ({3:n0}, {4:n0}) {1} {2} ", terr, mainArmy[terr], armyLists[3-terr].ToString(), x, y );

                        foreach (string oldarmy in armyLists[3 - terr])
                        {
                            string newvalue = value.Replace(" " + oldarmy + " ", " " + mainArmy[terr] + " ");
                            //Console.WriteLine("Rep: {0:n0} {1} {2} ", newvalue.Length, newvalue.Substring(newvalue.Length - 3), newvalue.Substring(newvalue.Length - 2));
                            if (newvalue.Length >= 3 && newvalue.TrimEnd().Substring(newvalue.Length - 3) == " " + oldarmy)
                                newvalue = newvalue.TrimEnd().Substring(0, newvalue.Length - 2) + mainArmy[terr];
                            if (!newvalue.Equals(value))
                            {
                                //Console.WriteLine("New: {0:n0} {1} {2} ", i, key, newvalue);
                                f.set(section, key, newvalue);
                                break;
                            }
                        }
                    }
                }
            }
            
            Console.WriteLine("Returning: St: {0} Ch: {1}", f.lines("Stationary"), f.lines("Chiefs"));

            return f;
        }
        catch (Exception ex) { Console.WriteLine("Calcs.changeArmyToTerritory_SectionFile ERROR: " + ex.ToString()); return f; }
    }

    //Changes army of stationaries & chiefs, as requested, and also removes a random # of
    //waypoints at the beginning of the _Road in the section file, so the chiefs/mobile
    //objectives don't always start @ the same position & follow the exact same course each mission
    public static ISectionFile changeArmy_Waypoints_SectionFile(ISectionFile f, maddox.game.IGamePlay GamePlay, AMission mission, int changeToArmy, int maxWaypoints_remove = 0, double maxPercentWaypoints_remove = 0 )
    {
        try
        {
            string key = "";
            string value = "";
            List<string> oldarmies = new List<string>() { "nn" };
            string newarmy = "nn";
            if (changeToArmy == 1)
            {
                oldarmies = new List<string>() { "de", "it", "hu", "fi", "ja", "ro", "sa" };
                newarmy = "gb";
            }
            if (changeToArmy == 2)
            {
                oldarmies = new List<string>() { "gb", "us", "fr", "gb", "ru", "rz" };
                newarmy = "de";
            }
			
			int mis_fileversion = 1;


            List<string> sections = new List<string>() { "Chiefs", "Stationary" };
            List<string> chiefs = new List<string>();

			
			
					if (f.exist("MAIN")) { 
					    string val = f.get ("MAIN", "fileversion", "1");  
						if (val.Trim() == "2") mis_fileversion = 2;
						Console.WriteLine("Fileversion found! Now set to {0}", val);
					}
			

            foreach (string section in sections)
            {
                if (f.exist(section))
                {
                    int num = f.lines(section);
                    Console.WriteLine("{0}: {1} lines", section, num);
                    for (int i = 0; i < num; i++)
                    {

                        f.get(section, i, out key, out value);
                        if (section == "Chiefs") chiefs.Add(key);
                        //Console.WriteLine("section, #, key, value: {3} {0:n0} {1} {2} ", i, key, value, section);


                        foreach (string oldarmy in oldarmies)
                        {
                            string newvalue = value.Replace(" " + oldarmy + " ", " " + newarmy + " ");
                            //Console.WriteLine("Rep: {0:n0} {1} {2} ", newvalue.Length, newvalue.Substring(newvalue.Length - 3), newvalue.Substring(newvalue.Length - 2));
                            if (newvalue.Length >= 3 && newvalue.TrimEnd().Substring(newvalue.Length - 3) == " " + oldarmy)
                                newvalue = newvalue.TrimEnd().Substring(0, newvalue.Length - 2) + newarmy;
                            if (!newvalue.Equals(value))
                            {
                                //Console.WriteLine("New: {0:n0} {1} {2} ", i, key, newvalue);
                                f.set(section, key, newvalue);
                                break;
                            }
                        }
                    }
                }
            }
            Console.WriteLine("No. of Chiefs found: {0:n0}", chiefs.Count);
			Console.WriteLine("Fileversion: {0}", mis_fileversion);
            //delete the first $X lines in the Chief_Road, randomly up to amt requested
            //This has the effect of making the Chief start in a different place each mission - so not
            //predictable.
            foreach (string chief in chiefs)
            {
                string section = chief + "_Road";
                Console.WriteLine("Checking for: {0}", section);
                if (f.exist(section))
                {
                    int num = f.lines(section);
                    double maxNumToTrim = num * maxPercentWaypoints_remove / 100.0;
                    if (maxNumToTrim > maxWaypoints_remove) maxNumToTrim = maxWaypoints_remove;
                    int numWaypoints_remove_firsttry = clc_random.Next(Convert.ToInt32(Math.Round(maxNumToTrim)));
                    Console.WriteLine("Removing Waypoints in {3}: MaxnumtoTrim {0:n0} numWaypoints_remove {1:n0}, num total: {2:n0}", maxNumToTrim, numWaypoints_remove_firsttry, num, section);
					
					int numWayPoints_remove = numWaypoints_remove_firsttry;
					int wait_accumulator = 0; // in ver 1 the wait value is just a number in minutes.  In ver 2, it accumulates from the beginning of the _Road and 'waiting' is implicit if the time given is later than when the Chief arrives at that point.  Still '0' wait means to simply not wait.
					
					//In fileversion 1, first char 'S' indicates sub-points that are for individual vehicles or whatever
					//IN fileversion 2, the "real" points have 11 fields while "sub-points" have just 8
					//So we want to back up the _remove pointer to the preceding "real" point, avoiding the sub-points
					
					if (numWaypoints_remove_firsttry > 0) for (int i = numWaypoints_remove_firsttry - 1; i >= 0; i--)
						{
							f.get(section, i, out key, out value);
							if (mis_fileversion == 1) {
								//char firstNonBlank = value.FirstOrDefault(c => !char.IsWhiteSpace(c)); 
								//if (firstNonBlank == 'S') numWayPoints_remove --;								
								Console.WriteLine("ver1 - section {0} : i {1} : key {2} : value {3}", section, i, key, value);
								if (key == "S") numWayPoints_remove --;
								else break;
							} else {
								string[] words = value.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
								if (words.Length < 9) numWayPoints_remove --;
								else break;
								
							}
							
						}
					
					
					if (numWayPoints_remove < 0) numWayPoints_remove = 0;
					
					Console.WriteLine("Removing Waypoints in {3}: MaxnumtoTrim {0:n0} numWaypoints_remove(final) {1:n0}, num total: {2:n0}", maxNumToTrim, numWaypoints_remove_firsttry, num, section);
					
					
					Console.WriteLine("1. Lines in f {0}: {1}", section, f.lines(section));
					
					
					
                    if (numWayPoints_remove > 1) for (int i = numWayPoints_remove - 2; i >= 0; i--)
					{
						
						if (mis_fileversion == 2) {
							f.get(section, i, out key, out value);
							string[] words = value.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
							int result;
							if (words.Length > 8 && int.TryParse(words[7], out result) && result > wait_accumulator ) wait_accumulator = result;	
						}
						
						Console.WriteLine("Deleting {0} {1} wait_accumulator: {2}", section, i, wait_accumulator);
					
						f.delete(section, i);
					}
					
					Console.WriteLine("2. Lines in f {0}: {1}", section, f.lines(section));

					//g.setText(f.getText());
					//g.delete(section);
					
                    int newnum = f.lines(section);
					Console.WriteLine("Lines remaining in section: {0} {1}",section, newnum);
					if (mis_fileversion == 2) {
						ISectionFile g = GamePlay.gpCreateSectionFile();
						for (int i = 0; i < newnum; i++)
						{
							f.get(section, i, out key, out value);
							g.add(section, key, value);
						}
							
						f.delete(section);
						
						for (int i = 0; i < newnum; i++)
						{
							
							
							g.get(section, i, out key, out value);
							
							Console.WriteLine("Version 2, retrieved: {0} : {1} : {2} ", section, key, value);
							
							   Console.WriteLine("3. section i key value {0} : {1} : {2} : {3}", section, i, key, value);
							
								string[] words = value.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
								int result;
								if (words.Length > 8 && int.TryParse(words[7], out result)) {
									if (result >= wait_accumulator) {
										result -= wait_accumulator; //many times result == 0 which means "no wait".  negative numbers don't seem to hurt anything, probably ignored, but still best to avoid them as they are undefined						
										//wait_accumulator += clc_random.Next(7); //helping out the server a ltitle with extra wait times
									}
									words[7] = result.ToString();
									
								}
								
							f.add(section, key, string.Join(" ",words));	
								
								
								
								
							
							
							Console.WriteLine("Version 2, re-added: {0} : {1} : {2} ", section, key, string.Join(" ",words));
							
							
						}
						Console.WriteLine("3A. Lines in g {0}: {1}", section, g.lines(section));
						//f.setText(g.getText());
						Console.WriteLine("3B. Lines in f {0}: {1}", section, f.lines(section));
					}
					
					Console.WriteLine("4. Lines in f {0}: {1}", section, f.lines(section));
					
					newnum = f.lines(section);
                    for (int i = 0; i < newnum; i++)
                    {
						
                        f.get(section, i, out key, out value);
						
                        Console.WriteLine("Trimmed/updated: {0:n0} {1} {2} ", i, key, value);
						
						
                    }
                }
            }
            Console.WriteLine("Returning: St: {0} Ch: {1}", f.lines("Stationary"), f.lines("Chiefs"));

            return f;
        }
        catch (Exception ex) { Console.WriteLine("Calcs.printSectionFile ERROR: " + ex.ToString()); return f; }
    }
    //This is the # of buildings in the 312.5mx312.5m sector the point is in.
    public static int numBuildingsInSector(double x, double y)
    {
       return numBuildingsInSector(new Point3d(x, y, 0));
    }
        
    public static int numBuildingsInSector(Point3d pos)
    {
        try
        {
            int iX = Convert.ToInt32(pos.x) / 10000;
            int iY = Convert.ToInt32(pos.y) / 10000;
            if (iX < 0 || iY < 0 || iX >= 45 || iY >= 39) return 0; //calling outside this range causes memory protection fault/program termination

            int ct = twcLandscape.getBuildingCountInBlock(iX, iY);
            //Console.WriteLine("Bldg count in block {0:F0}, {1:F0} ({3},{4}): {2}", pos.x, pos.y, ct, iX, iY);
            if (ct == 0) return 0;
            int remX = Convert.ToInt32(pos.x) % 10000;
            int remY = Convert.ToInt32(pos.y) % 10000;
            int secX = remX / 32;
            int secY = remY / 32;
            int secNum = 32 * secY + secX;

            // up to 14 38 is good but 14 39 = protected memory
            // 45 10 = protected memory, 43 10 was good, 44 10 was good. 44 38 good
            //-1 0 no good. 

            //Formula for blocks is something like, normal (x,y) => (x/10000 + 4, y/10000 + 4)

            int[] blockOffset;
            int blockCount;
            int[] codes;
            int codeslength;

            int ct2 = twcLandscape.getBuildingBlocks(iX, iY, out blockOffset, out blockCount, out codes, out codeslength);
            //Console.WriteLine("X: {0} Y: {1}; BlockCount {2}, codeslength {3}, returnvalue: {4}.", iX, iY, blockCount, codeslength, ct2);
            if (blockCount == 0) return 0;
            if (blockOffset.Length <= secNum) return 0;
            //Console.WriteLine("code@secNum: {0}", blockOffset[secNum]);
            if (blockOffset[secNum] == -1) return 0;
            int begNum = blockOffset[secNum];
            int endNum = codeslength;
            for (int i = secNum + 1; i < blockOffset.Length; i++)
            {
                if (i % 32 == 0) Console.Write("\n");
                //Console.Write("{0}\t", blockOffset[i]);
                if (blockOffset[i] == -1) continue;
                endNum = blockOffset[i];
                break;
            }
            //Console.WriteLine("Result: {0}", endNum - begNum);
            return endNum - begNum;
        }
        catch (Exception ex) { Console.WriteLine("ERROR Calcs.numBuildingsInSector: " + ex.ToString()); return 0; }
    }

    //Checking just the POINT for water sometimes fails - there is a ship there or whatever.
    //This checks a small radius/area AROUND the point
    public static bool isPointInOrNearWater(maddox.game.IGamePlay GamePlay, Point3d pos, int radius_m = 10)
    {
        if (GamePlay.gpLandType(pos.x, pos.y) == maddox.game.LandTypes.WATER) return true;
        int steps = radius_m / 3;
        for (int i = 0; i < steps; i++)
        {
            Point3d checkPos = new Point3d();
            checkPos.x = pos.x + Math.Cos(i) * radius_m;
            checkPos.y = pos.y + Math.Sin(i) * radius_m;

            if (GamePlay.gpLandType(checkPos.x, checkPos.y) == maddox.game.LandTypes.WATER) return true;
        }
        return false;
    }

    //Just checks the one point
    public static bool isPointOnWaterSimple(maddox.game.IGamePlay GamePlay, Point3d pos)
    {
        if (GamePlay.gpLandType(pos.x, pos.y) == maddox.game.LandTypes.WATER) return true;
        
        return false;
    }

    private static int lSOFcount = 0;
    private static int lSOFruns = 0;

    //returnFile just returns the file, not loading it, so you can assemble several into one load
    public static ISectionFile loadSmokeOrFire(maddox.game.IGamePlay GamePlay, Mission mission, double x, double y, double z, string type = "BuildingFireSmall", double duration_s = 300, ISectionFile f = null, bool resetCount = false)
    {
        /* Sample: Static556 Smoke.Environment.Smoke1 nn 63718.50 187780.80 110.00 /hstart 16.24 
         possible types: Smoke1 Smoke2 BuildingFireSmall BuildingFireBig BigSitySmoke_0 BigSitySmoke_1

        Not sure if height is above sea level or above ground level.

        NOTE THAT as of CloD 4.57 you can create these objects but you can't get their handle back via groundstationarys to delete/remove/destroy them later.
        These are the only groundstationaries I know about that have this problem.

        Example of how to get groundstationaries within a distance of a given point--except not that it will NOT list any smoke or fire groundstationaries!
[code]
GroundStationary[] gs = GamePlay.gpGroundStationarys(250000, 252000, 1000); //Find all groundstationaries within 1000 meters of map coordinate (250000,252000)
[/code]
 */

        //if on water, NO craters and only occasional smoke
        if ((type.ToLower().Contains("crater") || type.ToLower().Contains("fire") ||
            (type.ToLower().Contains("smoke") && clc_random.Next(10) > 0))
            && isPointInOrNearWater(GamePlay, new Point3d(x, y, z), radius_m: 10)) return f;
        //GamePlay.gpLandType(x, y) == maddox.game.LandTypes.WATER) return f;
        lSOFruns++;
        if (resetCount) lSOFcount = 0;
        bool returnFile = true;
        //AMission mission = GamePlay as AMission;
        if (f == null) { f = GamePlay.gpCreateSectionFile(); returnFile = false; }
        string sect = "Stationary";
        string key = "Static_TWCLSOF_R" + lSOFruns + "_" + lSOFcount.ToString("F0");
        string value = "Smoke.Environment." + type + " nn " + x.ToString("0.00") + " " + y.ToString("0.00") + " " + (duration_s / 60).ToString("0.0") + " /hstart " + z.ToString("0.00");
        f.add(sect, key, value);
        lSOFcount++;
        if (mission.ON_TESTSERVER) Console.WriteLine("PostmissionLoad: LoadSmokeOrFire");
        if (!returnFile) GamePlay.gpPostMissionLoad(f);

        return f;


    }

