        string key = "Static_TWCLoadStatic_1";
        if (staticprefix != null) key = "Static_LS_" + staticprefix.Replace(' ','_') + "_1";
        string value = type + " " + side + " " + x.ToString("0.00") + " " + y.ToString("0.00") + " " + heading.ToString("0.0") + " /hstart " + z.ToString("0.00");
