    //gpGroundStationarys()
    //army, can specify 0=nn, 1=gb, 2=de which will remove the statics matching that country only
    //amry=-1 removes all
    public static void removeStatics(maddox.game.IGamePlay GamePlay, Mission msn, double x, double y, double radius_m, List<string> types_to_remove = null, int percentToRemove = 100, int army = -1, List<string> types_to_retain = null, bool preserveOnWater = false, bool replaceThem = false) //types is a SUBSTRING MATCH and CASE INSENSITIVE
    {
        //Task.Run(() => //Don't TASK RUN for anything that changes anything ==> server crashes!!!!
        {
            Console.WriteLine("mainmission removeStatics: Starting");
            try
            {
                ISectionFile f = GamePlay.gpCreateSectionFile();
				int count = 0;
                List<GroundStationary> ggList = new List<GroundStationary>(GamePlay.gpGroundStationarys(x, y, radius_m).ToList());
                if (ggList != null) foreach (GroundStationary gg in ggList) //all stationaries w/i given radiusr meters of this object
                {
                    //try/catch in loop so if something goes awry with one static it will continue with the rest
                    try
                    {
                        //var match = types_to_remove.FirstOrDefault(stringToCheck => stringToCheck.Contains(gg.Category));
                        try
                        {
                            //Console.WriteLine("removeStatics: Checking airfield item name: {0} category: {1} title: {2} type: {3} ", gg.Name, gg.Category, gg.Title, gg.Type.ToString());
                        }
                        catch (Exception ex)
                        {
                            if (gg != null) Console.WriteLine("removeStatics: Couldn't do something with name {0}", gg.Name);
                            else { Console.WriteLine("removeStatics: couldn't do something ERROR"); }
                        }
                        if (gg == null) continue;

                        if (army != -1)
                        {
                            if (army == 1 && gg.country != "gb") continue;
                            if (army == 2 && gg.country != "de") continue;
                            if (army == 0 && gg.country != "nn") continue;
                        }

                        bool match = false;
                        
                        //Don't include NAME for now as it now includes stuff like the objective ID
                        //string types = gg.Title + gg.Type.ToString() + gg.Name + gg.Category;
                        string types = gg.Title + gg.Type.ToString() + gg.Category;
                        if (types.Contains("tank") && msn.ON_TESTSERVER) Console.WriteLine("RemoveStatic - checking: {0} ", types);



                        if (types_to_remove == null) match = true;
                        else foreach (string s in types_to_remove)
                            {
                                if (types.ToLower().Contains(s.ToLower()))
                                {
                                    match = true;
                                    break;
                                }
                            }

                        if (match && types_to_retain != null) foreach (string s in types_to_retain)
                            {
                                if (types.ToLower().Contains(s.ToLower()))
                                {
                                    match = false;
                                    break;
                                }
                            }

                        if (match && preserveOnWater)
                        {
                            if (Calcs.isPointInOrNearWater(GamePlay, gg.pos, radius_m: 10)) match = false;
                        }

                        if (!match) continue;

                        if (types.Contains("tank") && msn.ON_TESTSERVER) Console.WriteLine("RemoveStatic - matched! Removing: {0} ", types);


                        if (clc_random.Next(100) > percentToRemove) continue; //remove only a certain percent, if requested
						
						if (replaceThem)
                        {
                            string typ = "Stationary.Environment.JerryCan_GER1_2";
                            string names = (gg.Type.ToString() + gg.Title).ToLower();
                            if (names.Contains("industrial")) typ = "Stationary.Environment.CamoNetPlaneBig";
                            else if (names.Contains("building")) typ = "Stationary.Environment.TentTroopLarge_GER1"; //
                            else if (names.Contains("airfield")) typ = "Stationary.Environment.CamoNetPlane";
                            else if (names.Contains("aircraft")) typ = "Stationary.GladiatorMkII";
                            else if (names.Contains("tent")) typ = "Stationary.Environment.CamoNetTank";
                            else if (names.Contains("car")) typ = "Stationary.Opel_Blitz_fuel";
                            else if (names.Contains("tank")) typ = "Stationary.Environment.TelegaBallon_UK1";
                            else if (names.Contains("truck")) typ = "Stationary.Ford_G917";
                            else if (clc_random.Next(5) < 1) typ = "Stationary.Environment.CamoNetPlane";

                            f = Calcs.makeStatic(f, GamePlay, msn, gg.pos.x, gg.pos.y, 0, typ, 0, "nn", staticprefix: "remove_enemy_neutral");
                        }
						
						
                        msn.Timeout(clc_random.Next(5, 360), () => { gg.Destroy(); });  //somewhat cheap way to avoid deleting items in ggList while looping through it, but also spreads the removal of stationaries over 5 mins or so instead of just zapping them all at once, which usually looks fake.
                        count++;
                    }
                    catch (Exception ex)
                    {
                        if (gg != null) Console.WriteLine("removeStatics Loop ERROR: Couldn't do something with name {0}", gg.Name);
                        else { Console.WriteLine("removeStatics Loop ERROR: couldn't do anything with a NULL static ERROR"); }
                    }
                }
                if (msn.ON_TESTSERVER) Console.WriteLine("removeStatics: Removed {0} items ... ", count);
				
				if (replaceThem)
                {
                    msn.Timeout(clc_random.Next(5, 120), () => {
                        GamePlay.gpPostMissionLoad(f);
                        f.save(msn.CLOD_PATH + msn.FILE_PATH + "/sectionfiles" + "/removeStatics_replaced_enemy_objects_" + clc_random.Next(1,100).ToString());
                    
                    });
                }
            }
            catch (Exception ex) { Console.WriteLine("removeStatics ERROR: " + ex.ToString()); }

        }  //); //end task.run();
    }

    //will either remove ALL or within a certain radius from a point
    //Can remove on enemy territory OR on neutral (clearNeutral == true)
    //Won't remove statics on THEIR OWN territory, regardless.  But will remove
    //armyToClear from neutral (if requested) and enemy terr.  
    public static void removeStaticsOnEnemyTerritory(maddox.game.IGamePlay GamePlay, Mission msn, List<string> types_to_remove = null, int percentToRemove = 100, int armyToRemove = -1, List<string> types_to_retain = null, bool preserveOnWater = false, bool clearNeutral = false,  double radius_m = 0,  Point3d center = new Point3d(), bool replaceThem = false, bool addX = false) //types is a SUBSTRING MATCH and CASE INSENSITIVE
    {
        
        {
            Console.WriteLine("mainmission removeStaticsOnEnemyTerritory: Starting");
            try
            {
                ISectionFile f = GamePlay.gpCreateSectionFile();
                int count = 0;
                List<GroundStationary> ggList = new List<GroundStationary>();

                if (addX) f = Calcs.makeStatic(f, GamePlay, msn, center.x, center.y, 0, "Stationary.Environment.Polotnische_X_white_1", 0, "nn", staticprefix: "remove_enemy_neutral");

                if (radius_m ==0 ) ggList = new List<GroundStationary>(GamePlay.gpGroundStationarys().ToList());
                else ggList = new List<GroundStationary>(GamePlay.gpGroundStationarys(center.x, center.y, radius_m).ToList());
                foreach (GroundStationary gg in ggList) //all stationaries w/i given radiusr meters of this object
                {
                    try
                    {

                        if (gg == null) continue;

                        if (armyToRemove != -1)
                        {
                            if (armyToRemove == 1 && gg.country != "gb") continue;
                            if (armyToRemove == 2 && gg.country != "de") continue;
                            if (armyToRemove == 0 && gg.country != "nn") continue;
                        }
						
						string cleanTitle = Calcs.cleanStationaryTitle( gg.Title);
						

                        //Don't include NAME for now as it now includes stuff like the objective ID "static3493" "replace_old_enemy_statics34898" but not really any helpful info about the TYPE of static 
                        //string types = gg.Title + gg.Type.ToString() + gg.Name + gg.Category;
                        string types = gg.Title + gg.Type.ToString() + gg.Category;
						//string ggNames = String.Format("{0} ::: {1} : {2} : {3} : {4}", cleanedTitle, gg.Name, gg.Title, gg.Type.ToString(), gg.Category);
						
						//if (msn.ON_TESTSERVER) Console.WriteLine("ggNames: {0} ", ggNames);
                        //if (types.Contains("tank") && msn.ON_TESTSERVER) Console.WriteLine("RemoveStatic - checking: {0} ", types);

                        bool match = false;
                        if (types_to_remove == null) match = true;
                        else foreach (string s in types_to_remove)
                            {
                                if (types.ToLower().Contains(s.ToLower()))
                                {
                                    match = true;
                                    break;
                                }
                            }

                        if (match && types_to_retain != null) foreach (string s in types_to_retain)
                            {
                                if (types.ToLower().Contains(s.ToLower()))
                                {
                                    match = false;
                                    break;
                                }
                            }

                        if (match && preserveOnWater)
                        {
                            if (Calcs.isPointInOrNearWater(GamePlay, gg.pos, radius_m: 10)) match = false;
                        }

                        if (!match) continue;

                        if (types.Contains("tank") && msn.ON_TESTSERVER) Console.WriteLine("RemoveStatic - matched! Removing: {0} ", types);

                        if (clc_random.Next(100) > percentToRemove) continue; //remove only a certain percent, if requested

                        int terr = GamePlay.gpFrontArmy(gg.pos.x, gg.pos.y);

                        if (!clearNeutral && terr == 0) continue;

                        int ggarmy = -1;
                        if (gg.country == "gb") ggarmy = 1;
                        if (gg.country == "de") ggarmy = 2;
                        if (ggarmy == -1) continue;
                        if (ggarmy == terr) continue;
                        if (replaceThem)
                        {
							/*
                            string typ = "Stationary.Environment.JerryCan_GER1_2";
                            string names = (gg.Type.ToString() + gg.Title).ToLower();
                            if (names.Contains("industrial")) typ = "Stationary.Environment.CamoNetPlaneBig";
                            else if (names.Contains("building")) typ = "Stationary.Environment.TentTroopLarge_GER1"; //
                            else if (names.Contains("airfield")) typ = "Stationary.Environment.CamoNetPlane";
                            else if (names.Contains("aircraft")) typ = "Stationary.GladiatorMkII";
                            else if (names.Contains("tent")) typ = "Stationary.Environment.CamoNetTank";
                            else if (names.Contains("car")) typ = "Stationary.Opel_Blitz_fuel";
                            else if (names.Contains("tank")) typ = "Stationary.Environment.TelegaBallon_UK1";
                            else if (names.Contains("truck")) typ = "Stationary.Ford_G917";
                            else if (clc_random.Next(5) < 1) typ = "Stationary.Environment.CamoNetPlane";
							*/
							
							//we keep any nn statics as nn, but switch de to gb and vice-versa
							//Usually most statics are nn but a few de or gb to give targets
							//a little more visibility in the sim
							//But we can't have wrong army on wrong terr or attacked by AA etc....
							string side = Mission.ArmiesSection[0];
							if (ggarmy > 0) side = Mission.ArmiesSection[terr];

                            f = Calcs.makeStatic(f, GamePlay, msn, gg.pos.x, gg.pos.y, 0, cleanTitle, 0, side, staticprefix: "replace_enemy_statics");
							if (msn.ON_TESTSERVER) Console.WriteLine("Replacing with new static {0} {1}", cleanTitle, side );
                        }
						
						 
						
                        msn.Timeout(clc_random.Next(5, 120), () => { gg.Destroy();  });  //somewhat cheap way to avoid deleting items in ggList while looping through it, but also spreads the removal of stationaries over 5 mins or so instead of just zapping them all at once, which usually						looks fake.
						if (msn.ON_TESTSERVER) Console.WriteLine("Removing static {0} {1} {2}", cleanTitle, ggarmy, Mission.ArmiesSection[ggarmy] );
                        count++;
                    }
                    catch (Exception ex)
                    {
                        if (gg != null) Console.WriteLine("removeEnemyStatics Loop ERROR: Couldn't do something with name {0}", gg.Name);
                        else { Console.WriteLine("removeEnemyStatics Loop ERROR: couldn't do anything with a NULL static ERROR"); }
                    }
                }
                if (replaceThem)
                {
                    msn.Timeout(clc_random.Next(5, 120), () => {
                        GamePlay.gpPostMissionLoad(f);
                        f.save(msn.CLOD_PATH + msn.FILE_PATH + "/sectionfiles" + "/removeStaticsOnEnemyTerritory_replaced_enemy_objects_" + clc_random.Next(1,100).ToString());
                    
                    });
                }
                Console.WriteLine("removeEnemyStatics: Removed {0} items ... ", count);
            }
            catch (Exception ex) { Console.WriteLine("removeEnemyStatics ERROR: " + ex.ToString()); }

        }  //); //end task.run();
    }


