                k = "NORMFLY"; v = String.Format("{0} {1} {2} {3}", new object[] { p4.x, p4.y, p4.z, vel_kmh}); f.add(s, k, v);
                if (clc_random.NextDouble() < airportBombChance || gap_targ.Length>0)
                {
